/* Cytaty z aktow prawnych – generowane automatycznie z PDF-ow w akty/ (build_quotes.py).
   kind: 'akt' = doslowny cytat przepisu; 'norma'/'ue' = cytat niedostepny. */
window.QUOTES = {"1": [{"ref": "N SEP-E-004:2014 – definicja szybu kablowego", "kind": "norma"}], "2": [{"ref": "§ 27 RPB – obiekty wymagające stosowania stałych urządzeń gaśniczych", "kind": "akt", "act": "rpb", "label": "§ 27", "text": "§ 27. […] 2) muzeach oraz zabytkach budowlanych, wyznaczonych przez Generalnego Konserwatora Zabytków w uzgodnieniu z Komendantem Głównym Państwowej Straży Pożarnej; 3) ośrodkach elektronicznego przetwarzania danych o znaczeniu krajowym. 2. Stosowanie stałych samoczynnych urządzeń gaśniczych wodnych jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych, w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 8000 m2, b) wielokondygnacyjnych, w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 5000 m2; 2) w budynkach o liczbie miejsc służących celom gastronomicznym powyżej 600; 3) budynkach użyteczności publicznej wysokościowych; 4) budynkach zamieszkania zbiorowego wysokościowych. 3. […]"}], "3": [{"ref": "PN-EN 12845 – urządzenia tryskaczowe, oddzielenia", "kind": "norma"}], "5": [{"ref": "PN-EN 13200-1:2013 – obiekty widowiskowe, ewakuacja", "kind": "norma"}], "6": [{"ref": "§ 234 WT – ściany oddzielenia przeciwpożarowego a przekrycie dachu", "kind": "akt", "act": "wt", "label": "§ 234", "text": "§ 234. 1. Przepusty instalacyjne w elementach oddzielenia przeciwpożarowego powinny mieć klasę odporności ogniowej (E I) wymaganą dla tych elementów. 2. Dopuszcza się nieinstalowanie przepustów, o których mowa w ust. 1, dla pojedynczych rur instalacji wodnych, kanalizacyjnych i ogrzewczych, wprowadzanych przez ściany i stropy do pomieszczeń higienicznosanitarnych. 3. Przepusty instalacyjne o średnicy większej niż 0,04 m w ścianach i stropach pomieszczenia zamkniętego, dla których wymagana klasa odporności ogniowej jest nie niższa niż E I 60 lub R E I 60, a niebędących elementami oddzielenia przeciwpożarowego, powinny mieć klasę odporności ogniowej (E I) ścian i stropów tego pomieszczenia. 4. Przejścia instalacji przez zewnętrzne ściany budynku, znajdujące się poniżej poziomu terenu, powinny być zabezpieczone przed możliwością przenikania gazu do wnętrza budynku."}], "8": [{"ref": "§ 216, § 230 WT – warunki obniżenia wymagań przy zastosowaniu urządzeń gaśniczych", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. […] 3) ścian zewnętrznych w budynku niskim ZL IV. 3. Dopuszcza się stosowanie w budynku PM ścian zewnętrznych klasy D z rdzeniem klasy E z uwagi na reakcję na ogień, jeżeli okładzina wewnętrzna jest niepalna, a ściana jest nierozprzestrzeniająca ognia przy działaniu ognia od strony elewacji. 4. Dopuszcza się stosowanie w budynku PM ścian wewnętrznych klasy D z uwagi na reakcję na ogień. 5. W ścianach zewnętrznych budynku ZL II dopuszcza się, z zastrzeżeniem ust. 8, zastosowanie izolacji cieplnej palnej, jeżeli osłaniająca ją od wewnątrz okładzina jest niepalna i ma klasę odporności ogniowej co najmniej: 1) w budynku klasy odporności pożarowej „B” – E I 60; 2) w budynku klasy odporności pożarowej „C” i „D” – E I 30. 6. Dopuszcza się stosowanie klap dymowych z materiałów łatwo zapalnych w dachach i stropodachach. 7. […]"}], "9": [{"ref": "PN-EN 12845 / NFPA – instalacje tryskaczowe ESFR", "kind": "norma"}], "10": [{"ref": "PN-EN 15004 – stałe urządzenia gaśnicze gazowe, czas retencji", "kind": "norma"}], "11": [{"ref": "PN-EN 13501-6 – klasyfikacja reakcji na ogień kabli (indeks „ca”)", "kind": "norma"}], "12": [{"ref": "§ 271, § 275 WT – usytuowanie i strefy pożarowe garaży", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20 2. […]"}], "14": [{"ref": "PN-EN 12845 – rozmieszczenie tryskaczy", "kind": "norma"}], "15": [{"ref": "§ 37 RPB – ocena zagrożenia wybuchem i wyznaczanie stref", "kind": "norma"}], "16": [{"ref": "PN-EN 12845 / § 20 RPB – zasilanie hydrantów wewnętrznych", "kind": "norma"}], "17": [{"ref": "N SEP-E-005 – przeciwpożarowy wyłącznik prądu (PWP)", "kind": "norma"}], "21": [{"ref": "§ 230 ust. 2 WT – obniżenie klasy odporności pożarowej przy SUG wodnym", "kind": "akt", "act": "wt", "label": "§ 230", "text": "2. W budynku jednokondygnacyjnym wielkości stref pożarowych PM, z wyjątkiem garażu, nie ogranicza się, pod warunkiem zastosowania stałych samoczynnych urządzeń gaśniczych wodnych i samoczynnych urządzeń oddymiających."}], "22": [{"ref": "§ 256 WT – długość dojść ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "§ 256. […] 3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej. 4. […]"}], "23": [{"ref": "PN-EN ISO 7010:2012 – znaki bezpieczeństwa", "kind": "norma"}], "25": [{"ref": "§ 249 WT – przeszklenia w narożach i przy oddzieleniach", "kind": "akt", "act": "wt", "label": "§ 249", "text": "§ 249. 1. Ściany wewnętrzne i stropy stanowiące obudowę klatki schodowej lub pochylni powinny mieć klasę odporności ogniowej określoną zgodnie z § 216, jak dla stropów budynku. 2. (uchylony). 3. Biegi i spoczniki schodów oraz pochylnie służące do ewakuacji powinny być wykonane z materiałów niepalnych i mieć klasę odporności ogniowej co najmniej: 1) w budynkach o klasie odporności pożarowej „A”, „B” i „C” – R 60; 2) w budynkach o klasie odporności pożarowej „D” i „E” – R 30. 4. Wymaganie klasy odporności ogniowej, o którym mowa w ust. 3, nie dotyczy klatek schodowych wydzielonych na każdej kondygnacji przedsionkami przeciwpożarowymi oraz schodów na antresolę w pomieszczeniu, w którym się ona znajduje, jeżeli antresola ta jest przeznaczona do użytku nie więcej niż 10 osób. 5. […]"}], "26": [{"ref": "PN-B / wytyczne oddymiania klatek schodowych", "kind": "norma"}], "27": [{"ref": "§ 19–20 RPB – zapas wody dla instalacji wodociągowej przeciwpożarowej", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. […] 3) przy wejściu do pomieszczeń magazynowych lub technicznych o powierzchni przekraczającej 200 m2 i gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, usytuowanych w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II, ZL III lub ZL V, znajdującej się w budynku niskim albo średniowysokim. 4. W strefach pożarowych, o których mowa w ust. 3 pkt 1, i przy wejściu do pomieszczeń magazynowych lub technicznych, o których mowa w ust. 3 pkt 3, dopuszcza się stosowanie hydrantów 33, jeżeli gęstość obciążenia ogniowego w tych strefach i tych pomieszczeniach magazynowych lub technicznych nie przekracza 1000 MJ/m2. 5. Wymagania, o których mowa w ust. 2, nie dotyczą wolno stojących garaży na terenach zamkniętych podległych Ministrowi Obrony Narodowej. 6.5) Zawory 52 muszą być stosowane w budynkach wysokich i wysokościowych o więcej niż jednej kondygnacji nadziemnej."}], "29": [{"ref": "§ 12 RW – promień zewnętrznej krawędzi łuku drogi pożarowej ≥ 11 m", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 9. Droga pożarowa powinna zapewniać przejazd bez cofania lub powinna być zakończona placem manewrowym o wymiarach 20 m x 20 m, względnie można przewidzieć inne rozwiązania umożliwiające zawrócenie pojazdu, z zastrzeżeniem ust. 10. 10. Dopuszcza się wykonanie odcinka drogi pożarowej o długości nie większej niż 15 m, z którego wyjazd jest możliwy jedynie przez cofanie pojazdu. 11. Najmniejszy promień zewnętrznego łuku drogi pożarowej nie może wynosić mniej niż 11 m. 12. Drogi pożarowe oraz place manewrowe w miejscach innych niż wymienione w ust. 2 i 3 mogą być usytuowane w odległości mniejszej niż 5 m od chronionego budynku, pod warunkiem że ściana zewnętrzna budynku na tym odcinku oraz w odległości do 5 m od niego posiada klasę odporności ogniowej wymaganą dla ściany oddzielenia pożarowego tego budynku."}], "30": [{"ref": "PN-EN 1838 – oświetlenie awaryjne; § 181 WT", "kind": "norma"}], "31": [{"ref": "§ 37 RPB – pomieszczenia uznane za zagrożone wybuchem", "kind": "akt", "act": "rpb", "label": "§ 37", "text": "§ 37. […] U. poz. 1004 oraz z 2006 r. poz. 836)6). 6. Klasyfikację stref zagrożenia wybuchem określa Polska Norma dotycząca zapobiegania wybuchowi i ochronie przed wybuchem. 7. Pomieszczenie, w którym może wytworzyć się mieszanina wybuchowa, powstała z wydzielającej się takiej ilości palnych gazów, par, mgieł lub pyłów, której wybuch mógłby spowodować przyrost ciśnienia w tym pomieszczeniu przekraczający 5 kPa, określa się jako pomieszczenie zagrożone wybuchem. 8. Wytyczne w zakresie określania przyrostu ciśnienia w pomieszczeniu, jaki mógłby zostać spowodowany przez wybuch, określa załącznik do rozporządzenia. 9. W pomieszczeniu należy wyznaczyć strefę zagrożenia wybuchem, jeżeli może w nim występować mieszanina wybuchowa o objętości co najmniej 0,01 m3 w zwartej przestrzeni. […]"}], "32": [{"ref": "§ 239 WT – szerokość drzwi ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 239", "text": "§ 239. 1. Łączną szerokość drzwi w świetle, stanowiących wyjścia ewakuacyjne z pomieszczenia, należy obliczać proporcjonalnie do liczby osób mogących przebywać w nim równocześnie, przyjmując co najmniej 0,6 m szerokości na 100 osób, przy czym najmniejsza szerokość drzwi w świetle ościeżnicy powinna wynosić 0,9 m, a w przypadku drzwi służących do ewakuacji do 3 osób – 0,8 m. 2. Drzwi stanowiące wyjście ewakuacyjne powinny otwierać się na zewnątrz pomieszczeń: 1) zagrożonych wybuchem; 2) do których jest możliwe niespodziewane przedostanie się mieszanin wybuchowych lub substancji trujących, duszących bądź innych, mogących utrudnić ewakuację; 3) przeznaczonych do jednoczesnego przebywania ponad 50 osób; 4) przeznaczonych dla ponad 6 osób o ograniczonej zdolności poruszania się. 3. […]"}], "33": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego i powiększenia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "34": [{"ref": "PN-EN 12101-6 – systemy różnicowania ciśnień", "kind": "norma"}], "35": [{"ref": "§ 212 WT – klasa odporności pożarowej budynku", "kind": "akt", "act": "wt", "label": "§ 212", "text": "§ 212. 1. Ustanawia się pięć klas odporności pożarowej budynków lub ich części, podanych w kolejności od najwyższej do najniższej i oznaczonych literami: „A”, „B”, „C”, „D” i „E”, a scharakteryzowanych w § 216. 2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A” 3. Dopuszcza się obniżenie wymaganej klasy odporności pożarowej w budynkach wymienionych w poniższej tabeli do poziomu w niej określonego. Liczba kondygnacji nadziemnych ZL I ZL II ZL III 1 2 3 4 1 „D” „D” „D” 2*) „C” „C” „D” *) Gdy poziom stropu nad pierwszą kondygnacją nadziemną jest na wysokości nie większej niż 9 m nad poziomem terenu. 4. […]"}], "36": [{"ref": "§ 13 RW – prześwit nad/pod drogą pożarową", "kind": "akt", "act": "rw", "label": "§ 13", "text": "§ 13. […] 2) na odcinku o długości 15 m od miejsc doprowadzenia jej do budynku, o których mowa w § 12 ust. 6 pkt 2. 2. W obrębie miasta oraz na terenie działki, na której jest usytuowany obiekt budowlany, o którym mowa w § 12 ust. 1 pkt 3 i 4, droga pożarowa powinna umożliwiać przejazd pojazdów o nacisku osi na nawierzchnię jezdni co najmniej 100 kN (kiloniutonów), a jej minimalna szerokość w miejscach innych niż wymienione w ust. 1 nie może być mniejsza niż 3,5 m. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9069 — Poz. 1030 3. Na terenach innych niż wymienione w ust. 2 droga pożarowa powinna umożliwiać przejazd pojazdów o nacisku osi na nawierzchnię jezdni co najmniej 50 kN, a jej minimalna szerokość w miejscach innych niż wymienione w ust. 1 nie może być mniejsza niż 3 m. 4. […]"}], "37": [{"ref": "§ 3–5 RW – przypadki niewymagające zewnętrznego zaopatrzenia w wodę", "kind": "akt", "act": "rw", "label": "§ 3", "text": "§ 3. […] 2) budynków użyteczności publicznej i zamieszkania zbiorowego oraz obiektów budowlanych produkcyjnych i magazynowych, znajdujących się poza granicami jednostek osadniczych wymienionych w pkt 1, o kubaturze brutto przekraczającej 2 500 m3 lub o powierzchni przekraczającej 500 m2, z wyjątkiem stacji paliw płynnych ze zbiornikami o łącznej pojemności do 200 m3 i stacji gazu płynnego; 3) obiektów budowlanych niebędących budynkami, przeznaczonych na potrzeby użyteczności publicznej lub do zamieszkania zbiorowego, w których znajduje się strefa pożarowa o powierzchni przekraczającej 1 000 m2 lub przeznaczona do jednoczesnego przebywania ponad 50 osób; 4) obiekty budowlane gospodarki rolnej o powierzchni strefy pożarowej przekraczającej 1 000 m2. 2. […]"}], "38": [{"ref": "§ 5 RW – wymagana ilość wody do zewnętrznego gaszenia pożaru", "kind": "akt", "act": "rw", "label": "§ 5", "text": "§ 5. 1. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla budynków użyteczności publicznej i zamieszkania zbiorowego oraz innych obiektów budowlanych o takim przeznaczeniu, służąca do zewnętrznego gaszenia pożaru, wynosi: 1) dla budynku o kubaturze brutto do 5 000 m3 i o powierzchni wewnętrznej do 1 000 m2 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 2) dla budynków niewymienionych w pkt 1 — 20 dm3/s łącznie z co najmniej dwóch hydrantów o średnicy 80 mm lub 200 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 3) dla obiektów wymienionych w § 3 ust. 1 pkt 3 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym. 2. […]"}], "40": [{"ref": "PKN-CEN/TS 54-14 – systemy sygnalizacji pożarowej, poziomy dźwięku", "kind": "norma"}], "41": [{"ref": "art. 56 ustawy – Prawo budowlane", "kind": "akt", "act": "pb", "label": "art. 56", "text": "Art. 56. 1. Inwestor, w stosunku do którego nałożono obowiązek uzyskania pozwolenia na użytkowanie obiektu budowlanego, jest obowiązany zawiadomić, zgodnie z właściwością wynikającą z przepisów szczególnych, organy: 1) (uchylony) 2) Państwowej Inspekcji Sanitarnej, 3) (uchylony) 4) Państwowej Straży Pożarnej – o zakończeniu budowy obiektu budowlanego i zamiarze przystąpienia do jego użytkowania. Organy zajmują stanowisko w sprawie zgodności wykonania obiektu budowlanego z projektem budowlanym. 1a. Przepisy ust. 1 stosuje się również w przypadku, gdy projekt budowlany obiektu budowlanego nieobjętego obowiązkiem uzyskania pozwolenia na użytkowanie wymagał uzgodnienia pod względem ochrony przeciwpożarowej lub wymagań higienicznych i zdrowotnych. 2. […]"}], "42": [{"ref": "§ 10 RW – rozmieszczenie hydrantów zewnętrznych", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 2) od zewnętrznej krawędzi jezdni drogi lub ulicy — do 15 m; 3) najbliższego hydrantu od chronionego obiektu budowlanego — do 75 m; 4) innych niż wymienione w pkt 3 hydrantów wymaganych do ochrony obiektu budowlanego — do 150 m; 5) od ściany chronionego budynku — co najmniej 5 m. 7. Poza obszarami miejskimi odległość między hydrantami powinna być dostosowana do gęstości istniejącej i planowanej zabudowy. 8. Wydajność nominalna hydrantu zewnętrznego, przy ciśnieniu nominalnym 0,2 MPa mierzonym na zaworze hydrantowym podczas poboru wody, w zależności od jego średnicy nominalnej (DN), nie może być mniejsza niż: 1) dla hydrantu nadziemnego DN 80 — 10 dm3/s; 2) dla hydrantu nadziemnego DN 100 — 15 dm3/s; 3) dla hydrantu podziemnego DN 80 — 10 dm3/s; 4) dla hydrantu nadziemnego DN 80 na sieci, o której mowa w § 9 ust. 2 — 5 dm3/s. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9067 — Poz. 1030 9. […]"}], "43": [{"ref": "§ 4 RPB – obowiązki właścicieli/zarządców", "kind": "akt", "act": "rpb", "label": "§ 4", "text": "§ 4. […] 4) oznakowują znakami zgodnymi z Polskimi Normami: a) drogi i wyjścia ewakuacyjne z wyłączeniem budynków mieszkalnych oraz pomieszczenia, w których zgodnie z przepisami techniczno-budowlanymi są wymagane co najmniej 2 wyjścia ewakuacyjne, w sposób zapewniający dostarczenie informacji niezbędnych do ewakuacji, b) miejsca usytuowania urządzeń przeciwpożarowych i gaśnic, c) miejsca usytuowania elementów sterujących urządzeniami przeciwpożarowymi, d) miejsca usytuowania nasady umożliwiającej zasilanie instalacji wodociągowej przeciwpożarowej, kurków głównych instalacji gazowej oraz materiałów niebezpiecznych pożarowo, e) pomieszczenia i tereny z materiałami niebezpiecznymi pożarowo, f) drabiny ewakuacyjne, rękawy ratownicze, pojemniki z maskami ucieczkowymi, miejsca zbiórki do ewakuacji, miejsca lokalizacji kluczy do wyjść ewakuacyjnych, g) dźwigi dla straży pożarnej, h) przeciwpożarowe zbiorniki wodne, zbiorniki technologiczne stanowiące uzupełniające źródło wody do celów przeciwpożarowych, punkty poboru wody, stanowiska czerpania wody, i) drzwi przeciwpożarowe, j) drogi pożarowe, k) miejsca zaklasyfikowane jako strefy zagrożenia wybuchem; […]"}], "44": [{"ref": "PN-EN 12101-2 – klasyfikacja klap dymowych", "kind": "norma"}], "45": [{"ref": "PN-EN 13501-1 – klasyfikacja reakcji na ogień", "kind": "norma"}], "47": [{"ref": "rozp. MG – bazy i stacje paliw; PN-EN 13565 – urządzenia pianowe", "kind": "norma"}], "49": [{"ref": "PKN-CEN/TS 54-14:2006", "kind": "norma"}], "50": [{"ref": "§ 256 WT – długość dojść ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "§ 256. […] 3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej. 4. […]"}], "51": [{"ref": "§ 239 WT – szerokość drzwi ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 239", "text": "§ 239. 1. Łączną szerokość drzwi w świetle, stanowiących wyjścia ewakuacyjne z pomieszczenia, należy obliczać proporcjonalnie do liczby osób mogących przebywać w nim równocześnie, przyjmując co najmniej 0,6 m szerokości na 100 osób, przy czym najmniejsza szerokość drzwi w świetle ościeżnicy powinna wynosić 0,9 m, a w przypadku drzwi służących do ewakuacji do 3 osób – 0,8 m. 2. Drzwi stanowiące wyjście ewakuacyjne powinny otwierać się na zewnątrz pomieszczeń: 1) zagrożonych wybuchem; 2) do których jest możliwe niespodziewane przedostanie się mieszanin wybuchowych lub substancji trujących, duszących bądź innych, mogących utrudnić ewakuację; 3) przeznaczonych do jednoczesnego przebywania ponad 50 osób; 4) przeznaczonych dla ponad 6 osób o ograniczonej zdolności poruszania się. 3. […]"}], "52": [{"ref": "§ 227 ust. 4 pkt 1 WT – powiększenie strefy pożarowej ZL o 100%", "kind": "akt", "act": "wt", "label": "§ 227", "text": "4. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w ust. 1, z wyjątkiem stref pożarowych w wielokondygnacyjnych budynkach wysokich (W) i wysokościowych (WW), pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 100%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 100%. Przy jednoczesnym stosowaniu urządzeń wymienionych w pkt 1 i 2 dopuszcza się powiększenie powierzchni stref pożarowych o 200%."}], "53": [{"ref": "§ 12 ust. 9 RW – zbliżenie drogi pożarowej do ściany", "kind": "akt", "act": "rw", "label": "§ 12", "text": "9. Droga pożarowa powinna zapewniać przejazd bez cofania lub powinna być zakończona placem manewrowym o wymiarach 20 m x 20 m, względnie można przewidzieć inne rozwiązania umożliwiające zawrócenie pojazdu, z zastrzeżeniem ust."}], "54": [{"ref": "§ 37 RPB – pomieszczenia uznane za zagrożone wybuchem", "kind": "akt", "act": "rpb", "label": "§ 37", "text": "§ 37. 1. W obiektach i na terenach przyległych, gdzie są prowadzone procesy technologiczne z użyciem materiałów mogących wytworzyć mieszaniny wybuchowe lub w których materiały takie są magazynowane, dokonuje się oceny zagrożenia wybuchem. 2. Ocena zagrożenia wybuchem obejmuje wskazanie pomieszczeń zagrożonych wybuchem, wyznaczenie w pomieszczeniach i przestrzeniach zewnętrznych odpowiednich stref zagrożenia wybuchem wraz z opracowaniem graficznej dokumentacji klasyfikacyjnej oraz wskazanie czynników mogących w nich zainicjować zapłon. 3. Graficzna dokumentacja klasyfikacyjna zawiera plany sytuacyjne obrazujące rodzaj i zasięg stref zagrożenia wybuchem oraz lokalizację i identyfikację źródeł emisji, zgodnie z zasadami określonymi w Polskich Normach. 4. Oceny zagrożenia wybuchem dokonują: inwestor, projektant lub użytkownik decydujący o procesie technologicznym. 5. […]"}], "55": [{"ref": "§ 2 ust. 1 pkt 9 RPB – definicja urządzeń przeciwpożarowych", "kind": "akt", "act": "rpb", "label": "§ 2", "text": "§ 2. 1. Ilekroć w rozporządzeniu jest mowa o: 1) materiałach niebezpiecznych pożarowo ‒ należy przez to rozumieć: a) gazy palne, b) ciecze palne o temperaturze zapłonu poniżej 328,15 K (55ºC), c) materiały wytwarzające w zetknięciu z wodą gazy palne, d) materiały zapalające się samorzutnie na powietrzu, e) materiały wybuchowe i wyroby pirotechniczne, f) materiały ulegające samorzutnemu rozkładowi lub polimeryzacji, g) materiały mające skłonności do samozapalenia, h) materiały inne niż wymienione w lit. a‒g, jeśli sposób ich składowania, przetwarzania lub innego wykorzystania może spowodować powstanie pożaru; 2) pasie przeciwpożarowym ‒ należy przez to rozumieć system drzewostanów różnej szerokości poddanych specjalnym zabiegom gospodarczym i porządkowym lub powierzchni wylesionych i oczyszczonych do warstwy mineralnej; […]"}], "58": [{"ref": "§ 28 RPB – obiekty wymagające systemu sygnalizacji pożarowej", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. […] 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; 8) domach pomocy społecznej i ośrodkach rehabilitacji dla osób niepełnosprawnych o liczbie łóżek powyżej 100 w budynku; 9) zakładach pracy zatrudniających powyżej 100 osób niepełnosprawnych w budynku; 10) budynkach użyteczności publicznej wysokich i wysokościowych; 11) budynkach zamieszkania zbiorowego, w których przewidywany okres pobytu tych samych osób przekracza trzy doby, o liczbie miejsc noclegowych powyżej 200; 12) budynkach zamieszkania zbiorowego niewymienionych w pkt 11, o liczbie miejsc noclegowych powyżej 50; 13) archiwach wyznaczonych przez Naczelnego Dyrektora Archiwów Państwowych; 14) muzeach oraz zabytkach budowlanych, wyznaczonych przez Generalnego Konserwatora Zabytków w uzgodnieniu z Komendantem Głównym Państwowej Straży Pożarnej; […]"}], "60": [{"ref": "§ 209, § 212 WT – klasa odporności pożarowej", "kind": "akt", "act": "wt", "label": "§ 209", "text": "§ 209. 1. Budynki oraz części budynków, stanowiące odrębne strefy pożarowe w rozumieniu § 226, z uwagi na przeznaczenie i sposób użytkowania, dzieli się na: 1) mieszkalne, zamieszkania zbiorowego i użyteczności publicznej charakteryzowane kategorią zagrożenia ludzi, określane dalej jako ZL; 2) produkcyjne i magazynowe, określane dalej jako PM; 3) inwentarskie (służące do hodowli inwentarza), określane dalej jako IN. 2. Budynki oraz części budynków, stanowiące odrębne strefy pożarowe, określane jako ZL, zalicza się do jednej lub do więcej niż jedna spośród następujących kategorii zagrożenia ludzi: 1) ZL I – zawierające pomieszczenia przeznaczone do jednoczesnego przebywania ponad 50 osób niebędących ich stałymi użytkownikami, a nieprzeznaczone przede wszystkim do użytku ludzi o ograniczonej zdolności poruszania się; […]"}], "61": [{"ref": "§ 234 WT – przepusty instalacyjne w elementach oddzielających", "kind": "akt", "act": "wt", "label": "§ 234", "text": "§ 234. 1. Przepusty instalacyjne w elementach oddzielenia przeciwpożarowego powinny mieć klasę odporności ogniowej (E I) wymaganą dla tych elementów. 2. Dopuszcza się nieinstalowanie przepustów, o których mowa w ust. 1, dla pojedynczych rur instalacji wodnych, kanalizacyjnych i ogrzewczych, wprowadzanych przez ściany i stropy do pomieszczeń higienicznosanitarnych. 3. Przepusty instalacyjne o średnicy większej niż 0,04 m w ścianach i stropach pomieszczenia zamkniętego, dla których wymagana klasa odporności ogniowej jest nie niższa niż E I 60 lub R E I 60, a niebędących elementami oddzielenia przeciwpożarowego, powinny mieć klasę odporności ogniowej (E I) ścian i stropów tego pomieszczenia. 4. Przejścia instalacji przez zewnętrzne ściany budynku, znajdujące się poniżej poziomu terenu, powinny być zabezpieczone przed możliwością przenikania gazu do wnętrza budynku."}], "62": [{"ref": "przepisy techniczno-budowlane dla tuneli / § 28 RPB", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}], "64": [{"ref": "§ 234, § 256 WT – zamknięcia otworów w oddzieleniach ppoż.", "kind": "akt", "act": "wt", "label": "§ 234", "text": "§ 234. 1. Przepusty instalacyjne w elementach oddzielenia przeciwpożarowego powinny mieć klasę odporności ogniowej (E I) wymaganą dla tych elementów. 2. Dopuszcza się nieinstalowanie przepustów, o których mowa w ust. 1, dla pojedynczych rur instalacji wodnych, kanalizacyjnych i ogrzewczych, wprowadzanych przez ściany i stropy do pomieszczeń higienicznosanitarnych. 3. Przepusty instalacyjne o średnicy większej niż 0,04 m w ścianach i stropach pomieszczenia zamkniętego, dla których wymagana klasa odporności ogniowej jest nie niższa niż E I 60 lub R E I 60, a niebędących elementami oddzielenia przeciwpożarowego, powinny mieć klasę odporności ogniowej (E I) ścian i stropów tego pomieszczenia. 4. Przejścia instalacji przez zewnętrzne ściany budynku, znajdujące się poniżej poziomu terenu, powinny być zabezpieczone przed możliwością przenikania gazu do wnętrza budynku."}], "65": [{"ref": "§ 39 RPB – lekki dach w pomieszczeniu zagrożonym wybuchem", "kind": "akt", "act": "rpb", "label": "§ 39", "text": "§ 39. […] 5) studnia z pompą oraz z: a) hydrantem zewnętrznym lub b) innym punktem poboru wody z nasadą tłoczną typu 75 lub 110 – o wydajności nie mniejszej niż 10 dm3/s. 5.7) Zbiornikiem sztucznym jest pojemnik albo grupa pojemników połączonych przewodami o średnicy co najmniej 300 mm w sposób umożliwiający dostęp do wymaganego zapasu wody z każdego stanowiska czerpania wody, w które jest wyposażony zbiornik. 6.7) Źródła wody do celów przeciwpożarowych, o których mowa w ust. 4 pkt 1‒3 i 5, powinny być wyposażone w stanowiska czerpania wody z utwardzoną nawierzchnią o nośności nie mniejszej niż wymagana dla dojazdów pożarowych. 7.8) Stanowiska czerpania wody przy źródłach wody do celów przeciwpożarowych, o których mowa w ust. 4 pkt 1‒3, powinny umożliwiać pobieranie wody z głębokości nie większej niż 4 m, mierząc od lustra wody do poziomu stanowiska czerpania wody, z wykorzystaniem autopomp lub motopomp pożarniczych. 8.8) Stanowisko czerpania wody powinno mieć szerokość co najmniej 4 m i długość co najmniej 12 m oraz być wykonane w sposób umożliwiający wjazd i wyjazd, a także postój samochodu ratowniczo-gaśniczego o długości 12 m. […]"}], "66": [{"ref": "§ 12 RW; art. 6a ustawy o ochronie ppoż. – rozwiązania zamienne", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. 1. Drogę pożarową o utwardzonej nawierzchni, umożliwiającą dojazd pojazdów jednostek ochrony przeciwpożarowej do obiektu budowlanego o każdej porze roku, należy doprowadzić do: 1) budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL I lub ZL II; 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; […]"}], "67": [{"ref": "§ 212 WT – klasa odporności pożarowej budynków ZL", "kind": "akt", "act": "wt", "label": "§ 212", "text": "§ 212. 1. Ustanawia się pięć klas odporności pożarowej budynków lub ich części, podanych w kolejności od najwyższej do najniższej i oznaczonych literami: „A”, „B”, „C”, „D” i „E”, a scharakteryzowanych w § 216. 2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A” 3. Dopuszcza się obniżenie wymaganej klasy odporności pożarowej w budynkach wymienionych w poniższej tabeli do poziomu w niej określonego. Liczba kondygnacji nadziemnych ZL I ZL II ZL III 1 2 3 4 1 „D” „D” „D” 2*) „C” „C” „D” *) Gdy poziom stropu nad pierwszą kondygnacją nadziemną jest na wysokości nie większej niż 9 m nad poziomem terenu. 4. […]"}], "68": [{"ref": "art. 36a ustawy – Prawo budowlane", "kind": "akt", "act": "pb", "label": "art. 36a", "text": "Art. 36a. […] Projektant dokonuje kwalifikacji zamierzonego odstąpienia od projektu zagospodarowania działki lub terenu lub projektu architektoniczno-budowlanego lub innych warunków decyzji o pozwoleniu na budowę, a w przypadku uznania, że jest ono nieistotne, dołącza do dokumentacji budowy odpowiednie informacje (rysunek i opis) dotyczące tego odstąpienia. Nieistotne odstąpienie od zatwierdzonego projektu zagospodarowania działki lub terenu lub projektu architektoniczno-budowlanego, lub innych warunków decyzji o pozwoleniu na budowę nie wymaga uzyskania decyzji o zmianie pozwolenia na budowę oraz ponownego zgłoszenia."}], "69": [{"ref": "dyrektywa ATEX / PN-EN 60079-10-1 – dobór urządzeń do stref", "kind": "norma"}], "70": [{"ref": "PN-EN 15650 / PN-EN 13501-3 – klasyfikacja klap ppoż.", "kind": "norma"}], "71": [{"ref": "PN-EN 12845 / NFPA – tryskacze ESFR", "kind": "norma"}], "72": [{"ref": "§ 157 WT – zakaz stosowania gazu płynnego w budynkach wysokich i wysokościowych", "kind": "akt", "act": "wt", "label": "§ 157", "text": "§ 157. […] 3. Instalacja gazowa w budynku o wysokości większej niż 35 m ponad poziomem terenu może być doprowadzona tylko do pomieszczeń technicznych, w których są zainstalowane urządzenia gazowe, usytuowanych w piwnicy lub na najniższej kondygnacji nadziemnej, a także na najwyższej kondygnacji budynku lub nad tą kondygnacją, pod warunkiem zastosowania urządzeń stabilizujących ciśnienie gazu. 4. Zastosowanie instalacji gazowej w budynkach o wysokości ponad 25 m wymaga uzyskania pozytywnej opinii wydanej przez właściwego komendanta wojewódzkiego Państwowej Straży Pożarnej. 5. Instalacje gazowe zasilane gazem płynnym mogą być wykonywane tylko w budynkach niskich. 6. Zabrania się stosowania w jednym budynku gazu płynnego i gazu z sieci gazowej. 7. W budynku niskim, mającym w mieszkaniach instalację zasilaną gazem płynnym, dopuszcza się usytuowanie kotłowni gazowej zasilanej z sieci gazowej. 8. […]"}], "73": [{"ref": "§ 285 WT – część mieszkalna i gospodarcza w jednym budynku", "kind": "akt", "act": "wt", "label": "§ 285", "text": "§ 285. Dopuszcza się umieszczenie w jednym budynku części mieszkalnej i gospodarczej pod następującymi warunkami: 1) część mieszkalna oraz część gospodarcza mają odrębne wejścia; 2) między częścią mieszkalną a gospodarczą zostanie wykonana ściana o klasie odporności ogniowej co najmniej R E I 60. Rozdział 10 Wymagania przeciwpożarowe dla budynków tymczasowych"}], "74": [{"ref": "PN-B-02852 – obliczanie gęstości obciążenia ogniowego", "kind": "norma"}], "75": [{"ref": "PN-EN 12101-6:2007 – systemy różnicowania ciśnień, klasa B", "kind": "norma"}], "76": [{"ref": "PN-EN 60849:2001 – dźwiękowe systemy ostrzegawcze", "kind": "norma"}], "77": [{"ref": "PN-B-02877-4:2001 – grawitacyjne odprowadzanie dymu i ciepła", "kind": "norma"}], "78": [{"ref": "§ 227 WT – dopuszczalne powierzchnie stref pożarowych ZL", "kind": "akt", "act": "wt", "label": "§ 227", "text": "§ 227. 1. Dopuszczalne powierzchnie stref pożarowych ZL określa poniższa tabela: Kategoria zagrożenia ludzi Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim (N) średniowysokim (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 ZL I, ZL III, ZL IV, ZL V 10 000 8000 5000 2500 ZL II 8000 5000 3500 2000 2. Dopuszczalna powierzchnia strefy pożarowej ZL, obejmującej podziemną część budynku, nie powinna przekraczać 50% dopuszczalnej powierzchni strefy pożarowej tej samej kategorii zagrożenia ludzi, określonej w ust. 1 dla pierwszej nadziemnej kondygnacji tego budynku. 3. Zmniejszenie dopuszczalnej powierzchni strefy pożarowej, o której mowa w ust. 2, nie dotyczy przypadku, gdy wyjścia ewakuacyjne z kondygnacji podziemnej prowadzą bezpośrednio na zewnątrz budynku. 4. […]"}], "79": [{"ref": "§ 5 RW – wymagana ilość wody", "kind": "akt", "act": "rw", "label": "§ 5", "text": "§ 5. 1. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla budynków użyteczności publicznej i zamieszkania zbiorowego oraz innych obiektów budowlanych o takim przeznaczeniu, służąca do zewnętrznego gaszenia pożaru, wynosi: 1) dla budynku o kubaturze brutto do 5 000 m3 i o powierzchni wewnętrznej do 1 000 m2 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 2) dla budynków niewymienionych w pkt 1 — 20 dm3/s łącznie z co najmniej dwóch hydrantów o średnicy 80 mm lub 200 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 3) dla obiektów wymienionych w § 3 ust. 1 pkt 3 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym. 2. […]"}], "81": [{"ref": "§ 13 RW – prześwit nad drogą pożarową", "kind": "akt", "act": "rw", "label": "§ 13", "text": "§ 13. […] 2) na odcinku o długości 15 m od miejsc doprowadzenia jej do budynku, o których mowa w § 12 ust. 6 pkt 2. 2. W obrębie miasta oraz na terenie działki, na której jest usytuowany obiekt budowlany, o którym mowa w § 12 ust. 1 pkt 3 i 4, droga pożarowa powinna umożliwiać przejazd pojazdów o nacisku osi na nawierzchnię jezdni co najmniej 100 kN (kiloniutonów), a jej minimalna szerokość w miejscach innych niż wymienione w ust. 1 nie może być mniejsza niż 3,5 m. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9069 — Poz. 1030 3. Na terenach innych niż wymienione w ust. 2 droga pożarowa powinna umożliwiać przejazd pojazdów o nacisku osi na nawierzchnię jezdni co najmniej 50 kN, a jej minimalna szerokość w miejscach innych niż wymienione w ust. 1 nie może być mniejsza niż 3 m. 4. […]"}], "82": [{"ref": "§ 158 WT – urządzenia sygnalizacyjno-odcinające dopływ gazu", "kind": "akt", "act": "wt", "label": "§ 158", "text": "§ 158. […] 4. Zabrania się instalowania urządzeń sygnalizacyjno-odcinających dopływ gazu do części mieszkalnej budynku wielorodzinnego. Nie dotyczy to indywidualnych urządzeń sygnalizacyjno-odcinających dopływ gazu do odrębnych mieszkań. 5. Urządzenia sygnalizacyjno-odcinające dopływ gazu należy stosować w tych pomieszczeniach, w których łączna nominalna moc cieplna zainstalowanych urządzeń gazowych jest większa niż 60 kW. 6. Zawór odcinający dopływ gazu do budynku, będący elementem składowym urządzenia sygnalizacyjno-odcinającego, powinien być instalowany poza budynkiem, między kurkiem głównym a wprowadzeniem przewodu do budynku. 7. Instalacja gazowa przyłączona do sieci gazowej wykonanej z przewodów metalowych powinna być zabezpieczona przed wpływem prądów błądzących przez zainstalowanie wstawki izolacyjnej na wprowadzeniu metalowej rury gazowej do budynku."}], "83": [{"ref": "§ 261 WT – przestrzeń podpodłogowa podłóg podniesionych", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. Pomieszczenia przeznaczone do jednoczesnego przebywania ponad 200 osób dorosłych lub 100 dzieci, w których miejsca do siedzenia są ustawione w rzędach, powinny mieć: 1) fotele i inne siedzenia trudno zapalne oraz niewydzielające produktów rozkładu i spalania, określonych jako bardzo toksyczne, zgodnie z Polską Normą dotyczącą badań wydzielania produktów toksycznych; określenie trudno zapalny przypisuje się fotelom i innym siedzeniom, które nie ulegają postępującemu tleniu i spalaniu płomieniowemu w warunkach określonych Polską Normą dotyczącą badania zapalności mebli tapicerowanych; 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; […]"}], "84": [{"ref": "PN-EN 13501-1 – klasyfikacja reakcji na ogień posadzek (indeks fl)", "kind": "norma"}], "85": [{"ref": "§ 111 WT / RPB – przechowywanie materiałów niebezpiecznych w garażach", "kind": "akt", "act": "wt", "label": "§ 111", "text": "§ 111. (uchylony)."}], "87": [{"ref": "§ 216 WT / PN-EN 13501-5 – klasyfikacja przekryć dachów", "kind": "norma"}], "88": [{"ref": "§ 6–7 RW – ilość wody dla obiektów innych niż budynki", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. […] U. Nr 243, poz. 2063 oraz z 2007 r. Nr 240, poz. 1753). 7. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla urządzeń technologicznych oraz składów i magazynów z gazami palnymi i cieczami o temperaturze zapłonu do 373,15 K (100 °C), zlokalizowanych poza budynkami, określa tabela nr 4 załącznika do rozporządzenia. 8. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla silosów, komór i zasobników ze stałymi sypkimi materiałami palnymi oraz dla zbiorników z cieczami palnymi o temperaturze zapłonu powyżej 373,15 K (100 °C) wynosi 10 dm3/s. 9. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla obiektów budowlanych gospodarki rolnej należy zapewnić w następujących ilościach: 1) dla obiektów o powierzchni strefy pożarowej do 2 000 m2 — co najmniej 10 dm3/s; […]"}], "89": [{"ref": "§ 28, § 29 RPB – obowiązek SSP i DSO", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}], "90": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego i powiększenia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. […] 4. Jeżeli z przewidywanego przeznaczenia pomieszczenia nie wynika jednoznacznie sposób jego zagospodarowania, projektowa długość przejścia ewakuacyjnego nie może być większa niż 80% długości określonej w ust. 1 i 2. 5. W pomieszczeniach o wysokości przekraczającej 5 m długość przejść, o których mowa w ust. 1 i 2, może być powiększona o 25%. 6. Długości przejść, o których mowa w ust. 1 i 2, mogą być powiększone pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 50%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 50%. 7. Powiększenia, o których mowa w ust. 5 i 6 pkt 1 i 2, podlegają sumowaniu. 8. Przejście, o którym mowa w ust. 1, nie powinno prowadzić łącznie przez więcej niż trzy pomieszczenia. 9. […]"}], "91": [{"ref": "§ 8, § 212 WT – definicja budynku niskiego i klasa odporności pożarowej", "kind": "akt", "act": "wt", "label": "§ 8", "text": "§ 8. W celu określenia wymagań technicznych i użytkowych wprowadza się następujący podział budynków na grupy wysokości: 1) niskie (N) – do 12 m włącznie nad poziomem terenu lub mieszkalne o wysokości do 4 kondygnacji nadziemnych włącznie; 2) średniowysokie (SW) – ponad 12 m do 25 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 4 do 9 kondygnacji nadziemnych włącznie; 3) wysokie (W) – ponad 25 m do 55 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 9 do 18 kondygnacji nadziemnych włącznie; 4) wysokościowe (WW) – powyżej 55 m nad poziomem terenu."}], "92": [{"ref": "§ 212, § 216 WT – klasa B, wymagane klasy odporności ogniowej elementów", "kind": "akt", "act": "wt", "label": "§ 212", "text": "§ 212. […] 5. Jeżeli część podziemna budynku jest zaliczona do ZL, klasę odporności pożarowej budynku ustala się, przyjmując jako liczbę jego kondygnacji lub jego wysokość odpowiednio: sumę kondygnacji lub wysokości części podziemnej i nadziemnej, przy czym do tego ustalenia nie bierze się pod uwagę tych części podziemnych budynku, które są oddzielone elementami oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej R E I 120, zgodnie z oznaczeniem pod tabelą w § 216 ust. 1, i mają bezpośrednie wyjścia na zewnątrz. 6. W budynku wielokondygnacyjnym, którego kondygnacje są zaliczone do różnych kategorii ZL lub PM, klasy odporności pożarowej określa się dla poszczególnych kondygnacji odrębnie, zgodnie z zasadami określonymi w ust. 2–4. 7. […]"}], "93": [{"ref": "§ 271, § 272 WT – odległości między budynkami i od granicy działki", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. […] Najmniejsza odległość budynków wymienionych w § 213, wykonanych z elementów nierozprzestrzeniających ognia, niezawierających pomieszczeń zagrożonych wybuchem oraz posiadających klasę odporności pożarowej wyższą niż wymagana zgodnie z § 212, od granicy (konturu) lasu zlokalizowanej na: 1) sąsiedniej działce – wynosi 4 m, 2) działce, na której sytuuje się budynek – nie określa się – jeżeli teren, na którym znajduje się granica (kontur) lasu, przeznaczony jest w miejscowym planie zagospodarowania przestrzennego pod zabudowę niezwiązaną z produkcją leśną, a w przypadku braku planu miejscowego – grunty leśne są objęte zgodą na zmianę przeznaczenia na cele nieleśne uzyskaną przy sporządzaniu miejscowych planów zagospodarowania przestrzennego, które utraciły moc na podstawie art. 1 lit. a ustawy z dnia 21 grudnia 2001 r. o zmianie ustawy o zagospodarowaniu przestrzennym (Dz. U. poz. […]"}], "94": [{"ref": "§ 261 WT – liczba siedzeń w rzędzie i odstępy między rzędami", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. […] 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; 3) liczbę siedzeń w rzędzie nie większą niż 16 pomiędzy przejściami oraz 8 w rzędzie przyściennym, przy czym dopuszcza się zwiększenie liczby miejsc w rzędach odpowiednio do 40 i 20 pod warunkiem zwiększenia odstępu między rzędami siedzeń o 1 cm na każde dodatkowe siedzenie odpowiednio powyżej 16 lub 8; 4) szerokość przejść komunikacyjnych nie mniejszą niż 1,2 m przy liczbie osób do 150, a przy większej ich liczbie szerokość tę należy zwiększyć proporcjonalnie o 0,6 m na 100 osób; 5) rzędy siedzeń lub ławek trwale umocowane do podłogi albo siedzenia sztywno łączone ze sobą w rzędy oraz między rzędami."}], "95": [{"ref": "§ 216 ust. 8 WT – palna izolacja cieplna w ścianach", "kind": "akt", "act": "wt", "label": "§ 216", "text": "8. W budynku, na wysokości powyżej 25 m od poziomu terenu, okładzina elewacyjna i jej zamocowanie mechaniczne, a także izolacja cieplna ściany zewnętrznej, powinny być wykonane z materiałów niepalnych."}], "96": [{"ref": "§ 37 RPB / WT – wentylacja pomieszczeń zagrożonych wybuchem", "kind": "akt", "act": "wt", "label": "§ 37", "text": "§ 37. Przepływowe, szczelne osadniki podziemne, stanowiące część przydomowej oczyszczalni ścieków gospodarczo-bytowych, służące do wstępnego ich oczyszczania, mogą być sytuowane w bezpośrednim sąsiedztwie budynków jednorodzinnych, pod warunkiem wyprowadzenia ich odpowietrzenia przez instalację kanalizacyjną co najmniej 0,6 m powyżej górnej krawędzi okien i drzwi zewnętrznych w tych budynkach."}], "97": [{"ref": "§ 179 WT / rozp. dot. zbiorników gazu płynnego – odległości", "kind": "akt", "act": "wt", "label": "§ 179", "text": "§ 179. […] 2) powyżej 10 m3 – nie mniej niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3. 6. Odległość zbiorników z gazem płynnym od granicy działki budowlanej z tymi zbiornikami powinna być nie mniejsza niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3, przy zachowaniu wymaganej odległości od budynku danego rodzaju. 7. Odległości określone w tabeli w ust. 4 w kolumnie 2 mogą być zmniejszone do 50% w przypadku zastosowania wolno stojącej ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej R E I 120, usytuowanej pomiędzy zbiornikiem z gazem płynnym a budynkiem. Wymiary wolno stojącej ściany oraz jej odległość od zbiornika powinny być tak dobrane, aby osłonić zbiornik od tej części budynku, która znajduje się w odległości mniejszej niż określona w tabeli w ust. 4 w kolumnie 2 od dowolnego punktu zbiornika. 8. […]"}], "98": [{"ref": "§ 270 WT – usuwanie dymu z dróg ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 270", "text": "§ 270. 1. Instalacja wentylacji oddymiającej powinna: 1) usuwać dym z intensywnością zapewniającą, że w czasie potrzebnym do ewakuacji ludzi na chronionych przejściach i drogach ewakuacyjnych nie wystąpi zadymienie lub temperatura uniemożliwiające bezpieczną ewakuację; 2) mieć stały dopływ powietrza zewnętrznego uzupełniającego braki tego powietrza w wyniku jego wypływu wraz z dymem. 2. Przewody wentylacji oddymiającej, obsługujące: 1) wyłącznie jedną strefę pożarową, powinny mieć klasę odporności ogniowej z uwagi na szczelność ogniową i dymoszczelność – E600 S, co najmniej taką jak klasa odporności ogniowej stropu określona w § 216, przy czym dopuszcza się stosowanie klasy E300 S, jeżeli wynikająca z obliczeń temperatura dymu powstającego w czasie pożaru nie przekracza 300°C; […]"}], "99": [{"ref": "§ 24 ust. 2 i 3 RPB – zapas wody dla instalacji wodociągowej ppoż.", "kind": "akt", "act": "rpb", "label": "§ 24", "text": "2. Do zasilania w wodę instalacji wodociągowej przeciwpożarowej w budynkach wysokich i wysokościowych powinien być zapewniony zapas wody zgromadzony o łącznej pojemności nie mniejszej niż 100 m3 w jednym lub kilku zbiornikach przeznaczony wyłącznie do tego celu."}], "100": [{"ref": "PN-EN 13200-1:2013 – ewakuacja z widowni", "kind": "norma"}], "102": [{"ref": "§ 230 WT – warunki obniżenia klasy odporności pożarowej", "kind": "akt", "act": "wt", "label": "§ 230", "text": "§ 230. 1. W budynku jednokondygnacyjnym lub na ostatniej kondygnacji budynku wielokondygnacyjnego wielkości stref pożarowych PM, z wyjątkiem garaży, można powiększyć o 100%, jeżeli budynek nie zawiera pomieszczenia zagrożonego wybuchem i jest wykonany z elementów nierozprzestrzeniających ognia oraz zastosowano samoczynne urządzenia oddymiające. 2. W budynku jednokondygnacyjnym wielkości stref pożarowych PM, z wyjątkiem garażu, nie ogranicza się, pod warunkiem zastosowania stałych samoczynnych urządzeń gaśniczych wodnych i samoczynnych urządzeń oddymiających."}], "104": [{"ref": "§ 28 RPB – obiekty wymagające SSP", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}], "105": [{"ref": "§ 193, § 207 WT – dźwigi dla ekip ratowniczych", "kind": "akt", "act": "wt", "label": "§ 193", "text": "§ 193. […] Kabina dźwigu osobowego dostępna dla osób niepełnosprawnych powinna mieć szerokość co najmniej 1,1 m i długość 1,4 m, poręcze na wysokości 0,9 m oraz tablicę przyzywową na wysokości od 0,8 m do 1,2 m w odległości nie mniejszej niż 0,5 m od naroża kabiny z dodatkowym oznakowaniem dla osób niewidomych i informacją głosową. 3. W zabudowie śródmiejskiej w średniowysokim budynku mieszkalnym wielorodzinnym, mającym nie więcej niż 3 mieszkania dostępne z klatki schodowej na kondygnacji, dopuszcza się instalowanie dźwigu niespełniającego wymagań określonych w ust. 2, poza przystosowaniem go do potrzeb osób niepełnosprawnych. 4. Dźwigi przeznaczone dla ekip ratowniczych powinny spełniać wymagania określone w § 253 oraz w przepisach odrębnych dotyczących ochrony przeciwpożarowej."}], "106": [{"ref": "PN-EN 60849 / PKN-CEN/TS 54-14 – poziomy dźwięku", "kind": "norma"}], "107": [{"ref": "PN-EN 12845 – zbiornik pośredni z uzupełnianiem", "kind": "norma"}], "108": [{"ref": "PKN-CEN/TS 54-14:2006 – strefy dozorowe", "kind": "norma"}], "109": [{"ref": "PN-EN 1838 – oświetlenie awaryjne dróg ewakuacyjnych", "kind": "norma"}], "110": [{"ref": "§ 228 ust. 1 WT – tabela powierzchni stref PM", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}, {"ref": "§ 229 ust. 1 i 2 WT – powiększenie o 150%", "kind": "akt", "act": "wt", "label": "§ 229", "text": "§ 229. 1. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w § 228, pod warunkiem ich ochrony: 1) stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 100%; 2) samoczynnymi urządzeniami oddymiającymi – o 50%."}], "111": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego i powiększenia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "112": [{"ref": "§ 8–9 RW – uzupełniający zapas wody w zbiorniku", "kind": "akt", "act": "rw", "label": "§ 8", "text": "§ 8. […] 3. W szczególnie uzasadnionych przypadkach, gdy spełnienie wymagań dotyczących przeciwpożarowego zaopatrzenia w wodę jest niemożliwe ze względu na lokalne uwarunkowania lub jest uzasadnione przyjęcie www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9066 — Poz. 1030 innych rozwiązań, na wniosek właściciela budynku, obiektu budowlanego lub terenu, dopuszcza się stosowanie rozwiązań zamiennych, które zapewniają niepogorszenie warunków ochrony przeciwpożarowej, uzgodnionych z właściwym miejscowo komendantem wojewódzkim Państwowej Straży Pożarnej. 4. Wymagania dotyczące projektowania i budowy sieci wodociągowych, przeciwpożarowych zbiorników wodnych wraz ze stanowiskami czerpania wody oraz dojazdami do nich określają odpowiednie Polskie Normy. Rozdział 4 Wymagania przeciwpożarowe dla sieci wodociągowych"}], "114": [{"ref": "art. 6a ustawy o ochronie ppoż. – rozwiązania zamienne", "kind": "akt", "act": "uop", "label": "art. 6a", "text": "Art. 6a. […] 2) zapewniają ograniczenie rozprzestrzeniania się ognia i dymu wewnątrz obiektu budowlanego; 3) zapewniają ograniczenie rozprzestrzeniania się pożaru na sąsiednie obiekty budowlane lub tereny przyległe; 4) zapewniają możliwość ewakuacji ludzi lub ich uratowania w inny sposób; 5) uwzględniają bezpieczeństwo ekip ratowniczych. 2. Komendant wojewódzki Państwowej Straży Pożarnej właściwy dla miejsca lokalizacji inwestycji na uzasadniony ekspertyzą techniczną wniosek inwestora lub właściciela obiektu budowlanego lub terenu, którego dotyczą rozwiązania zamienne w stosunku do wymagań ochrony przeciwpożarowej, może, w drodze postanowienia, na które służy zażalenie: 1) wyrazić zgodę na zastosowanie rozwiązań zamiennych; 2) wyrazić zgodę na zastosowanie rozwiązań zamiennych pod warunkiem spełnienia dodatkowych wymagań określonych w postanowieniu; […]"}], "115": [{"ref": "§ 4 rozp. w sprawie uzgadniania projektu pod względem ochrony ppoż.", "kind": "akt", "act": "uzgadnianie", "label": "§ 4", "text": "§ 4. […] 2) w przypadku projektu architektoniczno-budowlanego, w szczególności: a) informacje o powierzchni wewnętrznej, wysokości i liczbie kondygnacji, b) charakterystykę zagrożenia pożarowego, w tym informacje o parametrach pożarowych materiałów niebezpiecznych pożarowo oraz zagrożeniach wynikających z procesów technologicznych, a także w zależności od potrzeb – charakterystykę pożarów przyjętych do celów projektowych, c) informacje o klasyfikacji pożarowej z uwagi na przeznaczenie i sposób użytkowania, d) informacje o kategorii zagrożenia ludzi oraz przewidywanej liczbie osób na każdej kondygnacji, a także w pomieszczeniach, których drzwi ewakuacyjne powinny otwierać się na zewnątrz pomieszczeń, e) informacje o podziale na strefy pożarowe, f) maksymalną gęstość obciążenia ogniowego poszczególnych stref pożarowych PM wraz z warunkami przyjętymi do jej określenia, g) informacje o klasie odporności pożarowej oraz odporności ogniowej i stopniu rozprzestrzeniania ognia przez elementy budowlane, h) informacje o występowaniu materiałów wybuchowych oraz zagrożenia wybuchem, w tym pomieszczeń zagrożonych wybuchem, i) informacje o warunkach i strategii ewakuacji ludzi lub ich uratowania w inny sposób, uwzględniające liczbę i stan sprawności osób przebywających w obiekcie, j) informacje o doborze urządzeń przeciwpożarowych oraz innych instalacji i urządzeń służących bezpieczeństwu pożarowemu wraz z określeniem zakresu i celu ich stosowania, ﻿ k) informacje o przygotowaniu obiektu budowlanego do prowadzenia działań ratowniczych, w tym informacje o punktach poboru wody do celów przeciwpożarowych, nasadach służących do zasilania urządzeń gaśniczych i innych rozwiązaniach przewidzianych do tych działań oraz dźwigach dla ekip ratowniczych i prowadzących do nich dojściach, l) informacje o usytuowaniu z uwagi na bezpieczeństwo pożarowe, w tym informacje o parametrach wpływających na odległości dopuszczalne, m) informacje o rozwiązaniach zamiennych w stosunku do wymagań ochrony przeciwpożarowej zastosowanych na podstawie zgody, o której mowa w art. 6c pkt 1 lub 2 ustawy z dnia 24 sierpnia 1991 r. o ochronie przeciwpożarowej, w zakresie rozwiązań objętych projektem architektoniczno-budowlanym; […]"}], "117": [{"ref": "§ 2 RPB – definicja scenariusza pożarowego", "kind": "norma"}], "119": [{"ref": "PN-EN 12845 / NFPA – tryskacze ESFR", "kind": "norma"}], "120": [{"ref": "§ 19 RPB – hydranty wewnętrzne w garażach", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. […] 4) Dodany przez § 1 rozporządzenia Ministra Spraw Wewnętrznych i Administracji z dnia 11 stycznia 2019 r. zmieniającego rozporządzenie w sprawie ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów (Dz. U. poz. 67), które weszło w życie z dniem 29 stycznia 2019 r. 2. Hydranty 33 muszą być stosowane w garażu: 1) jednokondygnacyjnym zamkniętym o więcej niż 10 stanowiskach postojowych; 2) wielokondygnacyjnym. 3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; […]"}], "121": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "122": [{"ref": "§ 164 WT – instalacje gazowe zasilające kotłownie", "kind": "akt", "act": "wt", "label": "§ 164", "text": "§ 164. 1. Przewodów instalacji gazowych nie należy prowadzić przez pomieszczenia mieszkalne oraz pomieszczenia, których sposób użytkowania może spowodować naruszenie stanu technicznego instalacji lub wpływać na parametry eksploatacyjne gazu. 2. Zabrania się prowadzenia przez pomieszczenia mieszkalne przewodów instalacji gazowej z zastosowaniem połączeń gwintowanych, a także z zastosowaniem innych sposobów łączenia rur, jeżeli mogą one stanowić zagrożenie dla bezpieczeństwa mieszkańców. 3. Przewody instalacji gazowej, w stosunku do przewodów innych instalacji stanowiących wyposażenie budynku (ogrzewczej wodociągowej, kanalizacyjnej, elektrycznej, piorunochronnej itp.), należy lokalizować w sposób zapewniający bezpieczeństwo ich użytkowania. Odległość między przewodami instalacji gazowej a innymi przewodami powinna umożliwiać wykonywanie prac konserwacyjnych. 4. […]"}], "123": [{"ref": "dyrektywa ATEX 2014/34/UE – kategorie urządzeń", "kind": "ue"}], "124": [{"ref": "PKN-CEN/TS 54-14:2006", "kind": "norma"}], "125": [{"ref": "§ 19–20 RPB – instalacja wodociągowa przeciwpożarowa", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. […] 3) przy wejściu do pomieszczeń magazynowych lub technicznych o powierzchni przekraczającej 200 m2 i gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, usytuowanych w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II, ZL III lub ZL V, znajdującej się w budynku niskim albo średniowysokim. 4. W strefach pożarowych, o których mowa w ust. 3 pkt 1, i przy wejściu do pomieszczeń magazynowych lub technicznych, o których mowa w ust. 3 pkt 3, dopuszcza się stosowanie hydrantów 33, jeżeli gęstość obciążenia ogniowego w tych strefach i tych pomieszczeniach magazynowych lub technicznych nie przekracza 1000 MJ/m2. 5. Wymagania, o których mowa w ust. 2, nie dotyczą wolno stojących garaży na terenach zamkniętych podległych Ministrowi Obrony Narodowej. 6.5) Zawory 52 muszą być stosowane w budynkach wysokich i wysokościowych o więcej niż jednej kondygnacji nadziemnej."}], "127": [{"ref": "PN-EN 12845:2015-10 – urządzenia tryskaczowe", "kind": "norma"}], "129": [{"ref": "PKN-CEN/TS 54-14:2006 – rozmieszczenie czujek", "kind": "norma"}], "130": [{"ref": "PN-EN 13501-4 / PN-EN 1366-10 – klasyfikacja klap wentylacji oddymiającej", "kind": "norma"}], "133": [{"ref": "§ 10 RW – sieć wodociągowa i hydranty zewnętrzne", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 2. Dopuszcza się instalowanie hydrantów podziemnych o średnicy nominalnej DN 80 w przypadkach, gdy zainstalowanie hydrantów nadziemnych jest szczególnie utrudnione lub niewskazane, na przykład ze względu na utrudnienia w ruchu. 3. W obiekcie budowlanym produkcyjnym i magazynowym, w którym wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru przekracza 30 dm3/s, w zakładach rafineryjnych i petrochemicznych oraz na magistralnym przewodzie wodociągowym przeciwpożarowym należy instalować hydranty nadziemne o średnicy nominalnej DN 100. 4. Hydranty zewnętrzne zainstalowane na sieci wodociągowej przeciwpożarowej powinny być wyposażone w odcięcia umożliwiające odłączania ich od sieci. Odcięcia te muszą pozostawać w położeniu otwartym podczas normalnej eksploatacji sieci. 5. […]"}], "135": [{"ref": "§ 208a WT – materiały niepalne; PN-EN 13501-1", "kind": "norma"}], "136": [{"ref": "§ 216 WT – wymagane klasy odporności ogniowej elementów (klasa E)", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. […] 1. Oznaczenia w tabeli: R – nośność ogniowa (w minutach), określona zgodnie z Polską Normą dotyczącą zasad ustalania klas odporności ogniowej elementów budynku, E – szczelność ogniowa (w minutach), określona jw., I – izolacyjność ogniowa (w minutach), określona jw., (–) – nie stawia się wymagań. 1) Jeżeli przegroda jest częścią głównej konstrukcji nośnej, powinna spełniać także kryteria nośności ogniowej (R) odpowiednio do wymagań zawartych w kol. 2 i 3 dla danej klasy odporności pożarowej budynku. 2) Klasa odporności ogniowej dotyczy pasa międzykondygnacyjnego wraz z połączeniem ze stropem. […]"}], "137": [{"ref": "art. 10 ust. 1 ustawy o wyrobach budowlanych", "kind": "akt", "act": "wyroby", "label": "art. 10", "text": "1. Dopuszczone do jednostkowego zastosowania w obiekcie budowlanym są wyroby budowlane, z wyłączeniem wyrobów, o których mowa w art. 5 ust. 1, wykonane według indywidualnej dokumentacji technicznej, sporządzonej przez projektanta obiektu lub z nim uzgodnionej, dla których producent wydał oświadczenie, że zapewniono zgodność wyrobu budowlanego z tą dokumentacją oraz z przepisami."}], "138": [{"ref": "PN-EN 12101-1 – kurtyny dymowe, klasyfikacja", "kind": "norma"}], "139": [{"ref": "§ 20 RPB / RW – zasilanie rezerwowe pompowni przeciwpożarowych", "kind": "akt", "act": "rpb", "label": "§ 20", "text": "§ 20. 1. Hydranty wewnętrzne oraz zawory 52 powinny być umieszczane przy drogach komunikacji ogólnej, w szczególności: 1) przy wejściach do budynku i klatek schodowych na każdej kondygnacji budynku, przy czym w budynkach wysokich i wysokościowych zaleca się lokalizację zaworów 52 w przedsionkach przeciwpożarowych, a dopuszcza na klatkach schodowych; 2) w przejściach i na korytarzach, w tym w holach i na korytarzach poszczególnych kondygnacji budynków wysokich i wysokościowych; 3) przy wejściach na poddasza; 4) przy wyjściach na przestrzeń otwartą lub przy wyjściach ewakuacyjnych z pomieszczeń produkcyjnych i magazynowych, w szczególności zagrożonych wybuchem. 2. […]"}], "141": [{"ref": "§ 37 RPB – pomieszczenia uznane za zagrożone wybuchem", "kind": "akt", "act": "rpb", "label": "§ 37", "text": "§ 37. 1. W obiektach i na terenach przyległych, gdzie są prowadzone procesy technologiczne z użyciem materiałów mogących wytworzyć mieszaniny wybuchowe lub w których materiały takie są magazynowane, dokonuje się oceny zagrożenia wybuchem. 2. Ocena zagrożenia wybuchem obejmuje wskazanie pomieszczeń zagrożonych wybuchem, wyznaczenie w pomieszczeniach i przestrzeniach zewnętrznych odpowiednich stref zagrożenia wybuchem wraz z opracowaniem graficznej dokumentacji klasyfikacyjnej oraz wskazanie czynników mogących w nich zainicjować zapłon. 3. Graficzna dokumentacja klasyfikacyjna zawiera plany sytuacyjne obrazujące rodzaj i zasięg stref zagrożenia wybuchem oraz lokalizację i identyfikację źródeł emisji, zgodnie z zasadami określonymi w Polskich Normach. 4. Oceny zagrożenia wybuchem dokonują: inwestor, projektant lub użytkownik decydujący o procesie technologicznym. 5. […]"}], "143": [{"ref": "PN-EN 12845 – urządzenia tryskaczowe suche", "kind": "norma"}], "144": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "145": [{"ref": "§ 12 RW – wymóg drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 4) budynku zawierającego strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego poniżej 500 MJ/m2 o powierzchni przekraczającej 20 000 m2; 5) budynku niskiego: a) zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III o powierzchni przekraczającej 1 000 m2, obejmującą kondygnację nadziemną inną niż pierwsza, lub b) zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL V i mającego ponad 50 miejsc noclegowych; www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9068 — Poz. 1030 6) obiektu budowlanego innego niż budynek, przeznaczonego do użyteczności publicznej lub zamieszkania zbiorowego, w którym przewiduje się możliwość jednoczesnego przebywania w strefie pożarowej ponad 50 osób; 7) stanowiska czerpania wody do celów przeciwpożarowych. 2. […]"}], "146": [{"ref": "PKN-CEN/TS 54-14:2006 – rozmieszczenie czujek, wpływ belek", "kind": "norma"}], "147": [{"ref": "§ 227 ust. 4 pkt 2 WT – powiększenie strefy o 100%", "kind": "akt", "act": "wt", "label": "§ 227", "text": "4. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w ust. 1, z wyjątkiem stref pożarowych w wielokondygnacyjnych budynkach wysokich (W) i wysokościowych (WW), pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 100%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 100%. Przy jednoczesnym stosowaniu urządzeń wymienionych w pkt 1 i 2 dopuszcza się powiększenie powierzchni stref pożarowych o 200%."}, {"ref": "§ 237 ust. 6 pkt 2 WT – powiększenie przejścia o 50%", "kind": "akt", "act": "wt", "label": "§ 237", "text": "6. Długości przejść, o których mowa w ust. 1 i 2, mogą być powiększone pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 50%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 50%."}], "148": [{"ref": "§ 181 WT – awaryjne oświetlenie ewakuacyjne", "kind": "akt", "act": "wt", "label": "§ 181", "text": "§ 181. […] 3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego. 4. […]"}], "149": [{"ref": "§ 228 ust. 1 WT – tabela powierzchni stref PM", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}, {"ref": "§ 229 ust. 1 pkt 1 WT – powiększenie o 100%", "kind": "akt", "act": "wt", "label": "§ 229", "text": "§ 229. 1. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w § 228, pod warunkiem ich ochrony: 1) stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 100%; 2) samoczynnymi urządzeniami oddymiającymi – o 50%."}], "150": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego i powiększenia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "151": [{"ref": "§ 212 ust. 3 WT – klasa odporności pożarowej budynków PM/IN", "kind": "akt", "act": "wt", "label": "§ 212", "text": "3. Dopuszcza się obniżenie wymaganej klasy odporności pożarowej w budynkach wymienionych w poniższej tabeli do poziomu w niej określonego. Liczba kondygnacji nadziemnych ZL I ZL II ZL III 1 2 3 4 1 „D” „D” „D” 2*) „C” „C” „D” *) Gdy poziom stropu nad pierwszą kondygnacją nadziemną jest na wysokości nie większej niż 9 m nad poziomem terenu."}], "152": [{"ref": "PN-B-02852:2001 – obliczanie gęstości obciążenia ogniowego", "kind": "norma"}], "154": [{"ref": "§ 256 WT – długość dojść ewakuacyjnych (drugie dojście)", "kind": "akt", "act": "wt", "label": "§ 256", "text": "§ 256. […] 3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej. 4. […]"}], "155": [{"ref": "§ 258 WT – wymagania dla posadzek na drogach ewakuacyjnych i w pomieszczeniach", "kind": "akt", "act": "wt", "label": "§ 258", "text": "§ 258. 1. W strefach pożarowych ZL I, ZL II, ZL III i ZL V stosowanie do wykończenia wnętrz materiałów i wyrobów łatwo zapalnych, których produkty rozkładu termicznego są bardzo toksyczne lub intensywnie dymiące, jest zabronione. 1a. W przypadku stosowania materiałów wykończeniowych luźno zwisających, w szczególności w kurtynach, zasłonach, draperiach, kotarach oraz żaluzjach, za łatwo zapalne uważa się materiały, których właściwości określone w badaniach zgodnych z Polskimi Normami odnoszącymi się do zapalności i rozprzestrzeniania płomienia przez wyroby włókiennicze nie spełniają co najmniej jednego z kryteriów: 1) ti ≥ 4 s; 2) ts ≤ 30 s; 3) nie następuje przepalenie trzeciej nitki; 4) nie występują płonące krople. 2. Na drogach komunikacji ogólnej, służących celom ewakuacji, stosowanie materiałów i wyrobów budowlanych łatwo zapalnych jest zabronione."}], "156": [{"ref": "§ 8, § 212 WT – klasa odporności pożarowej", "kind": "akt", "act": "wt", "label": "§ 8", "text": "§ 8. W celu określenia wymagań technicznych i użytkowych wprowadza się następujący podział budynków na grupy wysokości: 1) niskie (N) – do 12 m włącznie nad poziomem terenu lub mieszkalne o wysokości do 4 kondygnacji nadziemnych włącznie; 2) średniowysokie (SW) – ponad 12 m do 25 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 4 do 9 kondygnacji nadziemnych włącznie; 3) wysokie (W) – ponad 25 m do 55 m włącznie nad poziomem terenu lub mieszkalne o wysokości ponad 9 do 18 kondygnacji nadziemnych włącznie; 4) wysokościowe (WW) – powyżej 55 m nad poziomem terenu."}], "158": [{"ref": "PN-EN 12845 – zbiornik pośredni", "kind": "norma"}], "159": [{"ref": "§ 8–9 RW – uzupełniający zapas wody", "kind": "akt", "act": "rw", "label": "§ 8", "text": "§ 8. […] 3. W szczególnie uzasadnionych przypadkach, gdy spełnienie wymagań dotyczących przeciwpożarowego zaopatrzenia w wodę jest niemożliwe ze względu na lokalne uwarunkowania lub jest uzasadnione przyjęcie www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9066 — Poz. 1030 innych rozwiązań, na wniosek właściciela budynku, obiektu budowlanego lub terenu, dopuszcza się stosowanie rozwiązań zamiennych, które zapewniają niepogorszenie warunków ochrony przeciwpożarowej, uzgodnionych z właściwym miejscowo komendantem wojewódzkim Państwowej Straży Pożarnej. 4. Wymagania dotyczące projektowania i budowy sieci wodociągowych, przeciwpożarowych zbiorników wodnych wraz ze stanowiskami czerpania wody oraz dojazdami do nich określają odpowiednie Polskie Normy. Rozdział 4 Wymagania przeciwpożarowe dla sieci wodociągowych"}], "160": [{"ref": "§ 2 RPB – definicja scenariusza pożarowego", "kind": "norma"}], "161": [{"ref": "§ 32 RPB – wyposażenie w gaśnice; rozp. MEN dot. lokalu przedszkola", "kind": "akt", "act": "rpb", "label": "§ 32", "text": "§ 32. […] 2) na każde 300 m2 powierzchni strefy pożarowej niewymienionej w pkt 1, z wyjątkiem zakwalifikowanej do kategorii zagrożenia ludzi ZL IV. 4. Wyposażenie w gaśnice magazynów, w których są składowane butle z gazem płynnym, oraz stacji paliw płynnych określa rozporządzenie Ministra Gospodarki z dnia 21 listopada 2005 r. w sprawie warunków technicznych, jakim powinny odpowiadać bazy i stacje paliw płynnych, rurociągi przesyłowe dalekosiężne służące do transportu ropy naftowej i produktów naftowych i ich usytuowanie. 5. Miejsce omłotów, niezależnie od wymaganych gaśnic, musi być wyposażone w pojemnik z wodą o objętości co najmniej 200 dm3, przygotowany do wykorzystania w celach gaśniczych z użyciem wiadra lub w inny równorzędny sposób."}], "162": [{"ref": "PN-EN 15004-1:2008 – urządzenia gaśnicze gazowe", "kind": "norma"}], "164": [{"ref": "art. 10 ustawy o wyrobach budowlanych; art. 6a ustawy o ochronie ppoż.", "kind": "akt", "act": "wyroby", "label": "art. 10", "text": "Art. 10. 1. Dopuszczone do jednostkowego zastosowania w obiekcie budowlanym są wyroby budowlane, z wyłączeniem wyrobów, o których mowa w art. 5 ust. 1, wykonane według indywidualnej dokumentacji technicznej, sporządzonej przez projektanta obiektu lub z nim uzgodnionej, dla których producent wydał oświadczenie, że zapewniono zgodność wyrobu budowlanego z tą dokumentacją oraz z przepisami. 2. Indywidualna dokumentacja techniczna, o której mowa w ust. 1, powinna zawierać opis rozwiązania konstrukcyjnego, charakterystykę materiałową i informację dotyczącą projektowanych właściwości użytkowych wyrobu budowlanego oraz określać warunki jego zastosowania w danym obiekcie budowlanym, a także, w miarę potrzeb, instrukcję obsługi i eksploatacji. 3. Oświadczenie, o którym mowa w ust. 1, powinno zawierać: 1) nazwę i adres wydającego oświadczenie; 2) nazwę wyrobu budowlanego i miejsce jego wytworzenia; […]"}], "166": [{"ref": "PN-EN 12845 – urządzenia tryskaczowe, punkt projektowy", "kind": "norma"}], "167": [{"ref": "§ 27, § 28, § 29 RPB – wyposażenie obiektów w urządzenia ppoż.", "kind": "akt", "act": "rpb", "label": "§ 27", "text": "§ 27. […] 2) muzeach oraz zabytkach budowlanych, wyznaczonych przez Generalnego Konserwatora Zabytków w uzgodnieniu z Komendantem Głównym Państwowej Straży Pożarnej; 3) ośrodkach elektronicznego przetwarzania danych o znaczeniu krajowym. 2. Stosowanie stałych samoczynnych urządzeń gaśniczych wodnych jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych, w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 8000 m2, b) wielokondygnacyjnych, w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 5000 m2; 2) w budynkach o liczbie miejsc służących celom gastronomicznym powyżej 600; 3) budynkach użyteczności publicznej wysokościowych; 4) budynkach zamieszkania zbiorowego wysokościowych. 3. […]"}], "168": [{"ref": "PN-HD 60364-5-56 – instalacje bezpieczeństwa", "kind": "norma"}], "169": [{"ref": "§ 271, § 216 WT – usytuowanie budynku i klasy ścian zewnętrznych", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20 2. […]"}], "170": [{"ref": "rozp. w sprawie warunków technicznych drogowych obiektów inżynierskich; § 10 RW", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. 1. Na sieci wodociągowej przeciwpożarowej stosuje się hydranty zewnętrzne nadziemne o średnicy nominalnej DN 80. 2. Dopuszcza się instalowanie hydrantów podziemnych o średnicy nominalnej DN 80 w przypadkach, gdy zainstalowanie hydrantów nadziemnych jest szczególnie utrudnione lub niewskazane, na przykład ze względu na utrudnienia w ruchu. 3. W obiekcie budowlanym produkcyjnym i magazynowym, w którym wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru przekracza 30 dm3/s, w zakładach rafineryjnych i petrochemicznych oraz na magistralnym przewodzie wodociągowym przeciwpożarowym należy instalować hydranty nadziemne o średnicy nominalnej DN 100. 4. Hydranty zewnętrzne zainstalowane na sieci wodociągowej przeciwpożarowej powinny być wyposażone w odcięcia umożliwiające odłączania ich od sieci. […]"}], "172": [{"ref": "PN-EN 81-58:2005 – próba odporności ogniowej drzwi przystankowych", "kind": "norma"}], "173": [{"ref": "§ 181 WT – awaryjne oświetlenie ewakuacyjne", "kind": "akt", "act": "wt", "label": "§ 181", "text": "§ 181. […] 3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego. 4. […]"}], "175": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "176": [{"ref": "§ 234 WT – wyprowadzenie ścian oddzielenia ppoż.", "kind": "akt", "act": "wt", "label": "§ 234", "text": "§ 234. 1. Przepusty instalacyjne w elementach oddzielenia przeciwpożarowego powinny mieć klasę odporności ogniowej (E I) wymaganą dla tych elementów. 2. Dopuszcza się nieinstalowanie przepustów, o których mowa w ust. 1, dla pojedynczych rur instalacji wodnych, kanalizacyjnych i ogrzewczych, wprowadzanych przez ściany i stropy do pomieszczeń higienicznosanitarnych. 3. Przepusty instalacyjne o średnicy większej niż 0,04 m w ścianach i stropach pomieszczenia zamkniętego, dla których wymagana klasa odporności ogniowej jest nie niższa niż E I 60 lub R E I 60, a niebędących elementami oddzielenia przeciwpożarowego, powinny mieć klasę odporności ogniowej (E I) ścian i stropów tego pomieszczenia. 4. Przejścia instalacji przez zewnętrzne ściany budynku, znajdujące się poniżej poziomu terenu, powinny być zabezpieczone przed możliwością przenikania gazu do wnętrza budynku."}], "177": [{"ref": "PN-EN 12845 – powierzchnia chroniona przez tryskacz", "kind": "norma"}], "178": [{"ref": "§ 212, § 216 WT – klasa D, wymagane klasy odporności ogniowej", "kind": "akt", "act": "wt", "label": "§ 212", "text": "§ 212. 1. Ustanawia się pięć klas odporności pożarowej budynków lub ich części, podanych w kolejności od najwyższej do najniższej i oznaczonych literami: „A”, „B”, „C”, „D” i „E”, a scharakteryzowanych w § 216. 2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A” 3. Dopuszcza się obniżenie wymaganej klasy odporności pożarowej w budynkach wymienionych w poniższej tabeli do poziomu w niej określonego. Liczba kondygnacji nadziemnych ZL I ZL II ZL III 1 2 3 4 1 „D” „D” „D” 2*) „C” „C” „D” *) Gdy poziom stropu nad pierwszą kondygnacją nadziemną jest na wysokości nie większej niż 9 m nad poziomem terenu. 4. […]"}], "179": [{"ref": "PN-EN 60079-10-1:2016-02 – klasyfikacja przestrzeni", "kind": "norma"}], "180": [{"ref": "§ 19 RPB – hydranty wewnętrzne w strefach ZL", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. 1. Hydranty 25 muszą być stosowane w strefach pożarowych zakwalifikowanych do kategorii zagrożenia ludzi ZL: 1) na każdej kondygnacji budynku wysokiego i wysokościowego, z wyjątkiem kondygnacji obejmującej wyłącznie strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL IV; […]"}], "181": [{"ref": "PN-B-02852:2001 – obliczanie gęstości obciążenia ogniowego", "kind": "norma"}], "182": [{"ref": "§ 232 WT – otwory w ścianach oddzielenia ppoż.", "kind": "akt", "act": "wt", "label": "§ 232", "text": "§ 232. 1. Ściany i stropy stanowiące elementy oddzielenia przeciwpożarowego powinny być wykonane z materiałów niepalnych, a występujące w nich otwory – obudowane przedsionkami przeciwpożarowymi lub zamykane za pomocą drzwi przeciwpożarowych bądź innego zamknięcia przeciwpożarowego. 2. W ścianie oddzielenia przeciwpożarowego łączna powierzchnia otworów, o których mowa w ust. 1, nie powinna przekraczać 15% powierzchni ściany, a w stropie oddzielenia przeciwpożarowego – 0,5% powierzchni stropu. Ograniczenia nie stosuje się do otworów w ścianach oddzielenia przeciwpożarowego w garażu, które znajdują się na drogach manewrowych. 3. […]"}], "183": [{"ref": "§ 225 WT – pas międzykondygnacyjny", "kind": "akt", "act": "wt", "label": "§ 225", "text": "§ 225. Elementy okładzin elewacyjnych powinny być mocowane do konstrukcji budynku w sposób uniemożliwiający ich odpadanie w przypadku pożaru w czasie krótszym niż wynikający z wymaganej klasy odporności ogniowej dla ściany zewnętrznej, określonej w § 216 ust. 1, odpowiednio do klasy odporności pożarowej budynku, w którym są one zamocowane. Rozdział 3 Strefy pożarowe i oddzielenia przeciwpożarowe"}], "185": [{"ref": "§ 249 WT – przeszklenia przy narożach/ścianach prostopadłych", "kind": "akt", "act": "wt", "label": "§ 249", "text": "§ 249. 1. Ściany wewnętrzne i stropy stanowiące obudowę klatki schodowej lub pochylni powinny mieć klasę odporności ogniowej określoną zgodnie z § 216, jak dla stropów budynku. 2. (uchylony). 3. Biegi i spoczniki schodów oraz pochylnie służące do ewakuacji powinny być wykonane z materiałów niepalnych i mieć klasę odporności ogniowej co najmniej: 1) w budynkach o klasie odporności pożarowej „A”, „B” i „C” – R 60; 2) w budynkach o klasie odporności pożarowej „D” i „E” – R 30. 4. Wymaganie klasy odporności ogniowej, o którym mowa w ust. 3, nie dotyczy klatek schodowych wydzielonych na każdej kondygnacji przedsionkami przeciwpożarowymi oraz schodów na antresolę w pomieszczeniu, w którym się ona znajduje, jeżeli antresola ta jest przeznaczona do użytku nie więcej niż 10 osób. 5. […]"}], "186": [{"ref": "§ 284 pkt 1 WT – drogi ewakuacyjne w budynkach inwentarskich", "kind": "akt", "act": "wt", "label": "§ 284", "text": "§ 284. Budynek IN powinien spełniać następujące wymagania ewakuacyjne: 1) odległość od najdalszego stanowiska dla zwierząt do wyjścia ewakuacyjnego nie powinna przekraczać przy ściółkowym utrzymaniu zwierząt – 50 m, a przy bezściółkowym – 75 m; 2) w bezściółkowym chowie bydła, trzody chlewnej i owiec, jeżeli liczba bydła i trzody chlewnej nie przekracza 15 sztuk, a owiec – 200 sztuk, należy stosować co najmniej jedno wyjście ewakuacyjne; 3) w budynku przeznaczonym dla większej liczby zwierząt aniżeli wymieniona w pkt 2 należy stosować co najmniej dwa wyjścia, a z pomieszczeń podzielonych na sekcje – co najmniej jedno wyjście ewakuacyjne z każdej sekcji; 4) wrota i drzwi w budynku inwentarskim powinny otwierać się na zewnątrz pomieszczenia."}], "187": [{"ref": "§ 256 WT – podział korytarzy ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "§ 256. […] 3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej. 4. […]"}], "188": [{"ref": "PKN-CEN/TS 54-14:2006 – rozmieszczenie czujek, wpływ belek", "kind": "norma"}], "189": [{"ref": "PN-EN 12101-6 – systemy różnicowania ciśnień, klasa F", "kind": "norma"}], "190": [{"ref": "§ 239, § 245 WT – wymagania dla drzwi na drogach ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 239", "text": "§ 239. […] 2. Drzwi stanowiące wyjście ewakuacyjne powinny otwierać się na zewnątrz pomieszczeń: 1) zagrożonych wybuchem; 2) do których jest możliwe niespodziewane przedostanie się mieszanin wybuchowych lub substancji trujących, duszących bądź innych, mogących utrudnić ewakuację; 3) przeznaczonych do jednoczesnego przebywania ponad 50 osób; 4) przeznaczonych dla ponad 6 osób o ograniczonej zdolności poruszania się. 3. Wyjścia ewakuacyjne z pomieszczenia zagrożonego wybuchem na drogę ewakuacyjną powinny prowadzić przez przedsionki przeciwpożarowe odpowiadające wymaganiom § 232. 4. Szerokość drzwi stanowiących wyjście ewakuacyjne z budynku, z zastrzeżeniem ust. 1, a także szerokość drzwi na drodze ewakuacyjnej z klatki schodowej, prowadzących na zewnątrz budynku lub do innej strefy pożarowej, powinna być nie mniejsza niż szerokość biegu klatki schodowej, określona zgodnie z § 68 ust. 1 i 2. 5. […]"}], "191": [{"ref": "§ 3–5 RW – przypadki niewymagające zewnętrznego zaopatrzenia w wodę", "kind": "akt", "act": "rw", "label": "§ 3", "text": "§ 3. 1. Zapewnienie przeciwpożarowego zaopatrzenia w wodę do zewnętrznego gaszenia pożaru jest wymagane dla: 1) jednostek osadniczych o liczbie mieszkańców przekraczającej 100 osób, niestanowiących zabudowy kolonijnej, a także znajdujących się w ich granicach: budynków użyteczności publicznej i zamieszkania zbiorowego oraz obiektów budowlanych produkcyjnych i magazynowych; 2) budynków użyteczności publicznej i zamieszkania zbiorowego oraz obiektów budowlanych produkcyjnych i magazynowych, znajdujących się poza granicami jednostek osadniczych wymienionych w pkt 1, o kubaturze brutto przekraczającej 2 500 m3 lub o powierzchni przekraczającej 500 m2, z wyjątkiem stacji paliw płynnych ze zbiornikami o łącznej pojemności do 200 m3 i stacji gazu płynnego; […]"}], "192": [{"ref": "§ 236 WT – kierunek otwierania drzwi ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 236", "text": "§ 236. 1. Z pomieszczeń przeznaczonych na pobyt ludzi powinna być zapewniona możliwość ewakuacji w bezpieczne miejsce na zewnątrz budynku lub do sąsiedniej strefy pożarowej, bezpośrednio albo drogami komunikacji ogólnej, zwanymi dalej „drogami ewakuacyjnymi”. 2. Ze strefy pożarowej, o której mowa w ust. 1, powinno być wyjście bezpośrednio na zewnątrz budynku lub przez inną strefę pożarową, z zastrzeżeniem § 227 ust. 5. 3. Wyjścia z pomieszczeń na drogi ewakuacyjne powinny być zamykane drzwiami. 4. Drzwi stanowiące wyjście ewakuacyjne z budynku przeznaczonego dla więcej niż 50 osób powinny otwierać się na zewnątrz. Wymaganie to nie dotyczy budynku wpisanego do rejestru zabytków. 5. W wyjściu ewakuacyjnym z budynku dopuszcza się stosowanie drzwi rozsuwanych spełniających wymagania określone w § 240 ust. 4. 6. […]"}], "193": [{"ref": "§ 245, § 256 WT – obudowa i zamknięcie klatek schodowych", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}], "194": [{"ref": "§ 193, § 207 WT – dźwigi dla ekip ratowniczych i dojścia", "kind": "akt", "act": "wt", "label": "§ 193", "text": "§ 193. 1. W budynkach, o których mowa w § 54 ust. 1 i 2, liczbę i parametry techniczno-użytkowe dźwigów należy ustalać z uwzględnieniem przeznaczenia budynku, jego wysokości oraz liczby i rodzaju użytkowników. 2. Co najmniej jeden z dźwigów służących komunikacji ogólnej w budynku z pomieszczeniami przeznaczonymi na pobyt ludzi, a także w każdej wydzielonej w pionie, odrębnej części (segmencie) takiego budynku, powinien być przystosowany do przewozu mebli, chorych na noszach i osób niepełnosprawnych. 2a. Kabina dźwigu osobowego dostępna dla osób niepełnosprawnych powinna mieć szerokość co najmniej 1,1 m i długość 1,4 m, poręcze na wysokości 0,9 m oraz tablicę przyzywową na wysokości od 0,8 m do 1,2 m w odległości nie mniejszej niż 0,5 m od naroża kabiny z dodatkowym oznakowaniem dla osób niewidomych i informacją głosową. 3. […]"}], "195": [{"ref": "PKN-CEN/TS 54-14:2006 – strefy dozorowe", "kind": "norma"}], "196": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego i powiększenia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "197": [{"ref": "PN-EN 12845 – zbiornik pośredni", "kind": "norma"}], "198": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "199": [{"ref": "§ 227 ust. 1 i 4 WT – powierzchnie stref ZL i ich powiększanie", "kind": "akt", "act": "wt", "label": "§ 227", "text": "§ 227. 1. Dopuszczalne powierzchnie stref pożarowych ZL określa poniższa tabela: Kategoria zagrożenia ludzi Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim (N) średniowysokim (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 ZL I, ZL III, ZL IV, ZL V 10 000 8000 5000 2500 ZL II 8000 5000 3500 2000"}], "200": [{"ref": "§ 6–7 RW – ilość wody dla obiektów innych niż budynki", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. […] 1753). 7. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla urządzeń technologicznych oraz składów i magazynów z gazami palnymi i cieczami o temperaturze zapłonu do 373,15 K (100 °C), zlokalizowanych poza budynkami, określa tabela nr 4 załącznika do rozporządzenia. 8. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla silosów, komór i zasobników ze stałymi sypkimi materiałami palnymi oraz dla zbiorników z cieczami palnymi o temperaturze zapłonu powyżej 373,15 K (100 °C) wynosi 10 dm3/s. 9. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla obiektów budowlanych gospodarki rolnej należy zapewnić w następujących ilościach: 1) dla obiektów o powierzchni strefy pożarowej do 2 000 m2 — co najmniej 10 dm3/s; 2) dla obiektów o powierzchni strefy pożarowej przekraczającej 2 000 m2 — co najmniej 15 dm3/s. 10. […]"}], "201": [{"ref": "§ 11 RPB / przepisy dot. magazynowania gazów palnych", "kind": "akt", "act": "rpb", "label": "§ 11", "text": "§ 11. 1. Dopuszcza się przechowywanie paliw płynnych klasy III, na potrzeby własne użytkownika, w zbiorniku naziemnym dwupłaszczowym o pojemności do 5 m3. 2. Zbiornik do przechowywania paliw płynnych klasy III na potrzeby własne użytkownika, o którym mowa w ust. 1, należy sytuować z zachowaniem następujących odległości: 1) 10 m ‒ od budynków mieszkalnych i budynków użyteczności publicznej; 2) 5 m ‒ od innych obiektów budowlanych i od granicy działki sąsiedniej. 3. Odległości, o których mowa w ust. 2, mogą być zmniejszone o połowę, pod warunkiem zastosowania pomiędzy budynkiem lub obiektem a zbiornikiem ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej REI 120 zasłaniającej zbiornik od strony budynku lub obiektu. 3) Ustawa utraciła moc na podstawie art. 174 ustawy z dnia 13 czerwca 2019 r. […]"}], "203": [{"ref": "§ 3 pkt 1a WT – definicja działki budowlanej", "kind": "akt", "act": "wt", "label": "§ 3", "text": "§ 3. Ilekroć w rozporządzeniu jest mowa o: 1) zabudowie śródmiejskiej – należy przez to rozumieć zgrupowanie intensywnej zabudowy na obszarze śródmieścia, określonej w miejscowym planie zagospodarowania przestrzennego, a w przypadku braku planu miejscowego w studium uwarunkowań i kierunków zagospodarowania przestrzennego gminy; 1a) działce budowlanej – należy przez to rozumieć nieruchomość gruntową lub działkę gruntu, której wielkość, cechy geometryczne, dostęp do drogi publicznej oraz wyposażenie w urządzenia infrastruktury technicznej spełniają wymogi realizacji obiektów budowlanych wynikające z rozporządzenia, odrębnych przepisów i aktów prawa miejscowego; 2) zabudowie jednorodzinnej – należy przez to rozumieć jeden budynek mieszkalny jednorodzinny lub zespół takich budynków, wraz z budynkami garażowymi i gospodarczymi; […]"}], "204": [{"ref": "§ 12 RW – wymóg drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; 4) budynku zawierającego strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego poniżej 500 MJ/m2 o powierzchni przekraczającej 20 000 m2; […]"}], "205": [{"ref": "§ 6 RW – ilość wody dla obiektów innych niż budynki", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. […] U. Nr 243, poz. 2063 oraz z 2007 r. Nr 240, poz. 1753). 7. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla urządzeń technologicznych oraz składów i magazynów z gazami palnymi i cieczami o temperaturze zapłonu do 373,15 K (100 °C), zlokalizowanych poza budynkami, określa tabela nr 4 załącznika do rozporządzenia. 8. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla silosów, komór i zasobników ze stałymi sypkimi materiałami palnymi oraz dla zbiorników z cieczami palnymi o temperaturze zapłonu powyżej 373,15 K (100 °C) wynosi 10 dm3/s. 9. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla obiektów budowlanych gospodarki rolnej należy zapewnić w następujących ilościach: 1) dla obiektów o powierzchni strefy pożarowej do 2 000 m2 — co najmniej 10 dm3/s; […]"}], "207": [{"ref": "PN-EN 12845 – klasy zagrożenia (LH/OH/HH)", "kind": "norma"}], "208": [{"ref": "PN-EN 12845 – dobór tryskaczy w instalacjach suchych", "kind": "norma"}], "210": [{"ref": "§ 212 WT – klasa odporności pożarowej", "kind": "akt", "act": "wt", "label": "§ 212", "text": "§ 212. 1. Ustanawia się pięć klas odporności pożarowej budynków lub ich części, podanych w kolejności od najwyższej do najniższej i oznaczonych literami: „A”, „B”, „C”, „D” i „E”, a scharakteryzowanych w § 216. 2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A” 3. Dopuszcza się obniżenie wymaganej klasy odporności pożarowej w budynkach wymienionych w poniższej tabeli do poziomu w niej określonego. Liczba kondygnacji nadziemnych ZL I ZL II ZL III 1 2 3 4 1 „D” „D” „D” 2*) „C” „C” „D” *) Gdy poziom stropu nad pierwszą kondygnacją nadziemną jest na wysokości nie większej niż 9 m nad poziomem terenu. 4. […]"}], "211": [{"ref": "PN-EN 13501-1 – klasyfikacja izolacji przewodów; WT", "kind": "norma"}], "212": [{"ref": "§ 28 ust. 1 pkt 3 RPB – obiekty wymagające SSP", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}], "213": [{"ref": "ustawa o wyrobach budowlanych – krajowa ocena techniczna", "kind": "norma"}], "215": [{"ref": "art. 3 pkt 7a ustawy – Prawo budowlane (definicja przebudowy)", "kind": "akt", "act": "pb", "label": "art. 3", "text": "Art. 3. […] 2) budynku – należy przez to rozumieć taki obiekt budowlany, który jest trwale związany z gruntem, wydzielony z przestrzeni za pomocą przegród budowlanych oraz posiada fundamenty i dach; 2a) budynku mieszkalnym jednorodzinnym – należy przez to rozumieć budynek wolno stojący albo budynek w zabudowie bliźniaczej, szeregowej lub grupowej, służący zaspokajaniu potrzeb mieszkaniowych, stanowiący konstrukcyjnie samodzielną całość, w którym dopuszcza się wydzielenie nie więcej niż dwóch lokali mieszkalnych albo jednego lokalu mieszkalnego i lokalu użytkowego o powierzchni całkowitej nieprzekraczającej 30 % powierzchni całkowitej budynku; […]"}], "216": [{"ref": "§ 4 rozp. w sprawie uzgadniania projektu pod względem ochrony ppoż.", "kind": "akt", "act": "uzgadnianie", "label": "§ 4", "text": "§ 4. […] Podstawę uzgodnienia stanowią niezbędne do stwierdzenia zgodności projektu z wymaganiami ochrony przeciwpożarowej dane dotyczące warunków ochrony przeciwpożarowej obiektu budowlanego, zależne od jego przeznaczenia, sposobu użytkowania, prowadzonego procesu technologicznego, sposobu magazynowania lub składowania, warunków technicznych oraz występujących w nim zagrożeń pożarowych, obejmujące: 1) w przypadku projektu zagospodarowania działki lub terenu, w szczególności: a) informacje o powierzchni zabudowy, wysokości i liczbie kondygnacji, b) informacje o klasyfikacji pożarowej z uwagi na przeznaczenie i sposób użytkowania, c) informacje o klasie odporności pożarowej oraz odporności ogniowej i stopniu rozprzestrzeniania ognia przez ściany zewnętrzne i dachy, d) informacje o występowaniu zagrożenia wybuchem, w tym informacje dotyczące pomieszczeń zagrożonych wybuchem oraz stref zagrożenia wybuchem w przestrzeni zewnętrznej, e) informacje o usytuowaniu z uwagi na bezpieczeństwo pożarowe, w tym informacje o odległościach od sąsiadujących obiektów budowlanych, działek lub terenów oraz parametrach wpływających na odległości dopuszczalne, f) informacje o przygotowaniu obiektu budowlanego i terenu do prowadzenia działań ratowniczych, w tym informacje o: – drogach pożarowych oraz dojściach dla ekip ratowniczych, – zaopatrzeniu w wodę do zewnętrznego gaszenia pożaru, w tym o wymaganej ilości wody do celów przeciwpożarowych, urządzeniach i innych rozwiązaniach w zakresie przeciwpożarowego zaopatrzenia w wodę, usytuowaniu źródeł wody do celów przeciwpożarowych, hydrantów zewnętrznych lub innych punktów poboru wody oraz stanowisk czerpania wody wraz z dojazdami dla pojazdów pożarniczych, g) informacje o rozwiązaniach zamiennych w stosunku do wymagań ochrony przeciwpożarowej, zastosowanych na podstawie zgody, o której mowa w art. 6c pkt 1 lub 2 ustawy z dnia 24 sierpnia 1991 r. o ochronie przeciwpożarowej, w zakresie rozwiązań objętych projektem zagospodarowania działki lub terenu; […]"}], "217": [{"ref": "§ 216 ust. 8 WT; PN-B-02867", "kind": "norma"}], "218": [{"ref": "§ 29 RPB / PN-EN 54 – dźwiękowy system ostrzegawczy", "kind": "norma"}], "220": [{"ref": "PN-EN 12845 – wydatek tryskacza", "kind": "norma"}], "221": [{"ref": "§ 19 RPB – dobór hydrantów wewnętrznych", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. […] 2. Hydranty 33 muszą być stosowane w garażu: 1) jednokondygnacyjnym zamkniętym o więcej niż 10 stanowiskach postojowych; 2) wielokondygnacyjnym. 3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; 3) przy wejściu do pomieszczeń magazynowych lub technicznych o powierzchni przekraczającej 200 m2 i gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, usytuowanych w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II, ZL III lub ZL V, znajdującej się w budynku niskim albo średniowysokim. 4. […]"}], "223": [{"ref": "§ 245 WT – obudowa i zamykanie klatek schodowych", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}], "225": [{"ref": "PN-B-02857:2017 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "226": [{"ref": "§ 227 WT – powiększanie powierzchni stref pożarowych", "kind": "akt", "act": "wt", "label": "§ 227", "text": "§ 227. […] 3. Zmniejszenie dopuszczalnej powierzchni strefy pożarowej, o której mowa w ust. 2, nie dotyczy przypadku, gdy wyjścia ewakuacyjne z kondygnacji podziemnej prowadzą bezpośrednio na zewnątrz budynku. 4. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w ust. 1, z wyjątkiem stref pożarowych w wielokondygnacyjnych budynkach wysokich (W) i wysokościowych (WW), pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 100%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 100%. Przy jednoczesnym stosowaniu urządzeń wymienionych w pkt 1 i 2 dopuszcza się powiększenie powierzchni stref pożarowych o 200%. 5. Ze strefy pożarowej ZL II o powierzchni przekraczającej 750 m2 w budynku wielokondygnacyjnym, powinna być zapewniona możliwość ewakuacji ludzi do innej strefy pożarowej na tej samej kondygnacji."}], "227": [{"ref": "§ 17 RPB – praktyczne sprawdzenie warunków ewakuacji", "kind": "akt", "act": "rpb", "label": "§ 17", "text": "§ 17. […] 2. W przypadku obiektów, w których cyklicznie zmienia się jednocześnie grupa powyżej 50 użytkowników, w szczególności: szkół, przedszkoli, internatów, domów studenckich, praktycznego sprawdzenia organizacji oraz warunków ewakuacji należy dokonać ‒ co najmniej raz na rok, jednak w terminie nie dłuższym niż 3 miesiące od dnia rozpoczęcia korzystania z obiektu przez nowych użytkowników. 3. W przypadku obiektu zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL II oraz w budynkach zakwaterowania osadzonych zlokalizowanych na terenach zakładów karnych i aresztów śledczych, zakres i obszar budynku objęty praktycznym sprawdzeniem organizacji i warunków ewakuacji musi być uzgodniony z właściwym miejscowo komendantem powiatowym (miejskim) Państwowej Straży Pożarnej. 4. […]"}], "228": [{"ref": "§ 253 WT – wyjścia na strych/dach", "kind": "akt", "act": "wt", "label": "§ 253", "text": "§ 253. 1. W budynku ZL I, ZL II, ZL III lub ZL V, mającym kondygnację z posadzką na wysokości powyżej 25 m ponad poziomem terenu przy najniżej położonym wejściu do budynku oraz w budynku wysokościowym (WW) ZL IV przynajmniej jeden dźwig powinien być przystosowany do potrzeb ekip ratowniczych, spełniając wymagania Polskiej Normy dotyczącej dźwigów dla straży pożarnej. Dźwig dla ekip ratowniczych powinien zapewniać dostęp do każdej strefy pożarowej na kondygnacji bezpośrednio lub drogami komunikacji ogólnej. 2. Dojście do dźwigu dla ekip ratowniczych powinno prowadzić przez przedsionek przeciwpożarowy spełniający wymagania określone w § 232. 3. Ściany i stropy szybu dźwigu dla ekip ratowniczych powinny mieć klasę odporności ogniowej wymaganą jak dla stropów budynku, zgodnie z § 216. 4. Szyb dźwigu dla ekip ratowniczych powinien być wyposażony w urządzenia zapobiegające zadymieniu."}], "230": [{"ref": "§ 236 WT – kierunek otwierania drzwi ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 236", "text": "§ 236. 1. Z pomieszczeń przeznaczonych na pobyt ludzi powinna być zapewniona możliwość ewakuacji w bezpieczne miejsce na zewnątrz budynku lub do sąsiedniej strefy pożarowej, bezpośrednio albo drogami komunikacji ogólnej, zwanymi dalej „drogami ewakuacyjnymi”. 2. Ze strefy pożarowej, o której mowa w ust. 1, powinno być wyjście bezpośrednio na zewnątrz budynku lub przez inną strefę pożarową, z zastrzeżeniem § 227 ust. 5. 3. Wyjścia z pomieszczeń na drogi ewakuacyjne powinny być zamykane drzwiami. 4. Drzwi stanowiące wyjście ewakuacyjne z budynku przeznaczonego dla więcej niż 50 osób powinny otwierać się na zewnątrz. Wymaganie to nie dotyczy budynku wpisanego do rejestru zabytków. 5. W wyjściu ewakuacyjnym z budynku dopuszcza się stosowanie drzwi rozsuwanych spełniających wymagania określone w § 240 ust. 4. 6. […]"}], "233": [{"ref": "§ 308 WT – wyłazy i klapy wyjściowe", "kind": "akt", "act": "wt", "label": "§ 308", "text": "§ 308. 1. W budynkach o dwóch lub więcej kondygnacjach nadziemnych należy zapewnić wyjście na dach co najmniej z jednej klatki schodowej, umożliwiające dostęp na dach i do urządzeń technicznych tam zainstalowanych. 2. W budynkach wysokich (W) i wysokościowych (WW) wyjścia, o których mowa w ust. 1, należy zapewnić z każdej klatki schodowej. 3. Jako wyjście z klatki schodowej na dach należy stosować drzwi o szerokości 0,8 m i wysokości co najmniej 1,9 m lub klapy wyłazowe o wymiarze 0,8 x 0,8 m w świetle, do których dostęp powinien odpowiadać warunkom określonym w § 101. 4. Na dachu o spadku ponad 25% oraz na dachu pokrytym materiałami łamliwymi (tłukącymi) należy wykonać stałe dojścia do kominów, urządzeń technicznych oraz anten radiowych i telewizyjnych. 5. Dojścia, o których mowa w ust. 4, na odcinkach o nachyleniu ponad 25% powinny mieć zabezpieczenia przed poślizgiem. 6. […]"}], "234": [{"ref": "§ 230 WT – obniżenie klasy przy zastosowaniu SUG wodnego", "kind": "akt", "act": "wt", "label": "§ 230", "text": "§ 230. 1. W budynku jednokondygnacyjnym lub na ostatniej kondygnacji budynku wielokondygnacyjnego wielkości stref pożarowych PM, z wyjątkiem garaży, można powiększyć o 100%, jeżeli budynek nie zawiera pomieszczenia zagrożonego wybuchem i jest wykonany z elementów nierozprzestrzeniających ognia oraz zastosowano samoczynne urządzenia oddymiające. 2. W budynku jednokondygnacyjnym wielkości stref pożarowych PM, z wyjątkiem garażu, nie ogranicza się, pod warunkiem zastosowania stałych samoczynnych urządzeń gaśniczych wodnych i samoczynnych urządzeń oddymiających."}], "235": [{"ref": "PKN-CEN/TS 54-14:2006 – wpływ przegród na rozmieszczenie czujek", "kind": "norma"}], "236": [{"ref": "§ 229 WT – powiększanie powierzchni stref pożarowych PM", "kind": "akt", "act": "wt", "label": "§ 229", "text": "§ 229. 1. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w § 228, pod warunkiem ich ochrony: 1) stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 100%; 2) samoczynnymi urządzeniami oddymiającymi – o 50%. 2. Przy jednoczesnym stosowaniu urządzeń wymienionych w ust. 1 dopuszcza się powiększenie stref pożarowych o 150%."}], "237": [{"ref": "§ 261 / § 258 WT – wymagania dla wyposażenia sal", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. Pomieszczenia przeznaczone do jednoczesnego przebywania ponad 200 osób dorosłych lub 100 dzieci, w których miejsca do siedzenia są ustawione w rzędach, powinny mieć: 1) fotele i inne siedzenia trudno zapalne oraz niewydzielające produktów rozkładu i spalania, określonych jako bardzo toksyczne, zgodnie z Polską Normą dotyczącą badań wydzielania produktów toksycznych; określenie trudno zapalny przypisuje się fotelom i innym siedzeniom, które nie ulegają postępującemu tleniu i spalaniu płomieniowemu w warunkach określonych Polską Normą dotyczącą badania zapalności mebli tapicerowanych; 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; […]"}], "238": [{"ref": "§ 278 ust. 2 i 3 WT – przejścia ewakuacyjne w garażach", "kind": "akt", "act": "wt", "label": "§ 278", "text": "2. W przypadku strefy pożarowej garażu obejmującej więcej niż dwie kondygnacje wyjścia ewakuacyjne należy zapewnić na poziomie każdej kondygnacji. Długość przejścia od stanowiska postojowego do najbliższego wyjścia ewakuacyjnego nie może przekraczać: 1) w garażu zamkniętym – 40 m; 2) w garażu otwartym – 60 m."}], "239": [{"ref": "PN-EN 60079-10-1 / ATEX – klasyfikacja stref", "kind": "norma"}], "240": [{"ref": "PKN-CEN/TS 54-14:2006 – promienie działania czujek", "kind": "norma"}], "241": [{"ref": "§ 212 ust. 4 WT – budynki jednokondygnacyjne; § 230 WT", "kind": "akt", "act": "wt", "label": "§ 212", "text": "4. Wymaganą klasę odporności pożarowej dla budynku PM oraz IN, z zastrzeżeniem § 282, określa poniższa tabela: Maksymalna gęstość obciążenia ogniowego strefy pożarowej w budynku Q [MJ/m2] Budynek o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) Budynek wielokondygnacyjny niski średniowysoki wysoki wysokościowy (N) (SW) (W) (WW) 1 2 3 4 5 6 Q ≤ 500 „E” „D” „C” „B” „B” 500 < Q ≤ 1000 „D” „D” „C” „B” „B” 1000 < Q ≤ 2000 „C” „C” „C” „B” „B” 2000 < Q ≤ 4000 „B” „B” „B” * * Q > 4000 „A” „A” „A” * * * – Zgodnie z § 228 ust. 1 nie mogą występować takie budynki."}], "242": [{"ref": "§ 256 WT – obudowa poziomych dróg ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "§ 256. 1. Długość drogi ewakuacyjnej od wyjścia z pomieszczenia na tę drogę do wyjścia do innej strefy pożarowej lub na zewnątrz budynku, zwanej dalej „dojściem ewakuacyjnym”, mierzy się wzdłuż osi drogi ewakuacyjnej. W przypadku zakończenia dojścia ewakuacyjnego przedsionkiem przeciwpożarowym, długość tę mierzy się do pierwszych drzwi tego przedsionka. 2. Za równorzędne wyjściu do innej strefy pożarowej, o którym mowa w ust. 1, uważa się wyjście do obudowanej klatki schodowej, zamykanej drzwiami o klasie odporności ogniowej co najmniej E I 30, wyposażonej w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, a w przypadku, o którym mowa w § 246 ust. 5 – zamykanej drzwiami dymoszczelnymi. 3. […]"}], "243": [{"ref": "rozp. w sprawie warunków technicznych drogowych obiektów inżynierskich; PN-EN 12101-3", "kind": "norma"}], "244": [{"ref": "§ 258 WT – wykończenie wnętrz na drogach ewakuacyjnych i w pomieszczeniach", "kind": "akt", "act": "wt", "label": "§ 258", "text": "§ 258. 1. W strefach pożarowych ZL I, ZL II, ZL III i ZL V stosowanie do wykończenia wnętrz materiałów i wyrobów łatwo zapalnych, których produkty rozkładu termicznego są bardzo toksyczne lub intensywnie dymiące, jest zabronione. 1a. W przypadku stosowania materiałów wykończeniowych luźno zwisających, w szczególności w kurtynach, zasłonach, draperiach, kotarach oraz żaluzjach, za łatwo zapalne uważa się materiały, których właściwości określone w badaniach zgodnych z Polskimi Normami odnoszącymi się do zapalności i rozprzestrzeniania płomienia przez wyroby włókiennicze nie spełniają co najmniej jednego z kryteriów: 1) ti ≥ 4 s; 2) ts ≤ 30 s; 3) nie następuje przepalenie trzeciej nitki; 4) nie występują płonące krople. 2. Na drogach komunikacji ogólnej, służących celom ewakuacji, stosowanie materiałów i wyrobów budowlanych łatwo zapalnych jest zabronione."}], "246": [{"ref": "§ 132 WT – instalacje ogrzewcze na paliwo stałe", "kind": "akt", "act": "wt", "label": "§ 132", "text": "§ 132. 1. Budynek, który ze względu na swoje przeznaczenie wymaga ogrzewania, powinien być wyposażony w instalację ogrzewczą lub inne urządzenia ogrzewcze, niebędące piecami, trzonami kuchennymi lub kominkami. 2. Dopuszcza się stosowanie pieców i trzonów kuchennych na paliwo stałe w budynkach o wysokości do 3 kondygnacji nadziemnych włącznie, jeżeli nie jest to sprzeczne z ustaleniami miejscowego planu zagospodarowania przestrzennego, przy czym w budynkach zakładów opieki zdrowotnej5), opieki społecznej, przeznaczonych dla dzieci i młodzieży, lokalach gastronomicznych oraz pomieszczeniach przeznaczonych do produkcji żywności i środków farmaceutycznych – pod warunkiem uzyskania zgody właściwego państwowego inspektora sanitarnego. 3. […]"}], "248": [{"ref": "PKN-CEN/TS 54-14:2006 – rozmieszczenie czujek przy belkach", "kind": "norma"}], "249": [{"ref": "PN-EN 12101-2 – klasyfikacja klap dymowych", "kind": "norma"}], "250": [{"ref": "PN-B-02852:2001 – obliczanie gęstości obciążenia ogniowego", "kind": "norma"}], "251": [{"ref": "§ 278 ust. 2 pkt 2 i ust. 3 WT – przejścia ewakuacyjne w garażach", "kind": "akt", "act": "wt", "label": "§ 278", "text": "2. W przypadku strefy pożarowej garażu obejmującej więcej niż dwie kondygnacje wyjścia ewakuacyjne należy zapewnić na poziomie każdej kondygnacji. Długość przejścia od stanowiska postojowego do najbliższego wyjścia ewakuacyjnego nie może przekraczać: 1) w garażu zamkniętym – 40 m; 2) w garażu otwartym – 60 m."}], "252": [{"ref": "§ 237 WT – przejście w pomieszczeniu zagrożonym wybuchem", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. […] 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. Dopuszcza się prowadzenie przez pomieszczenie zagrożone wybuchem przejścia ewakuacyjnego z innego pomieszczenia, jeżeli pomieszczenia te są powiązane funkcjonalnie. 4. […]"}], "254": [{"ref": "§ 284 pkt 2 WT – wyjścia ewakuacyjne w budynkach inwentarskich", "kind": "akt", "act": "wt", "label": "§ 284", "text": "§ 284. Budynek IN powinien spełniać następujące wymagania ewakuacyjne: 1) odległość od najdalszego stanowiska dla zwierząt do wyjścia ewakuacyjnego nie powinna przekraczać przy ściółkowym utrzymaniu zwierząt – 50 m, a przy bezściółkowym – 75 m; 2) w bezściółkowym chowie bydła, trzody chlewnej i owiec, jeżeli liczba bydła i trzody chlewnej nie przekracza 15 sztuk, a owiec – 200 sztuk, należy stosować co najmniej jedno wyjście ewakuacyjne; 3) w budynku przeznaczonym dla większej liczby zwierząt aniżeli wymieniona w pkt 2 należy stosować co najmniej dwa wyjścia, a z pomieszczeń podzielonych na sekcje – co najmniej jedno wyjście ewakuacyjne z każdej sekcji; 4) wrota i drzwi w budynku inwentarskim powinny otwierać się na zewnątrz pomieszczenia."}], "255": [{"ref": "art. 42 ust. 4b ustawy o odpadach – operat przeciwpożarowy", "kind": "akt", "act": "odpady-ustawa", "label": "art. 42", "text": "4. Do wniosków, o których mowa w ust. 1 i 2, dołącza się decyzję o środowiskowych uwarunkowaniach, o której mowa w art. 71 ustawy z dnia 3 października 2008 r. o udostępnianiu informacji o środowisku i jego ochronie, udziale społeczeństwa w ochronie środowiska oraz o ocenach oddziaływania na środowisko, o ile jest wymagana."}], "256": [{"ref": "§ 2 RPB – definicja materiałów niebezpiecznych pożarowo", "kind": "akt", "act": "rpb", "label": "§ 2", "text": "§ 2. 1. Ilekroć w rozporządzeniu jest mowa o: 1) materiałach niebezpiecznych pożarowo ‒ należy przez to rozumieć: a) gazy palne, b) ciecze palne o temperaturze zapłonu poniżej 328,15 K (55ºC), c) materiały wytwarzające w zetknięciu z wodą gazy palne, d) materiały zapalające się samorzutnie na powietrzu, e) materiały wybuchowe i wyroby pirotechniczne, f) materiały ulegające samorzutnemu rozkładowi lub polimeryzacji, g) materiały mające skłonności do samozapalenia, h) materiały inne niż wymienione w lit. a‒g, jeśli sposób ich składowania, przetwarzania lub innego wykorzystania może spowodować powstanie pożaru; 2) pasie przeciwpożarowym ‒ należy przez to rozumieć system drzewostanów różnej szerokości poddanych specjalnym zabiegom gospodarczym i porządkowym lub powierzchni wylesionych i oczyszczonych do warstwy mineralnej; […]"}], "257": [{"ref": "PN-EN 12101-6:2007 – systemy różnicowania ciśnień", "kind": "norma"}], "259": [{"ref": "§ 271 ust. 1, 2, 3 i 7 WT – odległości między budynkami", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20"}], "260": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "261": [{"ref": "PKN-CEN/TS 54-14:2006 – rozmieszczenie czujek", "kind": "norma"}], "262": [{"ref": "§ 227 ust. 4 WT – wyłączenie budynków W i WW", "kind": "akt", "act": "wt", "label": "§ 227", "text": "4. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w ust. 1, z wyjątkiem stref pożarowych w wielokondygnacyjnych budynkach wysokich (W) i wysokościowych (WW), pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 100%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 100%. Przy jednoczesnym stosowaniu urządzeń wymienionych w pkt 1 i 2 dopuszcza się powiększenie powierzchni stref pożarowych o 200%."}], "263": [{"ref": "PN-EN 12845 – klasy zagrożenia przestrzeni ukrytych", "kind": "norma"}], "264": [{"ref": "PN-EN 12845 – instalacje suche, przyspieszacz", "kind": "norma"}], "265": [{"ref": "§ 273 WT / RPB – pas ochronny obiektów tymczasowych", "kind": "akt", "act": "wt", "label": "§ 273", "text": "§ 273. […] 4. Zbiorniki, o których mowa w ust. 3, powinny być wykonane jako stalowe dwupłaszczowe lub być lokalizowane na terenie ukształtowanym w formie niecki, o pojemności większej od pojemności zbiornika, z izolacją uniemożliwiającą przedostawanie się oleju do gruntu. 5. Odległość budynku ZL od zbiornika podziemnego oleju opałowego, przykrytego warstwą ziemi o grubości nie mniejszej niż 0,5 m, powinna wynosić co najmniej 3 m, a od urządzenia spustowego, oddechowego i pomiarowego tego zbiornika – co najmniej 10 m. 6. Odległości budynków PM i IN wykonanych z materiałów niepalnych od zbiorników i ich urządzeń, o których mowa w ust. 5, powinny wynosić co najmniej 3 m. Rozdział 8 Wymagania przeciwpożarowe dla garaży"}], "266": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "268": [{"ref": "§ 240 / załącznik WT – przyjmowanie liczby użytkowników", "kind": "akt", "act": "wt", "label": "§ 240", "text": "§ 240. […] 5. W bramach i ścianach przesuwanych na drogach ewakuacyjnych powinny znajdować się drzwi otwierane ręcznie albo w bezpośrednim sąsiedztwie tych bram i ścian powinny być umieszczone i wyraźnie oznakowane drzwi przeznaczone do celów ewakuacji. 6. Drzwi, bramy i inne zamknięcia otworów o wymaganej klasie odporności ogniowej lub dymoszczelności powinny być zaopatrzone w urządzenia, zapewniające samoczynne zamykanie otworu w razie pożaru. Należy też zapewnić możliwość ręcznego otwierania drzwi służących do ewakuacji. 7. Drzwi stanowiące wyjście ewakuacyjne z pomieszczenia, w którym może przebywać jednocześnie więcej niż 300 osób, oraz drzwi na drodze ewakuacyjnej z tego pomieszczenia, powinny być wyposażone w urządzenia przeciwpaniczne."}], "269": [{"ref": "PN-B-02877-4:2001 – grawitacyjne odprowadzanie dymu i ciepła", "kind": "norma"}], "270": [{"ref": "PN-HD 60364-5-56:2010 – instalacje bezpieczeństwa", "kind": "norma"}], "271": [{"ref": "PN-EN 1838:2005 – oświetlenie awaryjne stref wysokiego ryzyka", "kind": "norma"}], "272": [{"ref": "PN-EN 1838:2005 – odległość rozpoznawania znaków", "kind": "norma"}], "274": [{"ref": "§ 28, § 29 RPB; WT – kurtyny przeciwpożarowe scen", "kind": "norma"}], "276": [{"ref": "§ 20 RPB – instalacja wodociągowa przeciwpożarowa (instalacja sucha)", "kind": "akt", "act": "rpb", "label": "§ 20", "text": "§ 20. […] 2) w przejściach i na korytarzach, w tym w holach i na korytarzach poszczególnych kondygnacji budynków wysokich i wysokościowych; 3) przy wejściach na poddasza; 4) przy wyjściach na przestrzeń otwartą lub przy wyjściach ewakuacyjnych z pomieszczeń produkcyjnych i magazynowych, w szczególności zagrożonych wybuchem. 2. Hydranty wewnętrzne oraz zawory 52 muszą znajdować się na każdej kondygnacji, przy czym w budynkach wysokich i wysokościowych należy stosować po dwa zawory 52 na każdym pionie na kondygnacji podziemnej i na kondygnacji położonej na wysokości powyżej 25 m oraz po jednym zaworze 52 na każdym pionie na pozostałych kondygnacjach. 3. Zasięg hydrantów wewnętrznych w poziomie obejmuje całą powierzchnię chronionego budynku, strefy pożarowej lub pomieszczenia, z uwzględnieniem: 1) długości odcinka węża hydrantu wewnętrznego określonej w normach, o których mowa w § 18 ust. 2; […]"}], "279": [{"ref": "PN-EN 60079-10-1 / ocena zagrożenia wybuchem", "kind": "norma"}], "280": [{"ref": "§ 12–13 RW – parametry drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] Pomiędzy tą drogą i ścianą budynku nie mogą występować stałe elementy zagospodarowania terenu lub drzewa i krzewy o wysokości przekraczającej 3 m, uniemożliwiające dostęp do elewacji budynku za pomocą podnośników i drabin mechanicznych. 3. W przypadkach uzasadnionych warunkami lokalnymi, w szczególności architektonicznymi, droga pożarowa do budynków, o których mowa w ust. 1 pkt 1—4, może być poprowadzona w taki sposób, aby był zapewniony dostęp do: 1) 30 % obwodu zewnętrznego budynku, przy jego rozpiętości (największej szerokości) do 60 m, 2) 50 % obwodu zewnętrznego budynku, przy jego rozpiętości przekraczającej 60 m, 3) 100 % długości elewacji od frontu budynku, przy zabudowie pierzejowej — przy spełnieniu pozostałych wymagań określonych w ust. 2. 4. […]"}], "281": [{"ref": "§ 261 WT – liczba siedzeń w rzędzie", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. […] 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; 3) liczbę siedzeń w rzędzie nie większą niż 16 pomiędzy przejściami oraz 8 w rzędzie przyściennym, przy czym dopuszcza się zwiększenie liczby miejsc w rzędach odpowiednio do 40 i 20 pod warunkiem zwiększenia odstępu między rzędami siedzeń o 1 cm na każde dodatkowe siedzenie odpowiednio powyżej 16 lub 8; 4) szerokość przejść komunikacyjnych nie mniejszą niż 1,2 m przy liczbie osób do 150, a przy większej ich liczbie szerokość tę należy zwiększyć proporcjonalnie o 0,6 m na 100 osób; 5) rzędy siedzeń lub ławek trwale umocowane do podłogi albo siedzenia sztywno łączone ze sobą w rzędy oraz między rzędami."}], "282": [{"ref": "§ 68 WT – szerokość schodów ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 68", "text": "§ 68. […] 1. 3. Szerokość użytkowa schodów zewnętrznych do budynku powinna wynosić co najmniej 1,2 m, przy czym nie może być mniejsza niż szerokość użytkowa biegu schodowego w budynku, przyjęta zgodnie z wymaganiami określonymi w ust. 1 i 2. 4. Szerokość użytkową schodów stałych mierzy się między wewnętrznymi krawędziami poręczy, a w przypadku balustrady jednostronnej – między wykończoną powierzchnią ściany a wewnętrzną krawędzią poręczy tej balustrady. Szerokości te nie mogą być ograniczane przez zainstalowane urządzenia oraz elementy budynku."}], "283": [{"ref": "§ 253 WT – biegi i spoczniki schodów", "kind": "akt", "act": "wt", "label": "§ 253", "text": "§ 253. 1. W budynku ZL I, ZL II, ZL III lub ZL V, mającym kondygnację z posadzką na wysokości powyżej 25 m ponad poziomem terenu przy najniżej położonym wejściu do budynku oraz w budynku wysokościowym (WW) ZL IV przynajmniej jeden dźwig powinien być przystosowany do potrzeb ekip ratowniczych, spełniając wymagania Polskiej Normy dotyczącej dźwigów dla straży pożarnej. Dźwig dla ekip ratowniczych powinien zapewniać dostęp do każdej strefy pożarowej na kondygnacji bezpośrednio lub drogami komunikacji ogólnej. 2. Dojście do dźwigu dla ekip ratowniczych powinno prowadzić przez przedsionek przeciwpożarowy spełniający wymagania określone w § 232. 3. Ściany i stropy szybu dźwigu dla ekip ratowniczych powinny mieć klasę odporności ogniowej wymaganą jak dla stropów budynku, zgodnie z § 216. 4. Szyb dźwigu dla ekip ratowniczych powinien być wyposażony w urządzenia zapobiegające zadymieniu."}], "284": [{"ref": "§ 179 WT / rozp. dot. zbiorników gazu płynnego", "kind": "akt", "act": "wt", "label": "§ 179", "text": "§ 179. […] 8. Dla zbiornika z gazem płynnym o pojemności do 10 m3 zmniejszenie jego odległości od budynku, o której mowa w ust. 7, może mieć miejsce również wówczas, gdy pionowy pas ściany tego budynku o szerokości co najmniej równej rzutowi równoległemu zbiornika, powiększonej po 2 m z obu jego stron, oraz o wysokości równej wysokości budynku będzie miał klasę odporności ogniowej co najmniej R E I 120 i w tym pasie ściany nie będą znajdowały się otwory okienne i drzwiowe. 9. Odległość zbiornika z gazem płynnym od rzutu poziomego skrajnego przewodu elektroenergetycznej linii napowietrznej, a także od szyny zelektryfikowanej linii kolejowej lub tramwajowej powinna wynosić co najmniej: 1) 3 m – przy napięciu linii elektroenergetycznej lub sieci trakcyjnej do 1 kV; 2) 15 m – przy napięciu linii elektroenergetycznej lub sieci trakcyjnej równym lub większym od 1 kV. Rozdział 8 Instalacja elektryczna"}], "285": [{"ref": "§ 157 WT – instalacje gazowe w budynkach wysokich", "kind": "akt", "act": "wt", "label": "§ 157", "text": "§ 157. […] 3. Instalacja gazowa w budynku o wysokości większej niż 35 m ponad poziomem terenu może być doprowadzona tylko do pomieszczeń technicznych, w których są zainstalowane urządzenia gazowe, usytuowanych w piwnicy lub na najniższej kondygnacji nadziemnej, a także na najwyższej kondygnacji budynku lub nad tą kondygnacją, pod warunkiem zastosowania urządzeń stabilizujących ciśnienie gazu. 4. Zastosowanie instalacji gazowej w budynkach o wysokości ponad 25 m wymaga uzyskania pozytywnej opinii wydanej przez właściwego komendanta wojewódzkiego Państwowej Straży Pożarnej. 5. Instalacje gazowe zasilane gazem płynnym mogą być wykonywane tylko w budynkach niskich. 6. Zabrania się stosowania w jednym budynku gazu płynnego i gazu z sieci gazowej. 7. W budynku niskim, mającym w mieszkaniach instalację zasilaną gazem płynnym, dopuszcza się usytuowanie kotłowni gazowej zasilanej z sieci gazowej. 8. […]"}], "286": [{"ref": "§ 239 WT – drzwi na drogach ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 239", "text": "§ 239. […] 2. Drzwi stanowiące wyjście ewakuacyjne powinny otwierać się na zewnątrz pomieszczeń: 1) zagrożonych wybuchem; 2) do których jest możliwe niespodziewane przedostanie się mieszanin wybuchowych lub substancji trujących, duszących bądź innych, mogących utrudnić ewakuację; 3) przeznaczonych do jednoczesnego przebywania ponad 50 osób; 4) przeznaczonych dla ponad 6 osób o ograniczonej zdolności poruszania się. 3. Wyjścia ewakuacyjne z pomieszczenia zagrożonego wybuchem na drogę ewakuacyjną powinny prowadzić przez przedsionki przeciwpożarowe odpowiadające wymaganiom § 232. 4. Szerokość drzwi stanowiących wyjście ewakuacyjne z budynku, z zastrzeżeniem ust. 1, a także szerokość drzwi na drodze ewakuacyjnej z klatki schodowej, prowadzących na zewnątrz budynku lub do innej strefy pożarowej, powinna być nie mniejsza niż szerokość biegu klatki schodowej, określona zgodnie z § 68 ust. 1 i 2. 5. […]"}], "287": [{"ref": "§ 228 ust. 1 i 2 WT", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}, {"ref": "§ 229 ust. 1 pkt 1 WT", "kind": "akt", "act": "wt", "label": "§ 229", "text": "§ 229. 1. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w § 228, pod warunkiem ich ochrony: 1) stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 100%; 2) samoczynnymi urządzeniami oddymiającymi – o 50%."}], "288": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "289": [{"ref": "§ 271 WT – odległości między budynkami", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20 2. […]"}], "290": [{"ref": "§ 228 ust. 1 WT – tabela powierzchni stref PM", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}], "291": [{"ref": "§ 216 ust. 8 WT – palna izolacja cieplna w ścianach", "kind": "akt", "act": "wt", "label": "§ 216", "text": "8. W budynku, na wysokości powyżej 25 m od poziomu terenu, okładzina elewacyjna i jej zamocowanie mechaniczne, a także izolacja cieplna ściany zewnętrznej, powinny być wykonane z materiałów niepalnych."}], "292": [{"ref": "§ 234 WT – przepusty instalacyjne", "kind": "akt", "act": "wt", "label": "§ 234", "text": "§ 234. 1. Przepusty instalacyjne w elementach oddzielenia przeciwpożarowego powinny mieć klasę odporności ogniowej (E I) wymaganą dla tych elementów. 2. Dopuszcza się nieinstalowanie przepustów, o których mowa w ust. 1, dla pojedynczych rur instalacji wodnych, kanalizacyjnych i ogrzewczych, wprowadzanych przez ściany i stropy do pomieszczeń higienicznosanitarnych. 3. Przepusty instalacyjne o średnicy większej niż 0,04 m w ścianach i stropach pomieszczenia zamkniętego, dla których wymagana klasa odporności ogniowej jest nie niższa niż E I 60 lub R E I 60, a niebędących elementami oddzielenia przeciwpożarowego, powinny mieć klasę odporności ogniowej (E I) ścian i stropów tego pomieszczenia. 4. Przejścia instalacji przez zewnętrzne ściany budynku, znajdujące się poniżej poziomu terenu, powinny być zabezpieczone przed możliwością przenikania gazu do wnętrza budynku."}], "293": [{"ref": "§ 256 WT – długość dojść ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "§ 256. […] 3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej. 4. […]"}], "294": [{"ref": "§ 245, § 256 WT – obudowa i zabezpieczenie klatek schodowych", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}], "295": [{"ref": "§ 256 ust. 3 i 4 WT – długości dojść ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej."}], "296": [{"ref": "§ 278 ust. 1 WT – wyjścia ewakuacyjne ze strefy garażu", "kind": "akt", "act": "wt", "label": "§ 278", "text": "§ 278. 1. Ze strefy pożarowej garażu, która posiada więcej niż 25 stanowisk postojowych i nie jest wyposażona w instalację wentylacji oddymiającej lub ma powierzchnię przekraczającą 1500 m2, należy zapewnić co najmniej dwa wyjścia ewakuacyjne, przy czym jednym z tych wyjść może być wjazd lub wyjazd."}], "297": [{"ref": "rozp. dot. drogowych obiektów inżynierskich; § 10 RW", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. 1. Na sieci wodociągowej przeciwpożarowej stosuje się hydranty zewnętrzne nadziemne o średnicy nominalnej DN 80. 2. Dopuszcza się instalowanie hydrantów podziemnych o średnicy nominalnej DN 80 w przypadkach, gdy zainstalowanie hydrantów nadziemnych jest szczególnie utrudnione lub niewskazane, na przykład ze względu na utrudnienia w ruchu. 3. W obiekcie budowlanym produkcyjnym i magazynowym, w którym wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru przekracza 30 dm3/s, w zakładach rafineryjnych i petrochemicznych oraz na magistralnym przewodzie wodociągowym przeciwpożarowym należy instalować hydranty nadziemne o średnicy nominalnej DN 100. 4. Hydranty zewnętrzne zainstalowane na sieci wodociągowej przeciwpożarowej powinny być wyposażone w odcięcia umożliwiające odłączania ich od sieci. […]"}], "298": [{"ref": "rozp. MG z 21.11.2005 / § 179 WT – odległości zbiorników gazu", "kind": "akt", "act": "wt", "label": "§ 179", "text": "§ 179. […] Dopuszczalna odległość zbiorników z gazem płynnym od budynków produkcyjnych i magazynowych powinna wynosić dla zbiorników o pojemności: 1) do 10 m3 – nie mniej niż odległość określona w tabeli w ust. 4 w kolumnach 2 i 3; 2) powyżej 10 m3 – nie mniej niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3. 6. Odległość zbiorników z gazem płynnym od granicy działki budowlanej z tymi zbiornikami powinna być nie mniejsza niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3, przy zachowaniu wymaganej odległości od budynku danego rodzaju. 7. Odległości określone w tabeli w ust. 4 w kolumnie 2 mogą być zmniejszone do 50% w przypadku zastosowania wolno stojącej ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej R E I 120, usytuowanej pomiędzy zbiornikiem z gazem płynnym a budynkiem. […]"}], "302": [{"ref": "§ 10 RW – sieć wodociągowa przeciwpożarowa", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 6) na stanowisku czerpania wody należy umieścić zakaz parkowania. 10. Określenia potrzeb w zakresie instalowania hydrantów, o których mowa w ust. 9, dokonują właściwe miejscowo organy Państwowej Straży Pożarnej w ramach opiniowania projektów studium uwarunkowań i kierunków zagospodarowania przestrzennego gminy oraz projektów miejscowych planów zagospodarowania przestrzennego, w trybie określonym w przepisach o planowaniu i zagospodarowaniu przestrzennym. 11. Maksymalne ciśnienie hydrostatyczne w sieci wodociągowej przeciwpożarowej nie może przekraczać 1,6 MPa. 12. Miejsce usytuowania hydrantu zewnętrznego należy oznakować znakami zgodnymi z Polskimi Normami. 13. Hydranty zewnętrzne powinny być co najmniej raz w roku poddawane przeglądom i konserwacji przez właściciela sieci wodociągowej przeciwpożarowej. Rozdział 5 Pompownie przeciwpożarowe"}], "303": [{"ref": "§ 10 RW – hydranty zewnętrzne", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 2. Dopuszcza się instalowanie hydrantów podziemnych o średnicy nominalnej DN 80 w przypadkach, gdy zainstalowanie hydrantów nadziemnych jest szczególnie utrudnione lub niewskazane, na przykład ze względu na utrudnienia w ruchu. 3. W obiekcie budowlanym produkcyjnym i magazynowym, w którym wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru przekracza 30 dm3/s, w zakładach rafineryjnych i petrochemicznych oraz na magistralnym przewodzie wodociągowym przeciwpożarowym należy instalować hydranty nadziemne o średnicy nominalnej DN 100. 4. Hydranty zewnętrzne zainstalowane na sieci wodociągowej przeciwpożarowej powinny być wyposażone w odcięcia umożliwiające odłączania ich od sieci. Odcięcia te muszą pozostawać w położeniu otwartym podczas normalnej eksploatacji sieci. 5. […]"}], "304": [{"ref": "§ 15–19 RPB – zaopatrzenie w wodę do gaszenia wewnętrznego", "kind": "akt", "act": "rpb", "label": "§ 15", "text": "§ 15. 1. Z każdego miejsca w obiekcie, przeznaczonego do przebywania ludzi, zapewnia się odpowiednie warunki ewakuacji, umożliwiające szybkie i bezpieczne opuszczanie strefy zagrożonej lub objętej pożarem, dostosowane do liczby i stanu sprawności osób przebywających w obiekcie oraz jego funkcji, konstrukcji i wymiarów, a także zastosowanie technicznych środków zabezpieczenia przeciwpożarowego, polegających na: 1) zapewnieniu dostatecznej liczby, wysokości i szerokości wyjść ewakuacyjnych; 2) zachowaniu dopuszczalnej długości, wysokości i szerokości przejść oraz dojść ewakuacyjnych; 3) zapewnieniu bezpiecznej pożarowo obudowy i wydzieleń dróg ewakuacyjnych oraz pomieszczeń; […]"}], "305": [{"ref": "§ 6 RW – ilość wody dla obiektów innych niż budynki", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. […] Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla stacji paliw i stacji gazu płynnego oraz stacji gazu ziemnego wynosi 10 dm3/s. 5. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla zbiorników z gazami palnymi oraz z cieczami o temperaturze zapłonu do 373,15 K (100 °C) niebędącymi produktami naftowymi oraz dla zbiorników z produktami naftowymi o temperaturze zapłonu od 328,15 K (55 °C) do 373,15 K (100 °C), z wyjątkiem podgrzanych powyżej temperatury zapłonu, służącą do zewnętrznego gaszenia pożaru, określa tabela nr 3 załącznika do rozporządzenia. 6. […]"}], "306": [{"ref": "§ 12 RW – parametry drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 7) stanowiska czerpania wody do celów przeciwpożarowych. 2. Droga pożarowa powinna przebiegać wzdłuż dłuższego boku budynku, o którym mowa w ust. 1 pkt 1—4, na całej jego długości, a w przypadku gdy krótszy bok budynku ma więcej niż 60 m — z jego dwóch stron, przy czym bliższa krawędź drogi pożarowej musi być oddalona od ściany budynku o 5—15 m dla obiektów zaliczanych do kategorii zagrożenia ludzi i o 5—25 m dla pozostałych obiektów. Pomiędzy tą drogą i ścianą budynku nie mogą występować stałe elementy zagospodarowania terenu lub drzewa i krzewy o wysokości przekraczającej 3 m, uniemożliwiające dostęp do elewacji budynku za pomocą podnośników i drabin mechanicznych. 3. […]"}], "307": [{"ref": "§ 19–20 RPB – zapas wody instalacji wodociągowej ppoż.", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. 1. Hydranty 25 muszą być stosowane w strefach pożarowych zakwalifikowanych do kategorii zagrożenia ludzi ZL: 1) na każdej kondygnacji budynku wysokiego i wysokościowego, z wyjątkiem kondygnacji obejmującej wyłącznie strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL IV; […]"}], "308": [{"ref": "PN-HD 60364-5-56:2019-01 – instalacje bezpieczeństwa", "kind": "norma"}], "309": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "310": [{"ref": "PKN-CEN/TS 54-14:2020-09 – dobór czujek ciepła", "kind": "norma"}], "311": [{"ref": "PN-EN 54-23 – sygnalizatory optyczne", "kind": "norma"}], "312": [{"ref": "PN-EN 12845+A1:2020-05 – instalacje suche", "kind": "norma"}], "313": [{"ref": "PN-EN 12845 – dobór parametrów urządzenia tryskaczowego", "kind": "norma"}], "314": [{"ref": "PN-EN 12845+A1:2020-05 – rozmieszczenie tryskaczy", "kind": "norma"}], "315": [{"ref": "PN-EN 15004 – gazy gaśnicze", "kind": "norma"}], "316": [{"ref": "PN-EN 12101-6:2007 – systemy różnicowania ciśnień", "kind": "norma"}], "317": [{"ref": "PN-EN 12101-6:2007 – systemy różnicowania ciśnień", "kind": "norma"}], "318": [{"ref": "PN-EN 81-73:2020-12 – funkcjonowanie dźwigów w przypadku pożaru", "kind": "norma"}], "319": [{"ref": "PN-EN 1838:2013 – czas osiągania natężenia oświetlenia awaryjnego", "kind": "norma"}], "320": [{"ref": "PN-B-02877-4:2001 – grawitacyjne odprowadzanie dymu i ciepła", "kind": "norma"}], "321": [{"ref": "§ 266, § 271 WT – sytuowanie wylotów i otworów", "kind": "akt", "act": "wt", "label": "§ 266", "text": "§ 266. 1. Przewody spalinowe i dymowe powinny być wykonane z wyrobów niepalnych. 2. Przewody lub obudowa przewodów spalinowych i dymowych powinny spełniać wymagania określone w Polskiej Normie dotyczącej badań ogniowych małych kominów. 3. Dopuszcza się wykonanie obudowy, o której mowa w ust. 2, z cegły pełnej grubości 12 cm, murowanej na zaprawie cementowo-wapiennej, z zewnętrznym tynkiem lub spoinowaniem. 4. Między wylotem przewodu spalinowego i dymowego a najbliższym skrajem korony drzew dorosłych należy zapewnić zachowanie odległości co najmniej 6 m, z zastrzeżeniem § 271 ust. 8."}], "322": [{"ref": "§ 256 WT – podział korytarzy ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "§ 256. 1. Długość drogi ewakuacyjnej od wyjścia z pomieszczenia na tę drogę do wyjścia do innej strefy pożarowej lub na zewnątrz budynku, zwanej dalej „dojściem ewakuacyjnym”, mierzy się wzdłuż osi drogi ewakuacyjnej. W przypadku zakończenia dojścia ewakuacyjnego przedsionkiem przeciwpożarowym, długość tę mierzy się do pierwszych drzwi tego przedsionka. 2. Za równorzędne wyjściu do innej strefy pożarowej, o którym mowa w ust. 1, uważa się wyjście do obudowanej klatki schodowej, zamykanej drzwiami o klasie odporności ogniowej co najmniej E I 30, wyposażonej w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, a w przypadku, o którym mowa w § 246 ust. 5 – zamykanej drzwiami dymoszczelnymi. 3. […]"}], "323": [{"ref": "§ 212 ust. 4, § 230 WT", "kind": "akt", "act": "wt", "label": "§ 212", "text": "4. Wymaganą klasę odporności pożarowej dla budynku PM oraz IN, z zastrzeżeniem § 282, określa poniższa tabela: Maksymalna gęstość obciążenia ogniowego strefy pożarowej w budynku Q [MJ/m2] Budynek o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) Budynek wielokondygnacyjny niski średniowysoki wysoki wysokościowy (N) (SW) (W) (WW) 1 2 3 4 5 6 Q ≤ 500 „E” „D” „C” „B” „B” 500 < Q ≤ 1000 „D” „D” „C” „B” „B” 1000 < Q ≤ 2000 „C” „C” „C” „B” „B” 2000 < Q ≤ 4000 „B” „B” „B” * * Q > 4000 „A” „A” „A” * * * – Zgodnie z § 228 ust. 1 nie mogą występować takie budynki."}], "324": [{"ref": "§ 228 ust. 1 WT", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}, {"ref": "§ 229 ust. 1 pkt 1 WT", "kind": "akt", "act": "wt", "label": "§ 229", "text": "§ 229. 1. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w § 228, pod warunkiem ich ochrony: 1) stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 100%; 2) samoczynnymi urządzeniami oddymiającymi – o 50%."}], "325": [{"ref": "PN-EN 13501-1; § 208 WT", "kind": "norma"}], "326": [{"ref": "§ 216 WT – wymagania w zakresie rozprzestrzeniania ognia", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. […] 4. 4) Dla ścian komór zsypu wymaga się klasy E I 60, a dla drzwi komór zsypu klasy E I 30. 5) Klasa odporności ogniowej dotyczy elementów wraz z uszczelnieniami złączy i dylatacjami. 2. Elementy budynku, o których mowa w ust. 1, powinny być nierozprzestrzeniające ognia, przy czym dopuszcza się zastosowanie słabo rozprzestrzeniających ogień: 1) elementów budynku o jednej kondygnacji nadziemnej ZL IV oraz PM, o maksymalnej gęstości obciążenia ogniowego strefy pożarowej do 500 MJ/m2; 2) ścian wewnętrznych i zewnętrznych oraz elementów konstrukcji dachu i jego przekrycia w budynku PM niskim o maksymalnej gęstości obciążenia ogniowego strefy pożarowej do 1000 MJ/m2; 3) ścian zewnętrznych w budynku niskim ZL IV. 3. […]"}], "327": [{"ref": "§ 8–9 RW – uzupełniający zapas wody", "kind": "akt", "act": "rw", "label": "§ 8", "text": "§ 8. 1. W przypadku braku źródła wody zapewniającego wymaganą ilość wody do celów przeciwpożarowych, właściwy miejscowo komendant powiatowy (miejski) Państwowej Straży Pożarnej na wniosek właściciela budynku, obiektu budowlanego lub terenu, może dopuścić na czas określony zastępcze źródło wody do celów przeciwpożarowych, w szczególności naturalny lub sztuczny zbiornik wody, studnię lub ciek wodny, wyposażone w stanowisko czerpania wody wraz z dojazdem. 2. Zastępcze źródło wody, o którym mowa w ust. 1, powinno zapewniać możliwość prowadzenia działań gaśniczych z użyciem sił i środków dostępnych w rejonie działania najbliższej jednostki ochrony przeciwpożarowej. 3. […]"}], "328": [{"ref": "§ 232 WT – klasy ścian oddzielenia przeciwpożarowego", "kind": "akt", "act": "wt", "label": "§ 232", "text": "§ 232. […] 6. W ścianie oddzielenia przeciwpożarowego dopuszcza się wypełnienie otworów materiałem przepuszczającym światło, takim jak luksfery, cegła szklana lub inne przeszklenie, jeżeli powierzchnia wypełnionych otworów nie przekracza 10% powierzchni ściany, przy czym klasa odporności ogniowej wypełnień nie powinna być niższa niż: Wymagana klasa odporności ogniowej ściany oddzielenia przeciwpożarowego Klasa odporności ogniowej wypełnienia otworu w ścianie będącej obudową drogi ewakuacyjnej innej 1 2 3 R E I 240 E I 120 E 120 R E I 120 E I 60 E 60 R E I 60 E I 30 E 30 7. Dopuszcza się stosowanie w strefach pożarowych PM otworu w ścianie oddzielenia przeciwpożarowego, służącego przeprowadzeniu urządzeń technologicznych, chronionego w sposób równoważny wymaganym dla tej ściany drzwiom przeciwpożarowym pod względem możliwości przeniesienia się przez ten otwór ognia lub dymu, w przypadku pożaru."}], "329": [{"ref": "§ 179 WT – usytuowanie zbiorników gazu płynnego", "kind": "akt", "act": "wt", "label": "§ 179", "text": "§ 179. […] 2) powyżej 10 m3 – nie mniej niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3. 6. Odległość zbiorników z gazem płynnym od granicy działki budowlanej z tymi zbiornikami powinna być nie mniejsza niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3, przy zachowaniu wymaganej odległości od budynku danego rodzaju. 7. Odległości określone w tabeli w ust. 4 w kolumnie 2 mogą być zmniejszone do 50% w przypadku zastosowania wolno stojącej ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej R E I 120, usytuowanej pomiędzy zbiornikiem z gazem płynnym a budynkiem. Wymiary wolno stojącej ściany oraz jej odległość od zbiornika powinny być tak dobrane, aby osłonić zbiornik od tej części budynku, która znajduje się w odległości mniejszej niż określona w tabeli w ust. 4 w kolumnie 2 od dowolnego punktu zbiornika. 8. […]"}], "330": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "331": [{"ref": "§ 216 WT – wymagane klasy odporności ogniowej elementów", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}], "332": [{"ref": "§ 37 RPB / WT – wymagania dla pomieszczeń zagrożonych wybuchem", "kind": "akt", "act": "wt", "label": "§ 37", "text": "§ 37. Przepływowe, szczelne osadniki podziemne, stanowiące część przydomowej oczyszczalni ścieków gospodarczo-bytowych, służące do wstępnego ich oczyszczania, mogą być sytuowane w bezpośrednim sąsiedztwie budynków jednorodzinnych, pod warunkiem wyprowadzenia ich odpowietrzenia przez instalację kanalizacyjną co najmniej 0,6 m powyżej górnej krawędzi okien i drzwi zewnętrznych w tych budynkach."}], "334": [{"ref": "§ 16 RPB – warunki uznania budynku za zagrażający życiu ludzi", "kind": "akt", "act": "rpb", "label": "§ 16", "text": "§ 16. […] 2. Podstawą do stwierdzenia, że w budynku występują warunki techniczne, o których mowa w ust. 1, z zastrzeżeniem § 45, może być: 1) szerokość przejścia, dojścia lub wyjścia ewakuacyjnego albo biegu bądź spocznika klatki schodowej służącej ewakuacji, mniejsza o ponad jedną trzecią od określonej w przepisach techniczno-budowlanych; 2) długość przejścia lub dojścia ewakuacyjnego większa o ponad 100% od określonej w przepisach techniczno-budowlanych; 3) występowanie w pomieszczeniu strefy pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II lub ZL V albo na drodze ewakuacyjnej: a) okładziny sufitu lub sufitu podwieszonego z materiału łatwo zapalnego lub kapiącego pod wpływem ognia, bądź wykładziny podłogowej z materiału łatwo zapalnego, b) okładziny ściennej z materiału łatwo zapalnego na drodze ewakuacyjnej, jeżeli nie zapewniono dwóch kierunków ewakuacji; […]"}], "336": [{"ref": "PN-EN 12845 – klasyfikacja tryskaczy wg RTI", "kind": "norma"}], "338": [{"ref": "§ 6 RW – ilość wody do zewnętrznego gaszenia pożaru", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. […] 10. W przypadku gdy wydajność wodociągu stanowiącego źródło wody do celów przeciwpożarowych nie zapewnia ilości określonej w ust. 3—5 i 7—9, należy zapewnić uzupełniający zapas wody w zbiornikach przeciwpożarowych, technologicznych lub naturalnych, przystosowanych do poboru wody przez pompy pożarnicze: 1) dla obiektów budowlanych produkcyjnych i magazynowych wymienionych w ust. 3, w ilości równej iloczynowi brakującej wydajności wodociągu przez czas trwania pożaru przewidziany dla rozpatrywanej strefy pożarowej, ustalony w Polskiej Normie dotyczącej obliczania gęstości obciążenia ogniowego oraz wyznaczania względnego czasu trwania pożaru, jednak nie większy niż 4 godziny; 2) dla obiektów budowlanych wymienionych w ust. 4, 5 i 7—9, w ilości odpowiadającej 10 m3 zapasu wody na 1 dm3/s brakującej wydajności wodociągu. 11. […]"}], "339": [{"ref": "§ 12 RW – wymóg drogi pożarowej dla placów składowych", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; 4) budynku zawierającego strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego poniżej 500 MJ/m2 o powierzchni przekraczającej 20 000 m2; […]"}], "340": [{"ref": "PN-EN 12101-6:2007 – systemy różnicowania ciśnień", "kind": "norma"}], "341": [{"ref": "§ 10 RW – hydranty zewnętrzne na sieci", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 2. Dopuszcza się instalowanie hydrantów podziemnych o średnicy nominalnej DN 80 w przypadkach, gdy zainstalowanie hydrantów nadziemnych jest szczególnie utrudnione lub niewskazane, na przykład ze względu na utrudnienia w ruchu. 3. W obiekcie budowlanym produkcyjnym i magazynowym, w którym wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru przekracza 30 dm3/s, w zakładach rafineryjnych i petrochemicznych oraz na magistralnym przewodzie wodociągowym przeciwpożarowym należy instalować hydranty nadziemne o średnicy nominalnej DN 100. 4. Hydranty zewnętrzne zainstalowane na sieci wodociągowej przeciwpożarowej powinny być wyposażone w odcięcia umożliwiające odłączania ich od sieci. Odcięcia te muszą pozostawać w położeniu otwartym podczas normalnej eksploatacji sieci. 5. […]"}], "342": [{"ref": "§ 19 RPB – hydranty wewnętrzne (dotyczą budynków)", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. 1. Hydranty 25 muszą być stosowane w strefach pożarowych zakwalifikowanych do kategorii zagrożenia ludzi ZL: 1) na każdej kondygnacji budynku wysokiego i wysokościowego, z wyjątkiem kondygnacji obejmującej wyłącznie strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL IV; […]"}], "343": [{"ref": "§ 8 RPB – składowanie gazu płynnego w punktach sprzedaży", "kind": "akt", "act": "rpb", "label": "§ 8", "text": "§ 8. 1. Podczas przechowywania cieczy o temperaturze zapłonu poniżej 328,15 K (55ºC) w budynkach, w strefach pożarowych zaliczonych do kategorii zagrożenia ludzi: 1) jest dopuszczalne przechowywanie w jednej strefie pożarowej, zakwalifikowanej do kategorii zagrożenia ludzi innej niż ZL IV oraz o przeznaczeniu innym niż handlowo-usługowe do 10 dm3 cieczy o temperaturze zapłonu poniżej 294,15 K (21ºC) oraz do 50 dm3 cieczy o temperaturze zapłonu 294,15÷328,15 K (21÷55ºC), a w mieszkaniach odpowiednio do 5 i do 20 dm3 cieczy; 2) jest dopuszczalne przechowywanie w pomieszczeniach handlowo-usługowych cieczy o temperaturze zapłonu do 328,15 K (55ºC) w takiej ilości, że gęstość obciążenia ogniowego stworzona przez te ciecze nie przekroczy 500 MJ/m2; […]"}], "344": [{"ref": "PN-EN 12845+A1:2020 – powierzchnia na stanowisko kontrolno-alarmowe", "kind": "norma"}], "345": [{"ref": "rozp. z 30.05.2000 – drogowe obiekty inżynierskie; PN-EN 12101-3", "kind": "norma"}], "346": [{"ref": "PN-B-02877-4:2001 – kurtyny dymowe", "kind": "norma"}], "347": [{"ref": "§ 19 RPB / PN-EN 671-2 – hydranty wewnętrzne 52", "kind": "norma"}], "348": [{"ref": "PN-B-02877-4:2001/Az1:2006 – usytuowanie klap dymowych", "kind": "norma"}], "349": [{"ref": "PN-B-02857:2017 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "350": [{"ref": "PN-EN 1993-1-2 – projektowanie konstrukcji stalowych na warunki pożarowe", "kind": "norma"}], "351": [{"ref": "PKN-CEN/TS 54-14:2020 – rozmieszczenie czujek w korytarzach", "kind": "norma"}], "352": [{"ref": "PN-B-02857:2017 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "353": [{"ref": "PN-B-02431-1:1999 – kotłownie gazowe", "kind": "norma"}], "354": [{"ref": "PN-EN 12845+A1:2020 – intensywność zraszania", "kind": "norma"}], "356": [{"ref": "dyrektywa ATEX – kategorie urządzeń i strefy pyłowe", "kind": "ue"}], "357": [{"ref": "§ 37 RPB – pomieszczenia zagrożone wybuchem", "kind": "akt", "act": "rpb", "label": "§ 37", "text": "§ 37. […] U. poz. 1004 oraz z 2006 r. poz. 836)6). 6. Klasyfikację stref zagrożenia wybuchem określa Polska Norma dotycząca zapobiegania wybuchowi i ochronie przed wybuchem. 7. Pomieszczenie, w którym może wytworzyć się mieszanina wybuchowa, powstała z wydzielającej się takiej ilości palnych gazów, par, mgieł lub pyłów, której wybuch mógłby spowodować przyrost ciśnienia w tym pomieszczeniu przekraczający 5 kPa, określa się jako pomieszczenie zagrożone wybuchem. 8. Wytyczne w zakresie określania przyrostu ciśnienia w pomieszczeniu, jaki mógłby zostać spowodowany przez wybuch, określa załącznik do rozporządzenia. 9. W pomieszczeniu należy wyznaczyć strefę zagrożenia wybuchem, jeżeli może w nim występować mieszanina wybuchowa o objętości co najmniej 0,01 m3 w zwartej przestrzeni. […]"}], "359": [{"ref": "PN-EN 671-1:2012 – hydranty wewnętrzne z wężem półsztywnym", "kind": "norma"}], "361": [{"ref": "§ 261 WT – podłogi podniesione", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. Pomieszczenia przeznaczone do jednoczesnego przebywania ponad 200 osób dorosłych lub 100 dzieci, w których miejsca do siedzenia są ustawione w rzędach, powinny mieć: 1) fotele i inne siedzenia trudno zapalne oraz niewydzielające produktów rozkładu i spalania, określonych jako bardzo toksyczne, zgodnie z Polską Normą dotyczącą badań wydzielania produktów toksycznych; określenie trudno zapalny przypisuje się fotelom i innym siedzeniom, które nie ulegają postępującemu tleniu i spalaniu płomieniowemu w warunkach określonych Polską Normą dotyczącą badania zapalności mebli tapicerowanych; 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; […]"}], "362": [{"ref": "PN-EN 54-5 – czujki ciepła, klasy", "kind": "norma"}], "364": [{"ref": "§ 266, § 271 WT", "kind": "akt", "act": "wt", "label": "§ 266", "text": "§ 266. 1. Przewody spalinowe i dymowe powinny być wykonane z wyrobów niepalnych. 2. Przewody lub obudowa przewodów spalinowych i dymowych powinny spełniać wymagania określone w Polskiej Normie dotyczącej badań ogniowych małych kominów. 3. Dopuszcza się wykonanie obudowy, o której mowa w ust. 2, z cegły pełnej grubości 12 cm, murowanej na zaprawie cementowo-wapiennej, z zewnętrznym tynkiem lub spoinowaniem. 4. Między wylotem przewodu spalinowego i dymowego a najbliższym skrajem korony drzew dorosłych należy zapewnić zachowanie odległości co najmniej 6 m, z zastrzeżeniem § 271 ust. 8."}], "365": [{"ref": "§ 179 WT – zbiorniki gazu płynnego", "kind": "akt", "act": "wt", "label": "§ 179", "text": "§ 179. […] 4. Dopuszczalną odległość zbiorników z gazem płynnym od budynków mieszkalnych, budynków zamieszkania zbiorowego oraz budynków użyteczności publicznej, a także między zbiornikami, określa poniższa tabela: Nominalna pojemność zbiornika w m3 Odległość budynków mieszkalnych, budynków zamieszkania zbiorowego i budynków użyteczności publicznej od: Odległość od sąsiedniego zbiornika naziemnego lub podziemnego w m zbiornika naziemnego w m zbiornika podziemnego w m 1 2 3 4 do 3 3 1 1 powyżej 3 do 5 5 2,5 1 powyżej 5 do 7 7,5 3 1,5 powyżej 7 do 10 10 5 1,5 powyżej 10 do 40 20 10 ¼ sumy średnic dwóch sąsiednich zbiorników powyżej 40 do 65 30 15 powyżej 65 do 100 40 20 5. Dopuszczalna odległość zbiorników z gazem płynnym od budynków produkcyjnych i magazynowych powinna wynosić dla zbiorników o pojemności: 1) do 10 m3 – nie mniej niż odległość określona w tabeli w ust. 4 w kolumnach 2 i 3; […]"}], "367": [{"ref": "PN-B-02857:2017 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "368": [{"ref": "§ 2 RPB – definicja materiałów niebezpiecznych pożarowo", "kind": "akt", "act": "rpb", "label": "§ 2", "text": "§ 2. 1. Ilekroć w rozporządzeniu jest mowa o: 1) materiałach niebezpiecznych pożarowo ‒ należy przez to rozumieć: a) gazy palne, b) ciecze palne o temperaturze zapłonu poniżej 328,15 K (55ºC), c) materiały wytwarzające w zetknięciu z wodą gazy palne, d) materiały zapalające się samorzutnie na powietrzu, e) materiały wybuchowe i wyroby pirotechniczne, f) materiały ulegające samorzutnemu rozkładowi lub polimeryzacji, g) materiały mające skłonności do samozapalenia, h) materiały inne niż wymienione w lit. a‒g, jeśli sposób ich składowania, przetwarzania lub innego wykorzystania może spowodować powstanie pożaru; 2) pasie przeciwpożarowym ‒ należy przez to rozumieć system drzewostanów różnej szerokości poddanych specjalnym zabiegom gospodarczym i porządkowym lub powierzchni wylesionych i oczyszczonych do warstwy mineralnej; […]"}], "369": [{"ref": "PN-EN 12101-6 – systemy różnicowania ciśnień", "kind": "norma"}], "370": [{"ref": "§ 228 WT – powiększanie powierzchni stref PM", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. […] 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków. 2. Strefy pożarowe, o których mowa w ust. 1, w podziemnej części budynków nie powinny przekraczać 50% powierzchni określonych w tabeli."}], "371": [{"ref": "§ 6, § 8 RW – zapas wody do zewnętrznego gaszenia pożaru", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. 1. Wodę dla obiektów budowlanych produkcyjnych i magazynowych, w ilości wymaganej do celów przeciwpożarowych do zewnętrznego gaszenia pożaru, należy zapewnić z urządzeń dostarczających ją do celów bytowo-gospodarczych i technologicznych lub z innych zasobów wody służących do tego celu. 2. W przypadku gdy w obiektach budowlanych produkcyjnych i magazynowych urządzenia i zasoby wody, o których mowa w ust. 1, nie zapewniają wymaganej ilości do celów przeciwpożarowych do zewnętrznego gaszenia pożaru, wykorzystuje się urządzenia służące do dostarczania wody do jednostek osadniczych lub uzupełniające źródła wody, o których mowa w § 4 ust. 5. 3. […]"}], "372": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "373": [{"ref": "§ 256 ust. 3 i 4 WT – długości dojść ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej."}], "374": [{"ref": "PN-EN 81-72:2020 – dźwigi dla straży pożarnej", "kind": "norma"}], "375": [{"ref": "§ 212 WT – klasa odporności pożarowej", "kind": "akt", "act": "wt", "label": "§ 212", "text": "§ 212. 1. Ustanawia się pięć klas odporności pożarowej budynków lub ich części, podanych w kolejności od najwyższej do najniższej i oznaczonych literami: „A”, „B”, „C”, „D” i „E”, a scharakteryzowanych w § 216. 2. Wymaganą klasę odporności pożarowej dla budynku, zaliczonego do jednej kategorii ZL, określa poniższa tabela: Budynek ZL I ZL II ZL III ZL IV ZL V 1 2 3 4 5 6 niski (N) „B” „B” „C” „D” „C” średniowysoki (SW) „B” „B” „B” „C” „B” wysoki (W) „B” „B” „B” „B” „B” wysokościowy (WW) „A” „A” „A” „B” „A” 3. Dopuszcza się obniżenie wymaganej klasy odporności pożarowej w budynkach wymienionych w poniższej tabeli do poziomu w niej określonego. Liczba kondygnacji nadziemnych ZL I ZL II ZL III 1 2 3 4 1 „D” „D” „D” 2*) „C” „C” „D” *) Gdy poziom stropu nad pierwszą kondygnacją nadziemną jest na wysokości nie większej niż 9 m nad poziomem terenu. 4. […]"}], "376": [{"ref": "§ 278 ust. 1 i 2 WT – wyjścia i przejścia w garażach", "kind": "akt", "act": "wt", "label": "§ 278", "text": "§ 278. 1. Ze strefy pożarowej garażu, która posiada więcej niż 25 stanowisk postojowych i nie jest wyposażona w instalację wentylacji oddymiającej lub ma powierzchnię przekraczającą 1500 m2, należy zapewnić co najmniej dwa wyjścia ewakuacyjne, przy czym jednym z tych wyjść może być wjazd lub wyjazd."}], "377": [{"ref": "§ 157 WT – instalacje gazowe w budynkach wysokich", "kind": "akt", "act": "wt", "label": "§ 157", "text": "§ 157. […] 3. Instalacja gazowa w budynku o wysokości większej niż 35 m ponad poziomem terenu może być doprowadzona tylko do pomieszczeń technicznych, w których są zainstalowane urządzenia gazowe, usytuowanych w piwnicy lub na najniższej kondygnacji nadziemnej, a także na najwyższej kondygnacji budynku lub nad tą kondygnacją, pod warunkiem zastosowania urządzeń stabilizujących ciśnienie gazu. 4. Zastosowanie instalacji gazowej w budynkach o wysokości ponad 25 m wymaga uzyskania pozytywnej opinii wydanej przez właściwego komendanta wojewódzkiego Państwowej Straży Pożarnej. 5. Instalacje gazowe zasilane gazem płynnym mogą być wykonywane tylko w budynkach niskich. 6. Zabrania się stosowania w jednym budynku gazu płynnego i gazu z sieci gazowej. 7. W budynku niskim, mającym w mieszkaniach instalację zasilaną gazem płynnym, dopuszcza się usytuowanie kotłowni gazowej zasilanej z sieci gazowej. 8. […]"}], "378": [{"ref": "PN-EN 12845+A1:2020 – ochrona przestrzeni ukrytych", "kind": "norma"}], "380": [{"ref": "§ 216 ust. 1 WT – odnośnik 3 do tabeli (kolumna 4 – strop)", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}], "382": [{"ref": "PN-EN 12845+A1:2020 – tryskacze w regałach", "kind": "norma"}], "383": [{"ref": "§ 220 WT / PN-B-02431-1 – kotłownie gazowe", "kind": "norma"}], "384": [{"ref": "§ 277 WT – oddymianie garaży", "kind": "akt", "act": "wt", "label": "§ 277", "text": "§ 277. […] 3. W garażu zamkniętym obejmującym więcej niż dwie kondygnacje podziemne lub znajdującym się poniżej drugiej kondygnacji podziemnej należy stosować stałe samoczynne urządzenia gaśnicze wodne. Wymagania nie stosuje się do strefy pożarowej garażu, która posiada bezpośredni wjazd lub wyjazd z budynku. 4. W strefie pożarowej garażu zamkniętego należy stosować instalację wentylacji oddymiającej uruchamianą za pomocą systemu wykrywania dymu, w przypadku gdy ta strefa nie posiada bezpośredniego wjazdu lub wyjazdu z budynku lub gdy jej powierzchnia przekracza 1500 m2. 5. W przypadku zastosowania rozwiązania, o którym mowa w ust. 2 pkt 1, klasa odporności ogniowej przewodów wentylacji oddymiającej powinna odpowiadać wymaganiom określonym w § 270 ust. 2 – jedynie z uwagi na kryterium szczelności ogniowej (E)."}], "385": [{"ref": "§ 19 RPB – dobór hydrantów wewnętrznych", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. […] 2. Hydranty 33 muszą być stosowane w garażu: 1) jednokondygnacyjnym zamkniętym o więcej niż 10 stanowiskach postojowych; 2) wielokondygnacyjnym. 3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; 3) przy wejściu do pomieszczeń magazynowych lub technicznych o powierzchni przekraczającej 200 m2 i gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, usytuowanych w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II, ZL III lub ZL V, znajdującej się w budynku niskim albo średniowysokim. 4. […]"}], "386": [{"ref": "PN-EN 12101-1:2007 – kurtyny dymowe", "kind": "norma"}], "387": [{"ref": "§ 12 RW – wymóg drogi pożarowej dla ZL V", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 4) budynku zawierającego strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego poniżej 500 MJ/m2 o powierzchni przekraczającej 20 000 m2; 5) budynku niskiego: a) zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III o powierzchni przekraczającej 1 000 m2, obejmującą kondygnację nadziemną inną niż pierwsza, lub b) zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL V i mającego ponad 50 miejsc noclegowych; www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9068 — Poz. 1030 6) obiektu budowlanego innego niż budynek, przeznaczonego do użyteczności publicznej lub zamieszkania zbiorowego, w którym przewiduje się możliwość jednoczesnego przebywania w strefie pożarowej ponad 50 osób; 7) stanowiska czerpania wody do celów przeciwpożarowych. 2. […]"}], "388": [{"ref": "PN-EN 12845+A1:2020 – czas działania wg klasy zagrożenia", "kind": "norma"}], "389": [{"ref": "§ 181 WT – awaryjne oświetlenie ewakuacyjne", "kind": "akt", "act": "wt", "label": "§ 181", "text": "§ 181. […] 3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego. 4. […]"}], "390": [{"ref": "§ 28 RPB – obiekty wymagające SSP (tereny zamknięte)", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. […] 8) domach pomocy społecznej i ośrodkach rehabilitacji dla osób niepełnosprawnych o liczbie łóżek powyżej 100 w budynku; 9) zakładach pracy zatrudniających powyżej 100 osób niepełnosprawnych w budynku; 10) budynkach użyteczności publicznej wysokich i wysokościowych; 11) budynkach zamieszkania zbiorowego, w których przewidywany okres pobytu tych samych osób przekracza trzy doby, o liczbie miejsc noclegowych powyżej 200; 12) budynkach zamieszkania zbiorowego niewymienionych w pkt 11, o liczbie miejsc noclegowych powyżej 50; 13) archiwach wyznaczonych przez Naczelnego Dyrektora Archiwów Państwowych; 14) muzeach oraz zabytkach budowlanych, wyznaczonych przez Generalnego Konserwatora Zabytków w uzgodnieniu z Komendantem Głównym Państwowej Straży Pożarnej; 15) ośrodkach elektronicznego przetwarzania danych o zasięgu krajowym, wojewódzkim i w urzędach obsługujących organy administracji rządowej; […]"}], "391": [{"ref": "§ 12 RW – wymóg drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 4) budynku zawierającego strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego poniżej 500 MJ/m2 o powierzchni przekraczającej 20 000 m2; 5) budynku niskiego: a) zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III o powierzchni przekraczającej 1 000 m2, obejmującą kondygnację nadziemną inną niż pierwsza, lub b) zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL V i mającego ponad 50 miejsc noclegowych; www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9068 — Poz. 1030 6) obiektu budowlanego innego niż budynek, przeznaczonego do użyteczności publicznej lub zamieszkania zbiorowego, w którym przewiduje się możliwość jednoczesnego przebywania w strefie pożarowej ponad 50 osób; 7) stanowiska czerpania wody do celów przeciwpożarowych. 2. […]"}], "392": [{"ref": "§ 13 RW / WT – okna dla ekip ratowniczych", "kind": "akt", "act": "wt", "label": "§ 13", "text": "§ 13. 1. Odległość budynku z pomieszczeniami przeznaczonymi na pobyt ludzi od innych obiektów powinna umożliwiać naturalne oświetlenie tych pomieszczeń – co uznaje się za spełnione, jeżeli: 1) między ramionami kąta 60°, wyznaczonego w płaszczyźnie poziomej, z wierzchołkiem usytuowanym w wewnętrznym licu ściany na osi okna pomieszczenia przesłanianego, nie znajduje się przesłaniająca część tego samego budynku lub inny obiekt przesłaniający w odległości mniejszej niż: a) wysokość przesłaniania – dla obiektów przesłaniających o wysokości do 35 m, b) 35 m – dla obiektów przesłaniających o wysokości ponad 35 m; 2) zostały zachowane wymagania, o których mowa w § 57 i 60. 2. Wysokość przesłaniania, o której mowa w ust. […]"}], "394": [{"ref": "PN-EN 1838:2013 – czas osiągania natężenia", "kind": "norma"}], "395": [{"ref": "§ 4 rozp. w sprawie uzgadniania projektu pod względem ochrony ppoż.", "kind": "akt", "act": "uzgadnianie", "label": "§ 4", "text": "§ 4. […] Podstawę uzgodnienia stanowią niezbędne do stwierdzenia zgodności projektu z wymaganiami ochrony przeciwpożarowej dane dotyczące warunków ochrony przeciwpożarowej obiektu budowlanego, zależne od jego przeznaczenia, sposobu użytkowania, prowadzonego procesu technologicznego, sposobu magazynowania lub składowania, warunków technicznych oraz występujących w nim zagrożeń pożarowych, obejmujące: 1) w przypadku projektu zagospodarowania działki lub terenu, w szczególności: a) informacje o powierzchni zabudowy, wysokości i liczbie kondygnacji, b) informacje o klasyfikacji pożarowej z uwagi na przeznaczenie i sposób użytkowania, c) informacje o klasie odporności pożarowej oraz odporności ogniowej i stopniu rozprzestrzeniania ognia przez ściany zewnętrzne i dachy, d) informacje o występowaniu zagrożenia wybuchem, w tym informacje dotyczące pomieszczeń zagrożonych wybuchem oraz stref zagrożenia wybuchem w przestrzeni zewnętrznej, e) informacje o usytuowaniu z uwagi na bezpieczeństwo pożarowe, w tym informacje o odległościach od sąsiadujących obiektów budowlanych, działek lub terenów oraz parametrach wpływających na odległości dopuszczalne, f) informacje o przygotowaniu obiektu budowlanego i terenu do prowadzenia działań ratowniczych, w tym informacje o: – drogach pożarowych oraz dojściach dla ekip ratowniczych, – zaopatrzeniu w wodę do zewnętrznego gaszenia pożaru, w tym o wymaganej ilości wody do celów przeciwpożarowych, urządzeniach i innych rozwiązaniach w zakresie przeciwpożarowego zaopatrzenia w wodę, usytuowaniu źródeł wody do celów przeciwpożarowych, hydrantów zewnętrznych lub innych punktów poboru wody oraz stanowisk czerpania wody wraz z dojazdami dla pojazdów pożarniczych, g) informacje o rozwiązaniach zamiennych w stosunku do wymagań ochrony przeciwpożarowej, zastosowanych na podstawie zgody, o której mowa w art. 6c pkt 1 lub 2 ustawy z dnia 24 sierpnia 1991 r. o ochronie przeciwpożarowej, w zakresie rozwiązań objętych projektem zagospodarowania działki lub terenu; […]"}], "396": [{"ref": "PN-EN 12101-2:2017 – urządzenia do grawitacyjnego odprowadzania dymu", "kind": "norma"}], "397": [{"ref": "§ 3–5 RW – wymagane zaopatrzenie w wodę", "kind": "akt", "act": "rw", "label": "§ 3", "text": "§ 3. 1. Zapewnienie przeciwpożarowego zaopatrzenia w wodę do zewnętrznego gaszenia pożaru jest wymagane dla: 1) jednostek osadniczych o liczbie mieszkańców przekraczającej 100 osób, niestanowiących zabudowy kolonijnej, a także znajdujących się w ich granicach: budynków użyteczności publicznej i zamieszkania zbiorowego oraz obiektów budowlanych produkcyjnych i magazynowych; 2) budynków użyteczności publicznej i zamieszkania zbiorowego oraz obiektów budowlanych produkcyjnych i magazynowych, znajdujących się poza granicami jednostek osadniczych wymienionych w pkt 1, o kubaturze brutto przekraczającej 2 500 m3 lub o powierzchni przekraczającej 500 m2, z wyjątkiem stacji paliw płynnych ze zbiornikami o łącznej pojemności do 200 m3 i stacji gazu płynnego; […]"}], "398": [{"ref": "PKN-CEN/TS 54-14:2020 – promienie działania czujek", "kind": "norma"}], "399": [{"ref": "dyrektywa ATEX – kategorie urządzeń i strefy gazowe", "kind": "ue"}], "400": [{"ref": "PN-B-02857:2017 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "401": [{"ref": "§ 245, § 246 WT – obudowa i oddzielenie klatek schodowych", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}], "402": [{"ref": "PN-EN 1363-2:2001 – badania odporności ogniowej, procedury dodatkowe", "kind": "norma"}], "403": [{"ref": "§ 179 WT / rozp. dot. zbiorników gazu płynnego", "kind": "akt", "act": "wt", "label": "§ 179", "text": "§ 179. […] 2) powyżej 10 m3 – nie mniej niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3. 6. Odległość zbiorników z gazem płynnym od granicy działki budowlanej z tymi zbiornikami powinna być nie mniejsza niż połowa odległości określonej w tabeli w ust. 4 w kolumnach 2 i 3, przy zachowaniu wymaganej odległości od budynku danego rodzaju. 7. Odległości określone w tabeli w ust. 4 w kolumnie 2 mogą być zmniejszone do 50% w przypadku zastosowania wolno stojącej ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej R E I 120, usytuowanej pomiędzy zbiornikiem z gazem płynnym a budynkiem. Wymiary wolno stojącej ściany oraz jej odległość od zbiornika powinny być tak dobrane, aby osłonić zbiornik od tej części budynku, która znajduje się w odległości mniejszej niż określona w tabeli w ust. 4 w kolumnie 2 od dowolnego punktu zbiornika. 8. […]"}], "404": [{"ref": "PN-EN 12101-13:2022 – systemy różnicowania ciśnień", "kind": "norma"}], "406": [{"ref": "§ 236 WT – kierunek otwierania drzwi ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 236", "text": "§ 236. 1. Z pomieszczeń przeznaczonych na pobyt ludzi powinna być zapewniona możliwość ewakuacji w bezpieczne miejsce na zewnątrz budynku lub do sąsiedniej strefy pożarowej, bezpośrednio albo drogami komunikacji ogólnej, zwanymi dalej „drogami ewakuacyjnymi”. 2. Ze strefy pożarowej, o której mowa w ust. 1, powinno być wyjście bezpośrednio na zewnątrz budynku lub przez inną strefę pożarową, z zastrzeżeniem § 227 ust. 5. 3. Wyjścia z pomieszczeń na drogi ewakuacyjne powinny być zamykane drzwiami. 4. Drzwi stanowiące wyjście ewakuacyjne z budynku przeznaczonego dla więcej niż 50 osób powinny otwierać się na zewnątrz. Wymaganie to nie dotyczy budynku wpisanego do rejestru zabytków. 5. W wyjściu ewakuacyjnym z budynku dopuszcza się stosowanie drzwi rozsuwanych spełniających wymagania określone w § 240 ust. 4. 6. […]"}], "408": [{"ref": "§ 234, § 256 WT – zamknięcia otworów w oddzieleniach ppoż.", "kind": "akt", "act": "wt", "label": "§ 234", "text": "§ 234. 1. Przepusty instalacyjne w elementach oddzielenia przeciwpożarowego powinny mieć klasę odporności ogniowej (E I) wymaganą dla tych elementów. 2. Dopuszcza się nieinstalowanie przepustów, o których mowa w ust. 1, dla pojedynczych rur instalacji wodnych, kanalizacyjnych i ogrzewczych, wprowadzanych przez ściany i stropy do pomieszczeń higienicznosanitarnych. 3. Przepusty instalacyjne o średnicy większej niż 0,04 m w ścianach i stropach pomieszczenia zamkniętego, dla których wymagana klasa odporności ogniowej jest nie niższa niż E I 60 lub R E I 60, a niebędących elementami oddzielenia przeciwpożarowego, powinny mieć klasę odporności ogniowej (E I) ścian i stropów tego pomieszczenia. 4. Przejścia instalacji przez zewnętrzne ściany budynku, znajdujące się poniżej poziomu terenu, powinny być zabezpieczone przed możliwością przenikania gazu do wnętrza budynku."}], "410": [{"ref": "§ 261 WT – liczba siedzeń w rzędzie i odstępy", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. […] 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; 3) liczbę siedzeń w rzędzie nie większą niż 16 pomiędzy przejściami oraz 8 w rzędzie przyściennym, przy czym dopuszcza się zwiększenie liczby miejsc w rzędach odpowiednio do 40 i 20 pod warunkiem zwiększenia odstępu między rzędami siedzeń o 1 cm na każde dodatkowe siedzenie odpowiednio powyżej 16 lub 8; 4) szerokość przejść komunikacyjnych nie mniejszą niż 1,2 m przy liczbie osób do 150, a przy większej ich liczbie szerokość tę należy zwiększyć proporcjonalnie o 0,6 m na 100 osób; 5) rzędy siedzeń lub ławek trwale umocowane do podłogi albo siedzenia sztywno łączone ze sobą w rzędy oraz między rzędami."}], "411": [{"ref": "§ 37 RPB / WT – urządzenia odciążające pomieszczeń zagrożonych wybuchem", "kind": "akt", "act": "wt", "label": "§ 37", "text": "§ 37. Przepływowe, szczelne osadniki podziemne, stanowiące część przydomowej oczyszczalni ścieków gospodarczo-bytowych, służące do wstępnego ich oczyszczania, mogą być sytuowane w bezpośrednim sąsiedztwie budynków jednorodzinnych, pod warunkiem wyprowadzenia ich odpowietrzenia przez instalację kanalizacyjną co najmniej 0,6 m powyżej górnej krawędzi okien i drzwi zewnętrznych w tych budynkach."}], "413": [{"ref": "PN-EN 1992-1-2:2008 – Eurokod 2, warunki pożarowe", "kind": "norma"}], "415": [{"ref": "PN-EN 12845+A1:2020 – sekcje tandemowe", "kind": "norma"}], "416": [{"ref": "§ 19 RPB – hydranty wewnętrzne w garażach", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. […] 4) Dodany przez § 1 rozporządzenia Ministra Spraw Wewnętrznych i Administracji z dnia 11 stycznia 2019 r. zmieniającego rozporządzenie w sprawie ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów (Dz. U. poz. 67), które weszło w życie z dniem 29 stycznia 2019 r. 2. Hydranty 33 muszą być stosowane w garażu: 1) jednokondygnacyjnym zamkniętym o więcej niż 10 stanowiskach postojowych; 2) wielokondygnacyjnym. 3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; […]"}], "417": [{"ref": "§ 216 ust. 8 WT – palna izolacja cieplna w ścianach", "kind": "akt", "act": "wt", "label": "§ 216", "text": "8. W budynku, na wysokości powyżej 25 m od poziomu terenu, okładzina elewacyjna i jej zamocowanie mechaniczne, a także izolacja cieplna ściany zewnętrznej, powinny być wykonane z materiałów niepalnych."}], "418": [{"ref": "PN-B-02852:2001 – obliczanie gęstości obciążenia ogniowego", "kind": "norma"}], "419": [{"ref": "§ 216, § 219 WT – rozprzestrzenianie ognia przez elementy", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. […] 4. 4) Dla ścian komór zsypu wymaga się klasy E I 60, a dla drzwi komór zsypu klasy E I 30. 5) Klasa odporności ogniowej dotyczy elementów wraz z uszczelnieniami złączy i dylatacjami. 2. Elementy budynku, o których mowa w ust. 1, powinny być nierozprzestrzeniające ognia, przy czym dopuszcza się zastosowanie słabo rozprzestrzeniających ogień: 1) elementów budynku o jednej kondygnacji nadziemnej ZL IV oraz PM, o maksymalnej gęstości obciążenia ogniowego strefy pożarowej do 500 MJ/m2; 2) ścian wewnętrznych i zewnętrznych oraz elementów konstrukcji dachu i jego przekrycia w budynku PM niskim o maksymalnej gęstości obciążenia ogniowego strefy pożarowej do 1000 MJ/m2; 3) ścian zewnętrznych w budynku niskim ZL IV. 3. […]"}], "420": [{"ref": "rozp. z 17.09.2021 (Dz.U. poz. 1722) – uzgadnianie projektu, scenariusz pożarowy", "kind": "norma"}], "421": [{"ref": "§ 19, § 181 WT/RPB – hydranty i awaryjne oświetlenie", "kind": "akt", "act": "wt", "label": "§ 19", "text": "§ 19. 1. Odległość stanowisk postojowych, w tym również zadaszonych, oraz otwartych garaży wielopoziomowych od: placu zabaw dla dzieci, boiska dla dzieci i młodzieży, okien pomieszczeń przeznaczonych na stały pobyt ludzi w budynku opieki zdrowotnej, w budynku oświaty i wychowania, w budynku mieszkalnym, w budynku zamieszkania zbiorowego, z wyjątkiem: hotelu, motelu, pensjonatu, domu wypoczynkowego, domu wycieczkowego, schroniska młodzieżowego i schroniska, nie może być mniejsza niż: 1) dla samochodów osobowych: a) 7 m – w przypadku parkingu do 10 stanowisk postojowych włącznie, b) 10 m – w przypadku parkingu od 11 do 60 stanowisk postojowych włącznie, c) 20 m – w przypadku parkingu powyżej 60 stanowisk postojowych; […]"}], "422": [{"ref": "PN-EN IEC 60079-10-1:2021-09 – klasyfikacja przestrzeni", "kind": "norma"}], "423": [{"ref": "§ 37 RPB / WT – pomieszczenia zagrożone wybuchem, urządzenia odciążające", "kind": "akt", "act": "wt", "label": "§ 37", "text": "§ 37. Przepływowe, szczelne osadniki podziemne, stanowiące część przydomowej oczyszczalni ścieków gospodarczo-bytowych, służące do wstępnego ich oczyszczania, mogą być sytuowane w bezpośrednim sąsiedztwie budynków jednorodzinnych, pod warunkiem wyprowadzenia ich odpowietrzenia przez instalację kanalizacyjną co najmniej 0,6 m powyżej górnej krawędzi okien i drzwi zewnętrznych w tych budynkach."}], "424": [{"ref": "§ 228 ust. 1 i 2 WT – powierzchnie stref PM, część podziemna", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}], "425": [{"ref": "PN-EN 15004-1:2019 – gazowe urządzenia gaśnicze, bezpieczeństwo ludzi", "kind": "norma"}], "426": [{"ref": "PN-EN 13565 / rozp. MG – urządzenia pianowe zbiorników", "kind": "norma"}], "427": [{"ref": "PN-EN 12101-13:2022 / PN-EN 12101-6 – klasy systemów", "kind": "norma"}], "428": [{"ref": "PN-EN 12845+A1:2020 – zasilanie pomp", "kind": "norma"}], "429": [{"ref": "PN-B-02857:2017 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "430": [{"ref": "§ 12 RW – wymóg drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; 4) budynku zawierającego strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego poniżej 500 MJ/m2 o powierzchni przekraczającej 20 000 m2; […]"}], "431": [{"ref": "§ 219 WT – oddzielenie poddasza użytkowego", "kind": "akt", "act": "wt", "label": "§ 219", "text": "§ 219. 1. Przekrycie dachu o powierzchni większej niż 1000 m2 powinno być nierozprzestrzeniające ognia, a palna izolacja cieplna przekrycia powinna być oddzielona od wnętrza budynku przegrodą o klasie odporności ogniowej nie niższej niż R E 15. 2. W budynkach ZL III, ZL IV i ZL V poddasze użytkowe przeznaczone na cele mieszkalne lub biurowe powinno być oddzielone od palnej konstrukcji i palnego przekrycia dachu przegrodami o klasie odporności ogniowej: 1) w budynku niskim – E I 30; 2) w budynku średniowysokim i wysokim – E I 60."}], "432": [{"ref": "PKN-CEN/TS 54-14:2020 – dobór czujek ciepła", "kind": "norma"}], "433": [{"ref": "PN-EN 12845+A1:2020 – zbiorniki hydroforowe", "kind": "norma"}], "434": [{"ref": "PN-EN 1992-1-2:2008 – Eurokod 2, Metoda A", "kind": "norma"}], "435": [{"ref": "§ 8 RPB – składowanie cieczy palnych", "kind": "akt", "act": "rpb", "label": "§ 8", "text": "§ 8. 1. Podczas przechowywania cieczy o temperaturze zapłonu poniżej 328,15 K (55ºC) w budynkach, w strefach pożarowych zaliczonych do kategorii zagrożenia ludzi: 1) jest dopuszczalne przechowywanie w jednej strefie pożarowej, zakwalifikowanej do kategorii zagrożenia ludzi innej niż ZL IV oraz o przeznaczeniu innym niż handlowo-usługowe do 10 dm3 cieczy o temperaturze zapłonu poniżej 294,15 K (21ºC) oraz do 50 dm3 cieczy o temperaturze zapłonu 294,15÷328,15 K (21÷55ºC), a w mieszkaniach odpowiednio do 5 i do 20 dm3 cieczy; 2) jest dopuszczalne przechowywanie w pomieszczeniach handlowo-usługowych cieczy o temperaturze zapłonu do 328,15 K (55ºC) w takiej ilości, że gęstość obciążenia ogniowego stworzona przez te ciecze nie przekroczy 500 MJ/m2; […]"}], "436": [{"ref": "PKN-CEN/TS 54-14:2020 – zasysające czujki dymu", "kind": "norma"}], "437": [{"ref": "§ 5 RW – ilość wody do zewnętrznego gaszenia pożaru", "kind": "akt", "act": "rw", "label": "§ 5", "text": "§ 5. 1. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla budynków użyteczności publicznej i zamieszkania zbiorowego oraz innych obiektów budowlanych o takim przeznaczeniu, służąca do zewnętrznego gaszenia pożaru, wynosi: 1) dla budynku o kubaturze brutto do 5 000 m3 i o powierzchni wewnętrznej do 1 000 m2 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 2) dla budynków niewymienionych w pkt 1 — 20 dm3/s łącznie z co najmniej dwóch hydrantów o średnicy 80 mm lub 200 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 3) dla obiektów wymienionych w § 3 ust. 1 pkt 3 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym. 2. […]"}], "438": [{"ref": "PN-EN 12101-8:2012 – klapy odcinające wentylacji pożarowej", "kind": "norma"}], "439": [{"ref": "§ 4 rozp. w sprawie uzgadniania projektu pod względem ochrony ppoż.", "kind": "akt", "act": "uzgadnianie", "label": "§ 4", "text": "§ 4. […] Podstawę uzgodnienia stanowią niezbędne do stwierdzenia zgodności projektu z wymaganiami ochrony przeciwpożarowej dane dotyczące warunków ochrony przeciwpożarowej obiektu budowlanego, zależne od jego przeznaczenia, sposobu użytkowania, prowadzonego procesu technologicznego, sposobu magazynowania lub składowania, warunków technicznych oraz występujących w nim zagrożeń pożarowych, obejmujące: 1) w przypadku projektu zagospodarowania działki lub terenu, w szczególności: a) informacje o powierzchni zabudowy, wysokości i liczbie kondygnacji, b) informacje o klasyfikacji pożarowej z uwagi na przeznaczenie i sposób użytkowania, c) informacje o klasie odporności pożarowej oraz odporności ogniowej i stopniu rozprzestrzeniania ognia przez ściany zewnętrzne i dachy, d) informacje o występowaniu zagrożenia wybuchem, w tym informacje dotyczące pomieszczeń zagrożonych wybuchem oraz stref zagrożenia wybuchem w przestrzeni zewnętrznej, e) informacje o usytuowaniu z uwagi na bezpieczeństwo pożarowe, w tym informacje o odległościach od sąsiadujących obiektów budowlanych, działek lub terenów oraz parametrach wpływających na odległości dopuszczalne, f) informacje o przygotowaniu obiektu budowlanego i terenu do prowadzenia działań ratowniczych, w tym informacje o: – drogach pożarowych oraz dojściach dla ekip ratowniczych, – zaopatrzeniu w wodę do zewnętrznego gaszenia pożaru, w tym o wymaganej ilości wody do celów przeciwpożarowych, urządzeniach i innych rozwiązaniach w zakresie przeciwpożarowego zaopatrzenia w wodę, usytuowaniu źródeł wody do celów przeciwpożarowych, hydrantów zewnętrznych lub innych punktów poboru wody oraz stanowisk czerpania wody wraz z dojazdami dla pojazdów pożarniczych, g) informacje o rozwiązaniach zamiennych w stosunku do wymagań ochrony przeciwpożarowej, zastosowanych na podstawie zgody, o której mowa w art. 6c pkt 1 lub 2 ustawy z dnia 24 sierpnia 1991 r. o ochronie przeciwpożarowej, w zakresie rozwiązań objętych projektem zagospodarowania działki lub terenu; […]"}], "440": [{"ref": "PN-EN 1993-1-2 – zabezpieczenia ogniochronne konstrukcji stalowych", "kind": "norma"}], "442": [{"ref": "§ 181 WT – awaryjne oświetlenie ewakuacyjne", "kind": "akt", "act": "wt", "label": "§ 181", "text": "§ 181. […] 3. Awaryjne oświetlenie ewakuacyjne należy stosować: 1) w pomieszczeniach: a) widowni kin, teatrów i filharmonii oraz innych sal widowiskowych, b) audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, c) wystawowych w muzeach, d) o powierzchni netto ponad 1000 m2 w garażach oświetlonych wyłącznie światłem sztucznym, e) o powierzchni netto ponad 2000 m2 w budynkach użyteczności publicznej, budynkach zamieszkania zbiorowego oraz w budynkach produkcyjnych i magazynowych; 2) na drogach ewakuacyjnych: a) z pomieszczeń wymienionych w pkt 1, b) oświetlonych wyłącznie światłem sztucznym, c) w szpitalach i innych budynkach przeznaczonych przede wszystkim do użytku osób o ograniczonej zdolności poruszania się, d) w wysokich i wysokościowych budynkach użyteczności publicznej i zamieszkania zbiorowego. 4. […]"}], "443": [{"ref": "§ 227, § 230, § 237, § 256 WT – ulgi przy SUG wodnym", "kind": "akt", "act": "wt", "label": "§ 227", "text": "§ 227. 1. Dopuszczalne powierzchnie stref pożarowych ZL określa poniższa tabela: Kategoria zagrożenia ludzi Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim (N) średniowysokim (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 ZL I, ZL III, ZL IV, ZL V 10 000 8000 5000 2500 ZL II 8000 5000 3500 2000 2. Dopuszczalna powierzchnia strefy pożarowej ZL, obejmującej podziemną część budynku, nie powinna przekraczać 50% dopuszczalnej powierzchni strefy pożarowej tej samej kategorii zagrożenia ludzi, określonej w ust. 1 dla pierwszej nadziemnej kondygnacji tego budynku. 3. Zmniejszenie dopuszczalnej powierzchni strefy pożarowej, o której mowa w ust. 2, nie dotyczy przypadku, gdy wyjścia ewakuacyjne z kondygnacji podziemnej prowadzą bezpośrednio na zewnątrz budynku. 4. […]"}], "444": [{"ref": "PKN-CEN/TS 54-14:2020 – rozmieszczenie czujek ciepła", "kind": "norma"}], "445": [{"ref": "zał. nr 3 WT; PN-EN 13501-5 – klasyfikacja przekryć dachów", "kind": "norma"}], "446": [{"ref": "PN-EN 15004-1:2019 – czas utrzymywania stężenia", "kind": "norma"}], "447": [{"ref": "PN-EN 13501-2:2023 – klasyfikacja ogniowa (kryterium W)", "kind": "norma"}], "449": [{"ref": "§ 157 WT – instalacje gazowe", "kind": "akt", "act": "wt", "label": "§ 157", "text": "§ 157. […] 4. Zastosowanie instalacji gazowej w budynkach o wysokości ponad 25 m wymaga uzyskania pozytywnej opinii wydanej przez właściwego komendanta wojewódzkiego Państwowej Straży Pożarnej. 5. Instalacje gazowe zasilane gazem płynnym mogą być wykonywane tylko w budynkach niskich. 6. Zabrania się stosowania w jednym budynku gazu płynnego i gazu z sieci gazowej. 7. W budynku niskim, mającym w mieszkaniach instalację zasilaną gazem płynnym, dopuszcza się usytuowanie kotłowni gazowej zasilanej z sieci gazowej. 8. Instalacje gazowe zasilane gazem o gęstości większej od gęstości powietrza nie mogą być stosowane w pomieszczeniach, których poziom podłogi znajduje się poniżej otaczającego terenu oraz w których znajdują się studzienki lub kanały instalacyjne i rewizyjne poniżej podłogi."}], "450": [{"ref": "§ 212, § 275 WT – garaże otwarte", "kind": "akt", "act": "wt", "label": "§ 212", "text": "§ 212. […] Liczba kondygnacji nadziemnych ZL I ZL II ZL III 1 2 3 4 1 „D” „D” „D” 2*) „C” „C” „D” *) Gdy poziom stropu nad pierwszą kondygnacją nadziemną jest na wysokości nie większej niż 9 m nad poziomem terenu. 4. Wymaganą klasę odporności pożarowej dla budynku PM oraz IN, z zastrzeżeniem § 282, określa poniższa tabela: Maksymalna gęstość obciążenia ogniowego strefy pożarowej w budynku Q [MJ/m2] Budynek o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) Budynek wielokondygnacyjny niski średniowysoki wysoki wysokościowy (N) (SW) (W) (WW) 1 2 3 4 5 6 Q ≤ 500 „E” „D” „C” „B” „B” 500 < Q ≤ 1000 „D” „D” „C” „B” „B” 1000 < Q ≤ 2000 „C” „C” „C” „B” „B” 2000 < Q ≤ 4000 „B” „B” „B” * * Q > 4000 „A” „A” „A” * * * – Zgodnie z § 228 ust. 1 nie mogą występować takie budynki. 5. […]"}], "451": [{"ref": "§ 10 RW – sieć wodociągowa przeciwpożarowa", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 4) dla hydrantu nadziemnego DN 80 na sieci, o której mowa w § 9 ust. 2 — 5 dm3/s. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9067 — Poz. 1030 9. Dla zapewnienia możliwości intensywnego czerpania wody do celów przeciwpożarowych na sieciach wodociągowych o średnicy nominalnej nie mniejszej niż DN 250 powinny być instalowane hydranty nadziemne, spełniające następujące wymagania: 1) średnica nominalna hydrantu powinna wynosić DN 100 lub DN 150; 2) wydajność nominalna przy ciśnieniu nominalnym 0,2 MPa mierzonym na zaworze hydrantowym podczas poboru wody nie może być mniejsza niż 20 dm3/s; 3) hydranty powinny być usytuowane w miejscach dostępnych z głównych dróg komunikacyjnych na terenie jednostki osadniczej; 4) miejsce usytuowania hydrantu należy oznakować znakami zgodnymi z Polskimi Normami wraz z podaniem na znaku dodatkowym wielkości charakterystycznych hydrantu; […]"}], "454": [{"ref": "§ 256 WT – długość dojść ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "§ 256. […] 3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej. 4. […]"}], "455": [{"ref": "PN-B-02431-1:1999 – kotłownie gazowe", "kind": "norma"}], "456": [{"ref": "§ 10 RW – zasilanie sieci wodociągowej przeciwpożarowej", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 2) dla hydrantu nadziemnego DN 100 — 15 dm3/s; 3) dla hydrantu podziemnego DN 80 — 10 dm3/s; 4) dla hydrantu nadziemnego DN 80 na sieci, o której mowa w § 9 ust. 2 — 5 dm3/s. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9067 — Poz. 1030 9. Dla zapewnienia możliwości intensywnego czerpania wody do celów przeciwpożarowych na sieciach wodociągowych o średnicy nominalnej nie mniejszej niż DN 250 powinny być instalowane hydranty nadziemne, spełniające następujące wymagania: 1) średnica nominalna hydrantu powinna wynosić DN 100 lub DN 150; 2) wydajność nominalna przy ciśnieniu nominalnym 0,2 MPa mierzonym na zaworze hydrantowym podczas poboru wody nie może być mniejsza niż 20 dm3/s; 3) hydranty powinny być usytuowane w miejscach dostępnych z głównych dróg komunikacyjnych na terenie jednostki osadniczej; […]"}], "457": [{"ref": "§ 12 RW – wymóg drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; 4) budynku zawierającego strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego poniżej 500 MJ/m2 o powierzchni przekraczającej 20 000 m2; […]"}], "458": [{"ref": "PN-EN 12845+A1:2020 – źródła zasilania wodą", "kind": "norma"}], "459": [{"ref": "PN-EN 12101-13:2022 – systemy różnicowania ciśnień, klasy", "kind": "norma"}], "460": [{"ref": "art. 10 ustawy o wyrobach budowlanych", "kind": "akt", "act": "wyroby", "label": "art. 10", "text": "Art. 10. 1. Dopuszczone do jednostkowego zastosowania w obiekcie budowlanym są wyroby budowlane, z wyłączeniem wyrobów, o których mowa w art. 5 ust. 1, wykonane według indywidualnej dokumentacji technicznej, sporządzonej przez projektanta obiektu lub z nim uzgodnionej, dla których producent wydał oświadczenie, że zapewniono zgodność wyrobu budowlanego z tą dokumentacją oraz z przepisami. 2. Indywidualna dokumentacja techniczna, o której mowa w ust. 1, powinna zawierać opis rozwiązania konstrukcyjnego, charakterystykę materiałową i informację dotyczącą projektowanych właściwości użytkowych wyrobu budowlanego oraz określać warunki jego zastosowania w danym obiekcie budowlanym, a także, w miarę potrzeb, instrukcję obsługi i eksploatacji. 3. Oświadczenie, o którym mowa w ust. 1, powinno zawierać: 1) nazwę i adres wydającego oświadczenie; 2) nazwę wyrobu budowlanego i miejsce jego wytworzenia; […]"}], "461": [{"ref": "§ 28 RPB – obiekty wymagające SSP", "kind": "akt", "act": "rpb", "label": "§ 28", "text": "§ 28. 1. Stosowanie systemu sygnalizacji pożarowej, obejmującego urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych, jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych o powierzchni strefy pożarowej powyżej 5000 m2, b) wielokondygnacyjnych o powierzchni strefy pożarowej powyżej 2500 m2; 2) teatrach o liczbie miejsc powyżej 300; 3) kinach o liczbie miejsc powyżej 600; 4) budynkach o liczbie miejsc służących celom gastronomicznym powyżej 300; 5) salach widowiskowych i sportowych o liczbie miejsc powyżej 1500; 6) szpitalach, z wyjątkiem psychiatrycznych, oraz w sanatoriach ‒ o liczbie łóżek powyżej 200 w budynku; 7) szpitalach psychiatrycznych o liczbie łóżek powyżej 100 w budynku; […]"}], "463": [{"ref": "PKN-CEN/TS 54-14:2020 – czujki liniowe dymu", "kind": "norma"}], "464": [{"ref": "§ 271 WT – odległości między budynkami", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20 2. […]"}], "465": [{"ref": "PKN-CEN/TS 54-14:2020 – rozmieszczenie czujek ciepła", "kind": "norma"}], "466": [{"ref": "dyrektywa ATEX – kategorie urządzeń a strefy", "kind": "ue"}], "467": [{"ref": "PN-EN 12845+A1:2020 – ESFR, świetliki", "kind": "norma"}], "468": [{"ref": "§ 240 WT – wydzielanie pomieszczeń technicznych", "kind": "akt", "act": "wt", "label": "§ 240", "text": "§ 240. […] 5. W bramach i ścianach przesuwanych na drogach ewakuacyjnych powinny znajdować się drzwi otwierane ręcznie albo w bezpośrednim sąsiedztwie tych bram i ścian powinny być umieszczone i wyraźnie oznakowane drzwi przeznaczone do celów ewakuacji. 6. Drzwi, bramy i inne zamknięcia otworów o wymaganej klasie odporności ogniowej lub dymoszczelności powinny być zaopatrzone w urządzenia, zapewniające samoczynne zamykanie otworu w razie pożaru. Należy też zapewnić możliwość ręcznego otwierania drzwi służących do ewakuacji. 7. Drzwi stanowiące wyjście ewakuacyjne z pomieszczenia, w którym może przebywać jednocześnie więcej niż 300 osób, oraz drzwi na drodze ewakuacyjnej z tego pomieszczenia, powinny być wyposażone w urządzenia przeciwpaniczne."}], "469": [{"ref": "§ 258 WT – wymagania dla posadzek", "kind": "akt", "act": "wt", "label": "§ 258", "text": "§ 258. 1. W strefach pożarowych ZL I, ZL II, ZL III i ZL V stosowanie do wykończenia wnętrz materiałów i wyrobów łatwo zapalnych, których produkty rozkładu termicznego są bardzo toksyczne lub intensywnie dymiące, jest zabronione. 1a. W przypadku stosowania materiałów wykończeniowych luźno zwisających, w szczególności w kurtynach, zasłonach, draperiach, kotarach oraz żaluzjach, za łatwo zapalne uważa się materiały, których właściwości określone w badaniach zgodnych z Polskimi Normami odnoszącymi się do zapalności i rozprzestrzeniania płomienia przez wyroby włókiennicze nie spełniają co najmniej jednego z kryteriów: 1) ti ≥ 4 s; 2) ts ≤ 30 s; 3) nie następuje przepalenie trzeciej nitki; 4) nie występują płonące krople. 2. Na drogach komunikacji ogólnej, służących celom ewakuacji, stosowanie materiałów i wyrobów budowlanych łatwo zapalnych jest zabronione."}], "470": [{"ref": "PN-B-02877-4:2001/Az1:2006 – usytuowanie klap dymowych", "kind": "norma"}], "472": [{"ref": "PN-EN 13501-4:2016 – klasyfikacja klap odcinających", "kind": "norma"}], "474": [{"ref": "PN-B-02857:2017 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "475": [{"ref": "PN-EN 81-72:2020 – dźwigi dla straży pożarnej", "kind": "norma"}], "476": [{"ref": "§ 28, § 29 RPB; § 181 WT", "kind": "akt", "act": "wt", "label": "§ 28", "text": "§ 28. 1. Działka budowlana, na której sytuowane są budynki, powinna być wyposażona w kanalizację umożliwiającą odprowadzenie wód opadowych do sieci kanalizacji deszczowej lub ogólnospławnej. 2. W przypadku budynków niskich lub budynków, dla których nie ma możliwości przyłączenia do sieci kanalizacji deszczowej lub ogólnospławnej, dopuszcza się odprowadzenie wód opadowych na własny teren nieutwardzony, do dołów chłonnych lub do zbiorników retencyjnych."}], "478": [{"ref": "§ 179 WT – zbiorniki gazu płynnego", "kind": "akt", "act": "wt", "label": "§ 179", "text": "§ 179. […] 4. Dopuszczalną odległość zbiorników z gazem płynnym od budynków mieszkalnych, budynków zamieszkania zbiorowego oraz budynków użyteczności publicznej, a także między zbiornikami, określa poniższa tabela: Nominalna pojemność zbiornika w m3 Odległość budynków mieszkalnych, budynków zamieszkania zbiorowego i budynków użyteczności publicznej od: Odległość od sąsiedniego zbiornika naziemnego lub podziemnego w m zbiornika naziemnego w m zbiornika podziemnego w m 1 2 3 4 do 3 3 1 1 powyżej 3 do 5 5 2,5 1 powyżej 5 do 7 7,5 3 1,5 powyżej 7 do 10 10 5 1,5 powyżej 10 do 40 20 10 ¼ sumy średnic dwóch sąsiednich zbiorników powyżej 40 do 65 30 15 powyżej 65 do 100 40 20 5. Dopuszczalna odległość zbiorników z gazem płynnym od budynków produkcyjnych i magazynowych powinna wynosić dla zbiorników o pojemności: 1) do 10 m3 – nie mniej niż odległość określona w tabeli w ust. 4 w kolumnach 2 i 3; […]"}], "479": [{"ref": "§ 37 RPB / WT – urządzenia odciążające", "kind": "akt", "act": "wt", "label": "§ 37", "text": "§ 37. Przepływowe, szczelne osadniki podziemne, stanowiące część przydomowej oczyszczalni ścieków gospodarczo-bytowych, służące do wstępnego ich oczyszczania, mogą być sytuowane w bezpośrednim sąsiedztwie budynków jednorodzinnych, pod warunkiem wyprowadzenia ich odpowietrzenia przez instalację kanalizacyjną co najmniej 0,6 m powyżej górnej krawędzi okien i drzwi zewnętrznych w tych budynkach."}], "480": [{"ref": "§ 27, § 29 RPB", "kind": "akt", "act": "rpb", "label": "§ 27", "text": "§ 27. […] 2) muzeach oraz zabytkach budowlanych, wyznaczonych przez Generalnego Konserwatora Zabytków w uzgodnieniu z Komendantem Głównym Państwowej Straży Pożarnej; 3) ośrodkach elektronicznego przetwarzania danych o znaczeniu krajowym. 2. Stosowanie stałych samoczynnych urządzeń gaśniczych wodnych jest wymagane w: 1) budynkach handlowych lub wystawowych: a) jednokondygnacyjnych, w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 8000 m2, b) wielokondygnacyjnych, w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I o powierzchni powyżej 5000 m2; 2) w budynkach o liczbie miejsc służących celom gastronomicznym powyżej 600; 3) budynkach użyteczności publicznej wysokościowych; 4) budynkach zamieszkania zbiorowego wysokościowych. 3. […]"}], "481": [{"ref": "§ 267 WT – przewody wentylacyjne", "kind": "akt", "act": "wt", "label": "§ 267", "text": "§ 267. […] 5. W kuchni lub w aneksie kuchennym w mieszkaniu dopuszcza się stosowanie przewodów wentylacji wywiewnej z materiałów co najmniej trudno zapalnych. 6. Elastyczne elementy łączące, służące do połączenia sztywnych przewodów wentylacyjnych z elementami instalacji lub urządzeniami, z wyjątkiem wentylatorów, powinny być wykonane z materiałów co najmniej trudno zapalnych, posiadać długość nie większą niż 4 m, przy czym nie powinny być prowadzone przez elementy oddzielenia przeciwpożarowego. 7. Elastyczne elementy łączące wentylatory z przewodami wentylacyjnymi powinny być wykonane z materiałów co najmniej trudno zapalnych, przy czym ich długość nie powinna przekraczać 0,25 m. 8. Izolacje cieplne i akustyczne zastosowane w instalacjach: wodociągowej, kanalizacyjnej i ogrzewczej powinny być wykonane w sposób zapewniający nierozprzestrzenianie ognia."}], "482": [{"ref": "PN-B-02877-4:2025-07 – oddymianie grawitacyjne", "kind": "norma"}], "483": [{"ref": "§ 225 WT – pas międzykondygnacyjny", "kind": "akt", "act": "wt", "label": "§ 225", "text": "§ 225. Elementy okładzin elewacyjnych powinny być mocowane do konstrukcji budynku w sposób uniemożliwiający ich odpadanie w przypadku pożaru w czasie krótszym niż wynikający z wymaganej klasy odporności ogniowej dla ściany zewnętrznej, określonej w § 216 ust. 1, odpowiednio do klasy odporności pożarowej budynku, w którym są one zamocowane. Rozdział 3 Strefy pożarowe i oddzielenia przeciwpożarowe"}], "484": [{"ref": "§ 12–13 RW – droga pożarowa, nacisk osi", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] Pomiędzy tą drogą i ścianą budynku nie mogą występować stałe elementy zagospodarowania terenu lub drzewa i krzewy o wysokości przekraczającej 3 m, uniemożliwiające dostęp do elewacji budynku za pomocą podnośników i drabin mechanicznych. 3. W przypadkach uzasadnionych warunkami lokalnymi, w szczególności architektonicznymi, droga pożarowa do budynków, o których mowa w ust. 1 pkt 1—4, może być poprowadzona w taki sposób, aby był zapewniony dostęp do: 1) 30 % obwodu zewnętrznego budynku, przy jego rozpiętości (największej szerokości) do 60 m, 2) 50 % obwodu zewnętrznego budynku, przy jego rozpiętości przekraczającej 60 m, 3) 100 % długości elewacji od frontu budynku, przy zabudowie pierzejowej — przy spełnieniu pozostałych wymagań określonych w ust. 2. 4. […]"}], "485": [{"ref": "§ 267 WT – przejścia przewodów wentylacyjnych", "kind": "akt", "act": "wt", "label": "§ 267", "text": "§ 267. […] U. poz. 248), które weszło w życie z dniem 17 lutego 2022 r. 1b.9) W budynkach mieszkalnych jednorodzinnych, w których wydzielono dwa lokale mieszkalne albo jeden lokal mieszkalny i lokal użytkowy, oraz w budynkach mieszkalnych wielorodzinnych, w obrębie jednego lokalu mieszkalnego, dopuszcza się stosowanie przewodów wentylacyjnych o klasie reakcji na ogień co najmniej E pod warunkiem zainstalowania w miejscu przejścia przewodów wentylacyjnych przez przegrody wydzielające lokal mieszkalny lub lokal użytkowy: 1) w budynkach niskich (N) i średniowysokich (SW) – zabezpieczenia ogniochronnego o klasie odporności ogniowej co najmniej E I 30; 2) w budynkach wysokich (W) i wysokościowych (WW) – przeciwpożarowej klapy odcinającej o klasie odporności ogniowej co najmniej E I S 60. 2. […]"}], "486": [{"ref": "§ 258 WT – wykończenie wnętrz; wskaźnik toksyczności", "kind": "akt", "act": "wt", "label": "§ 258", "text": "§ 258. 1. W strefach pożarowych ZL I, ZL II, ZL III i ZL V stosowanie do wykończenia wnętrz materiałów i wyrobów łatwo zapalnych, których produkty rozkładu termicznego są bardzo toksyczne lub intensywnie dymiące, jest zabronione. 1a. W przypadku stosowania materiałów wykończeniowych luźno zwisających, w szczególności w kurtynach, zasłonach, draperiach, kotarach oraz żaluzjach, za łatwo zapalne uważa się materiały, których właściwości określone w badaniach zgodnych z Polskimi Normami odnoszącymi się do zapalności i rozprzestrzeniania płomienia przez wyroby włókiennicze nie spełniają co najmniej jednego z kryteriów: 1) ti ≥ 4 s; 2) ts ≤ 30 s; 3) nie następuje przepalenie trzeciej nitki; 4) nie występują płonące krople. 2. Na drogach komunikacji ogólnej, służących celom ewakuacji, stosowanie materiałów i wyrobów budowlanych łatwo zapalnych jest zabronione."}], "487": [{"ref": "§ 4 rozp. w sprawie uzgadniania projektu pod względem ochrony ppoż.", "kind": "akt", "act": "uzgadnianie", "label": "§ 4", "text": "§ 4. […] Podstawę uzgodnienia stanowią niezbędne do stwierdzenia zgodności projektu z wymaganiami ochrony przeciwpożarowej dane dotyczące warunków ochrony przeciwpożarowej obiektu budowlanego, zależne od jego przeznaczenia, sposobu użytkowania, prowadzonego procesu technologicznego, sposobu magazynowania lub składowania, warunków technicznych oraz występujących w nim zagrożeń pożarowych, obejmujące: 1) w przypadku projektu zagospodarowania działki lub terenu, w szczególności: a) informacje o powierzchni zabudowy, wysokości i liczbie kondygnacji, b) informacje o klasyfikacji pożarowej z uwagi na przeznaczenie i sposób użytkowania, c) informacje o klasie odporności pożarowej oraz odporności ogniowej i stopniu rozprzestrzeniania ognia przez ściany zewnętrzne i dachy, d) informacje o występowaniu zagrożenia wybuchem, w tym informacje dotyczące pomieszczeń zagrożonych wybuchem oraz stref zagrożenia wybuchem w przestrzeni zewnętrznej, e) informacje o usytuowaniu z uwagi na bezpieczeństwo pożarowe, w tym informacje o odległościach od sąsiadujących obiektów budowlanych, działek lub terenów oraz parametrach wpływających na odległości dopuszczalne, f) informacje o przygotowaniu obiektu budowlanego i terenu do prowadzenia działań ratowniczych, w tym informacje o: – drogach pożarowych oraz dojściach dla ekip ratowniczych, – zaopatrzeniu w wodę do zewnętrznego gaszenia pożaru, w tym o wymaganej ilości wody do celów przeciwpożarowych, urządzeniach i innych rozwiązaniach w zakresie przeciwpożarowego zaopatrzenia w wodę, usytuowaniu źródeł wody do celów przeciwpożarowych, hydrantów zewnętrznych lub innych punktów poboru wody oraz stanowisk czerpania wody wraz z dojazdami dla pojazdów pożarniczych, g) informacje o rozwiązaniach zamiennych w stosunku do wymagań ochrony przeciwpożarowej, zastosowanych na podstawie zgody, o której mowa w art. 6c pkt 1 lub 2 ustawy z dnia 24 sierpnia 1991 r. o ochronie przeciwpożarowej, w zakresie rozwiązań objętych projektem zagospodarowania działki lub terenu; […]"}], "489": [{"ref": "PKN-CEN/TS 54-14:2020 – rozmieszczenie czujek", "kind": "norma"}], "490": [{"ref": "§ 277 ust. 1 i 2 WT – powierzchnia strefy pożarowej garażu zamkniętego", "kind": "akt", "act": "wt", "label": "§ 277", "text": "§ 277. 1. Powierzchnia strefy pożarowej w nadziemnym lub podziemnym garażu zamkniętym nie powinna przekraczać 5000 m2."}], "491": [{"ref": "§ 12 RW – parametry drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 7) stanowiska czerpania wody do celów przeciwpożarowych. 2. Droga pożarowa powinna przebiegać wzdłuż dłuższego boku budynku, o którym mowa w ust. 1 pkt 1—4, na całej jego długości, a w przypadku gdy krótszy bok budynku ma więcej niż 60 m — z jego dwóch stron, przy czym bliższa krawędź drogi pożarowej musi być oddalona od ściany budynku o 5—15 m dla obiektów zaliczanych do kategorii zagrożenia ludzi i o 5—25 m dla pozostałych obiektów. Pomiędzy tą drogą i ścianą budynku nie mogą występować stałe elementy zagospodarowania terenu lub drzewa i krzewy o wysokości przekraczającej 3 m, uniemożliwiające dostęp do elewacji budynku za pomocą podnośników i drabin mechanicznych. 3. […]"}], "492": [{"ref": "§ 216, § 217 WT – konstrukcja dachu z drewna klejonego", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}], "494": [{"ref": "PN-EN 13501-4:2016-07 – klasyfikacja klap odcinających", "kind": "norma"}], "495": [{"ref": "§ 19 RPB – hydranty wewnętrzne w strefach ZL", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. 1. Hydranty 25 muszą być stosowane w strefach pożarowych zakwalifikowanych do kategorii zagrożenia ludzi ZL: 1) na każdej kondygnacji budynku wysokiego i wysokościowego, z wyjątkiem kondygnacji obejmującej wyłącznie strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL IV; […]"}], "496": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "497": [{"ref": "§ 245 WT – zabezpieczenie klatek schodowych", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}], "498": [{"ref": "§ 245 WT – liczba klatek schodowych", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}], "499": [{"ref": "§ 216, § 220 WT – klasy odporności ogniowej stropów/antresol", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}], "500": [{"ref": "§ 19–20 RPB – instalacja wodociągowa przeciwpożarowa w budynkach wysokich", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. […] 2) na każdej kondygnacji budynku innego niż tymczasowy, niskiego i średniowysokiego: a) w strefie pożarowej o powierzchni przekraczającej 200 m2, zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II lub ZL V, b) w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL III: – o powierzchni przekraczającej 200 m2 w budynku średniowysokim, przy czym jeżeli jest to strefa pożarowa obejmująca tylko pierwszą kondygnację nadziemną, a nad nią znajdują się wyłącznie strefy pożarowe ZL IV, jedynie wtedy, gdy powierzchnia tej strefy pożarowej przekracza 1000 m2, – o powierzchni przekraczającej 1000 m2 w budynku niskim. 4) Dodany przez § 1 rozporządzenia Ministra Spraw Wewnętrznych i Administracji z dnia 11 stycznia 2019 r. zmieniającego rozporządzenie w sprawie ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów (Dz. U. poz. […]"}], "501": [{"ref": "§ 271 ust. 1 WT – tabela odległości", "kind": "akt", "act": "wt", "label": "§ 271", "text": "§ 271. 1. Odległość między zewnętrznymi ścianami budynków niebędącymi ścianami oddzielenia przeciwpożarowego, a mającymi na powierzchni większej niż 65% klasę odporności ogniowej (E), określoną w § 216 ust. 1 w 5 kolumnie tabeli, nie powinna, z zastrzeżeniem ust. 2 i 3, być mniejsza niż odległość w metrach określona w poniższej tabeli: Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 Rodzaj budynku oraz dla budynku PM maksymalna gęstość obciążenia ogniowego strefy pożarowej PM Q w MJ/m2 ZL IN PM Q ≤ 1000 1000 < Q ≤ 4000 Q > 4000 1 2 3 4 5 6 ZL 8 8 8 15 20 IN 8 8 8 15 20 PM Q ≤ 1000 8 8 8 15 20 PM 1000 < Q ≤ 4000 15 15 15 15 20 PM Q > 4000 20 20 20 20 20"}, {"ref": "§ 271 ust. 7 WT – zmniejszenie o 25% przy SUG wodnych", "kind": "akt", "act": "wt", "label": "§ 271", "text": "7. Odległość od ściany zewnętrznej budynku lub jej części do ściany zewnętrznej drugiego budynku może być zmniejszona o 25%, w stosunku do określonej w ust. 1–5, jeżeli we wszystkich strefach pożarowych budynku, przylegających odpowiednio do tej ściany lub jej części, są stosowane stałe urządzenia gaśnicze wodne."}], "503": [{"ref": "§ 228 ust. 1 WT", "kind": "akt", "act": "wt", "label": "§ 228", "text": "§ 228. 1. Dopuszczalne powierzchnie stref pożarowych PM, z wyjątkiem garaży, określa poniższa tabela: Rodzaj stref pożarowych Gęstość obciążenia ogniowego Q [MJ/m2] Dopuszczalna powierzchnia strefy pożarowej w m2 w budynku o jednej kondygnacji nadziemnej (bez ograniczenia wysokości) w budynku wielokondygnacyjnym niskim i średniowysokim (N) i (SW) wysokim i wysokościowym (W) i (WW) 1 2 3 4 5 Strefy pożarowe z pomieszczeniem zagrożonym wybuchem Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 1000 2000 4000 6000 8000 * * 1000 2000 3000 * * * 500 1000 Strefy pożarowe pozostałe Q > 4000 2000 < Q ≤ 4000 1000 < Q ≤ 2000 500 < Q ≤ 1000 Q ≤ 500 2000 4000 8000 15 000 20 000 1000 2000 4000 8000 10 000 * * 1000 2500 5000 * Nie dopuszcza się takich przypadków."}, {"ref": "§ 229 ust. 1 pkt 2 WT", "kind": "akt", "act": "wt", "label": "§ 229", "text": "§ 229. 1. Dopuszcza się powiększenie powierzchni stref pożarowych, o których mowa w § 228, pod warunkiem ich ochrony: 1) stałymi samoczynnymi urządzeniami gaśniczymi wodnymi – o 100%; 2) samoczynnymi urządzeniami oddymiającymi – o 50%."}], "504": [{"ref": "§ 9 ust. 1 i 2 RW – sieć wodociągowa przeciwpożarowa", "kind": "akt", "act": "rw", "label": "§ 9", "text": "§ 9. 1. Sieć wodociągowa stanowiąca źródło wody do celów przeciwpożarowych, zwana dalej „siecią wodociągową przeciwpożarową”, powinna być zasilana z pompowni przeciwpożarowej, zbiornika wieżowego, studni lub innych urządzeń, zapewniających wymaganą wydajność i ciśnienie w hydrantach zewnętrznych, nawet tych niekorzystnie ulokowanych, przez co najmniej 2 godziny."}], "505": [{"ref": "§ 10 RW – hydranty zewnętrzne, stanowisko czerpania", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 3) hydranty powinny być usytuowane w miejscach dostępnych z głównych dróg komunikacyjnych na terenie jednostki osadniczej; 4) miejsce usytuowania hydrantu należy oznakować znakami zgodnymi z Polskimi Normami wraz z podaniem na znaku dodatkowym wielkości charakterystycznych hydrantu; 5) przy hydrancie należy przewidzieć stanowisko czerpania wody o wymiarach zapewniających swobodny dostęp do hydrantu; 6) na stanowisku czerpania wody należy umieścić zakaz parkowania. 10. Określenia potrzeb w zakresie instalowania hydrantów, o których mowa w ust. 9, dokonują właściwe miejscowo organy Państwowej Straży Pożarnej w ramach opiniowania projektów studium uwarunkowań i kierunków zagospodarowania przestrzennego gminy oraz projektów miejscowych planów zagospodarowania przestrzennego, w trybie określonym w przepisach o planowaniu i zagospodarowaniu przestrzennym. 11. […]"}], "507": [{"ref": "PN-EN 12845+A1:2020 – hydrofory", "kind": "norma"}], "508": [{"ref": "§ 6–7 RW – wymagana ilość wody dla stref poza budynkami", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. […] 6. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla zbiorników z produktami naftowymi, z wyjątkiem występujących na stacjach paliw i stacjach gazu płynnego oraz wymienionych w ust. 5, określa się zgodnie z przepisami rozporządzenia Ministra Gospodarki z dnia 21 listopada 2005 r. w sprawie warunków technicznych, jakim powinny odpowiadać bazy i stacje paliw płynnych, rurociągi przesyłowe dalekosiężne służące do transportu ropy naftowej i produktów naftowych i ich usytuowanie (Dz. U. Nr 243, poz. 2063 oraz z 2007 r. Nr 240, poz. 1753). 7. Wymaganą ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla urządzeń technologicznych oraz składów i magazynów z gazami palnymi i cieczami o temperaturze zapłonu do 373,15 K (100 °C), zlokalizowanych poza budynkami, określa tabela nr 4 załącznika do rozporządzenia. 8. […]"}, {"ref": "PN-B-02857 – przeciwpożarowe zbiorniki wodne (obliczanie zapasu)", "kind": "norma"}], "510": [{"ref": "PN-EN 1838:2025-05 – oświetlenie strefy otwartej (antypaniczne)", "kind": "norma"}], "511": [{"ref": "PN-EN 12101-13:2022 – systemy różnicowania ciśnień", "kind": "norma"}], "512": [{"ref": "PKN-CEN/TS 54-14:2020 – rozmieszczenie czujek a wentylacja", "kind": "norma"}], "514": [{"ref": "PN-EN 12845+A1:2020 – przyłączanie tryskaczy", "kind": "norma"}], "515": [{"ref": "PN-EN 12845+A1:2020 – uzupełnianie zapasu wody", "kind": "norma"}], "516": [{"ref": "PN-EN 15004-1:2025-05 – urządzenia gaśnicze gazowe", "kind": "norma"}], "517": [{"ref": "§ 253 WT – biegi i spoczniki schodów", "kind": "akt", "act": "wt", "label": "§ 253", "text": "§ 253. 1. W budynku ZL I, ZL II, ZL III lub ZL V, mającym kondygnację z posadzką na wysokości powyżej 25 m ponad poziomem terenu przy najniżej położonym wejściu do budynku oraz w budynku wysokościowym (WW) ZL IV przynajmniej jeden dźwig powinien być przystosowany do potrzeb ekip ratowniczych, spełniając wymagania Polskiej Normy dotyczącej dźwigów dla straży pożarnej. Dźwig dla ekip ratowniczych powinien zapewniać dostęp do każdej strefy pożarowej na kondygnacji bezpośrednio lub drogami komunikacji ogólnej. 2. Dojście do dźwigu dla ekip ratowniczych powinno prowadzić przez przedsionek przeciwpożarowy spełniający wymagania określone w § 232. 3. Ściany i stropy szybu dźwigu dla ekip ratowniczych powinny mieć klasę odporności ogniowej wymaganą jak dla stropów budynku, zgodnie z § 216. 4. Szyb dźwigu dla ekip ratowniczych powinien być wyposażony w urządzenia zapobiegające zadymieniu."}], "519": [{"ref": "PN-EN 81-72:2020-12 – dźwigi dla straży pożarnej", "kind": "norma"}], "521": [{"ref": "§ 234 ust. 1 i 3 WT – przepusty instalacyjne", "kind": "akt", "act": "wt", "label": "§ 234", "text": "§ 234. 1. Przepusty instalacyjne w elementach oddzielenia przeciwpożarowego powinny mieć klasę odporności ogniowej (E I) wymaganą dla tych elementów."}, {"ref": "§ 216 ust. 1 WT – klasa B, ściana wewnętrzna EI 30", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}], "522": [{"ref": "PN-B-02877-4:2025-07 – strefy dymowe", "kind": "norma"}], "524": [{"ref": "PN-EN 12845+A1:2020 – tryskacze w regałach", "kind": "norma"}], "525": [{"ref": "§ 253 WT – biegi i spoczniki schodów", "kind": "akt", "act": "wt", "label": "§ 253", "text": "§ 253. 1. W budynku ZL I, ZL II, ZL III lub ZL V, mającym kondygnację z posadzką na wysokości powyżej 25 m ponad poziomem terenu przy najniżej położonym wejściu do budynku oraz w budynku wysokościowym (WW) ZL IV przynajmniej jeden dźwig powinien być przystosowany do potrzeb ekip ratowniczych, spełniając wymagania Polskiej Normy dotyczącej dźwigów dla straży pożarnej. Dźwig dla ekip ratowniczych powinien zapewniać dostęp do każdej strefy pożarowej na kondygnacji bezpośrednio lub drogami komunikacji ogólnej. 2. Dojście do dźwigu dla ekip ratowniczych powinno prowadzić przez przedsionek przeciwpożarowy spełniający wymagania określone w § 232. 3. Ściany i stropy szybu dźwigu dla ekip ratowniczych powinny mieć klasę odporności ogniowej wymaganą jak dla stropów budynku, zgodnie z § 216. 4. Szyb dźwigu dla ekip ratowniczych powinien być wyposażony w urządzenia zapobiegające zadymieniu."}], "526": [{"ref": "§ 10 RW – sieć wodociągowa przeciwpożarowa", "kind": "akt", "act": "rw", "label": "§ 10", "text": "§ 10. […] 2) dla hydrantu nadziemnego DN 100 — 15 dm3/s; 3) dla hydrantu podziemnego DN 80 — 10 dm3/s; 4) dla hydrantu nadziemnego DN 80 na sieci, o której mowa w § 9 ust. 2 — 5 dm3/s. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9067 — Poz. 1030 9. Dla zapewnienia możliwości intensywnego czerpania wody do celów przeciwpożarowych na sieciach wodociągowych o średnicy nominalnej nie mniejszej niż DN 250 powinny być instalowane hydranty nadziemne, spełniające następujące wymagania: 1) średnica nominalna hydrantu powinna wynosić DN 100 lub DN 150; 2) wydajność nominalna przy ciśnieniu nominalnym 0,2 MPa mierzonym na zaworze hydrantowym podczas poboru wody nie może być mniejsza niż 20 dm3/s; 3) hydranty powinny być usytuowane w miejscach dostępnych z głównych dróg komunikacyjnych na terenie jednostki osadniczej; […]"}], "527": [{"ref": "§ 256 ust. 3 (odnośnik 2) i ust. 4 WT – długości dojść ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej."}], "528": [{"ref": "§ 249 WT – przeszklenia i ściany przy narożach", "kind": "akt", "act": "wt", "label": "§ 249", "text": "§ 249. 1. Ściany wewnętrzne i stropy stanowiące obudowę klatki schodowej lub pochylni powinny mieć klasę odporności ogniowej określoną zgodnie z § 216, jak dla stropów budynku. 2. (uchylony). 3. Biegi i spoczniki schodów oraz pochylnie służące do ewakuacji powinny być wykonane z materiałów niepalnych i mieć klasę odporności ogniowej co najmniej: 1) w budynkach o klasie odporności pożarowej „A”, „B” i „C” – R 60; 2) w budynkach o klasie odporności pożarowej „D” i „E” – R 30. 4. Wymaganie klasy odporności ogniowej, o którym mowa w ust. 3, nie dotyczy klatek schodowych wydzielonych na każdej kondygnacji przedsionkami przeciwpożarowymi oraz schodów na antresolę w pomieszczeniu, w którym się ona znajduje, jeżeli antresola ta jest przeznaczona do użytku nie więcej niż 10 osób. 5. […]"}], "529": [{"ref": "§ 6, § 8 RW – zapas wody do zewnętrznego gaszenia", "kind": "akt", "act": "rw", "label": "§ 6", "text": "§ 6. […] 2. W przypadku gdy w obiektach budowlanych produkcyjnych i magazynowych urządzenia i zasoby wody, o których mowa w ust. 1, nie zapewniają wymaganej ilości do celów przeciwpożarowych do zewnętrznego gaszenia pożaru, wykorzystuje się urządzenia służące do dostarczania wody do jednostek osadniczych lub uzupełniające źródła wody, o których mowa w § 4 ust. 5. 3. Wymaganą ilość wody do celów przeciwpożarowych dla obiektów budowlanych produkcyjnych i magazynowych, z wyjątkiem wymienionych w ust. 4—8, służącą do zewnętrznego gaszenia pożaru, określa się, biorąc pod uwagę tę strefę pożarową, dla której jest ona największa, zgodnie z tabelą nr 2 załącznika do rozporządzenia. www.rcl.gov.pl Dziennik Ustaw Nr 124 — 9065 — Poz. 1030 4. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla stacji paliw i stacji gazu płynnego oraz stacji gazu ziemnego wynosi 10 dm3/s. 5. […]"}], "530": [{"ref": "PN-B-02877-4:2025-07 – powietrze kompensacyjne", "kind": "norma"}], "531": [{"ref": "§ 181 WT / PN-HD 60364-5-56 – zasilanie urządzeń ppoż.", "kind": "norma"}], "532": [{"ref": "§ 256 WT – podział korytarzy ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 256", "text": "§ 256. […] 3. Dopuszczalne długości dojść ewakuacyjnych w strefach pożarowych określa poniższa tabela: Rodzaj strefy pożarowej Długość dojścia w m przy jednym dojściu przy co najmniej 2 dojściach1) 1 2 3 Z pomieszczeniem zagrożonym wybuchem 10 40 PM o gęstości obciążenia ogniowego Q > 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 302) 60 PM o gęstości obciążenia ogniowego Q ≤ 500 MJ/m2 bez pomieszczenia zagrożonego wybuchem 602) 100 ZL I, II i V 10 40 ZL III 302) 60 ZL IV 602) 100 1) Dla dojścia najkrótszego, przy czym dopuszcza się dla drugiego dojścia długość większą o 100% od najkrótszego. Dojścia te nie mogą się pokrywać ani krzyżować, przy czym dopuszcza się ich wspólny początkowy przebieg na długości nie większej niż 2 m. 2) W tym nie więcej niż 20 m na poziomej drodze ewakuacyjnej. 4. […]"}], "533": [{"ref": "§ 12 RW – parametry drogi pożarowej", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 2) budynku należącego do grupy wysokości: średniowysoki, wysoki lub wysokościowy, zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL III, ZL IV lub ZL V; 3) budynku zawierającego strefę pożarową produkcyjną lub magazynową oraz do strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, plac składowy lub wiatę, jeżeli gęstość obciążenia ogniowego wymienionych stref pożarowych przekracza 500 MJ/m2 i zachodzi co najmniej jeden z warunków: a) powierzchnia strefy pożarowej przekracza 1 000 m2, b) występuje pomieszczenie zagrożone wybuchem; 4) budynku zawierającego strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego poniżej 500 MJ/m2 o powierzchni przekraczającej 20 000 m2; […]"}], "534": [{"ref": "§ 245 WT – liczba klatek schodowych w budynkach wysokich", "kind": "akt", "act": "wt", "label": "§ 245", "text": "§ 245. Klatki schodowe przeznaczone do ewakuacji ze strefy pożarowej: 1) ZL II w budynku niskim (N), 2) ZL I, ZL II, ZL III lub ZL V w budynku średniowysokim (SW), 3) PM o gęstości obciążenia ogniowego powyżej 500 MJ/m2 lub zawierającej pomieszczenie zagrożone wybuchem w budynku niskim (N) bądź średniowysokim (SW) – powinny być obudowane i zamykane drzwiami dymoszczelnymi oraz wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu."}], "535": [{"ref": "PKN-CEN/TS 54-14:2020 – dobór czujek płomienia", "kind": "norma"}], "536": [{"ref": "§ 19–20 RPB – instalacja wodociągowa ppoż. w budynkach wysokościowych", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "§ 19. 1. Hydranty 25 muszą być stosowane w strefach pożarowych zakwalifikowanych do kategorii zagrożenia ludzi ZL: 1) na każdej kondygnacji budynku wysokiego i wysokościowego, z wyjątkiem kondygnacji obejmującej wyłącznie strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL IV; […]"}], "537": [{"ref": "§ 278 ust. 1 WT – wyjścia ewakuacyjne ze strefy garażu", "kind": "akt", "act": "wt", "label": "§ 278", "text": "§ 278. 1. Ze strefy pożarowej garażu, która posiada więcej niż 25 stanowisk postojowych i nie jest wyposażona w instalację wentylacji oddymiającej lub ma powierzchnię przekraczającą 1500 m2, należy zapewnić co najmniej dwa wyjścia ewakuacyjne, przy czym jednym z tych wyjść może być wjazd lub wyjazd."}], "538": [{"ref": "PN-B-02877-4:2025-07 – klapy dymowe", "kind": "norma"}], "539": [{"ref": "rozp. dot. wyrobów pirotechnicznych / § 240 WT", "kind": "akt", "act": "wt", "label": "§ 240", "text": "§ 240. 1. Drzwi wieloskrzydłowe, stanowiące wyjście ewakuacyjne z pomieszczenia oraz na drodze ewakuacyjnej, powinny mieć co najmniej jedno, nieblokowane skrzydło drzwiowe o szerokości nie mniejszej niż 0,9 m. 2. Szerokość skrzydła drzwi wahadłowych, stanowiących wyjście ewakuacyjne z pomieszczenia oraz na drodze ewakuacyjnej, powinna wynosić co najmniej dla drzwi jednoskrzydłowych – 0,9 m, a dla drzwi dwuskrzydłowych – 0,6 m, przy czym oba skrzydła drzwi dwuskrzydłowych muszą mieć tę samą szerokość. 3. Zabrania się stosowania do celów ewakuacji drzwi obrotowych i podnoszonych. 4. Drzwi rozsuwane mogą stanowić wyjścia na drogi ewakuacyjne, a także być stosowane na drogach ewakuacyjnych, jeżeli są przeznaczone nie tylko do celów ewakuacji, a ich konstrukcja zapewnia: 1) otwieranie automatyczne i ręczne bez możliwości ich blokowania; […]"}], "540": [{"ref": "§ 19 ust. 3 pkt 2 i ust. 4 RPB – dobór hydrantów wewnętrznych", "kind": "akt", "act": "rpb", "label": "§ 19", "text": "3. Hydranty 52 muszą być stosowane: 1) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 i powierzchni przekraczającej 200 m2; 2) w strefie pożarowej produkcyjnej i magazynowej o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie o powierzchni przekraczającej 100 m2 i gęstości obciążenia ogniowego przekraczającej 1 000 MJ/m2; 3) przy wejściu do pomieszczeń magazynowych lub technicznych o powierzchni przekraczającej 200 m2 i gęstości obciążenia ogniowego przekraczającej 500 MJ/m2, usytuowanych w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL I, ZL II, ZL III lub ZL V, znajdującej się w budynku niskim albo średniowysokim."}], "541": [{"ref": "PN-EN 12845+A1:2020 – tryskacze przyścienne", "kind": "norma"}], "542": [{"ref": "PN-B-02857:2017-04 – przeciwpożarowe zbiorniki wodne", "kind": "norma"}], "544": [{"ref": "§ 261 WT – liczba siedzeń w rzędzie (limit 20 w rzędzie przyściennym)", "kind": "akt", "act": "wt", "label": "§ 261", "text": "§ 261. […] 2) szerokość przejść pomiędzy rzędami siedzeń nie mniejszą niż 0,45 m, przy czym odległość tę należy ustalać, biorąc pod uwagę odstęp między stałymi elementami siedzeń; 3) liczbę siedzeń w rzędzie nie większą niż 16 pomiędzy przejściami oraz 8 w rzędzie przyściennym, przy czym dopuszcza się zwiększenie liczby miejsc w rzędach odpowiednio do 40 i 20 pod warunkiem zwiększenia odstępu między rzędami siedzeń o 1 cm na każde dodatkowe siedzenie odpowiednio powyżej 16 lub 8; 4) szerokość przejść komunikacyjnych nie mniejszą niż 1,2 m przy liczbie osób do 150, a przy większej ich liczbie szerokość tę należy zwiększyć proporcjonalnie o 0,6 m na 100 osób; 5) rzędy siedzeń lub ławek trwale umocowane do podłogi albo siedzenia sztywno łączone ze sobą w rzędy oraz między rzędami."}], "545": [{"ref": "PN-EN 12101-13:2022 – klasy systemów różnicowania ciśnień", "kind": "norma"}], "546": [{"ref": "rozp. dot. sprzedaży materiałów wybuchowych/broni; § 240 WT", "kind": "akt", "act": "wt", "label": "§ 240", "text": "§ 240. […] 5. W bramach i ścianach przesuwanych na drogach ewakuacyjnych powinny znajdować się drzwi otwierane ręcznie albo w bezpośrednim sąsiedztwie tych bram i ścian powinny być umieszczone i wyraźnie oznakowane drzwi przeznaczone do celów ewakuacji. 6. Drzwi, bramy i inne zamknięcia otworów o wymaganej klasie odporności ogniowej lub dymoszczelności powinny być zaopatrzone w urządzenia, zapewniające samoczynne zamykanie otworu w razie pożaru. Należy też zapewnić możliwość ręcznego otwierania drzwi służących do ewakuacji. 7. Drzwi stanowiące wyjście ewakuacyjne z pomieszczenia, w którym może przebywać jednocześnie więcej niż 300 osób, oraz drzwi na drodze ewakuacyjnej z tego pomieszczenia, powinny być wyposażone w urządzenia przeciwpaniczne."}], "548": [{"ref": "§ 37 RPB – ocena zagrożenia wybuchem", "kind": "norma"}], "549": [{"ref": "dyrektywa ATEX – kategorie urządzeń a strefy pyłowe", "kind": "ue"}], "550": [{"ref": "PKN-CEN/TS 54-14:2020 – rozmieszczenie czujek ciepła", "kind": "norma"}], "551": [{"ref": "§ 268 WT – maszynownie wentylacyjne i klimatyzacyjne", "kind": "akt", "act": "wt", "label": "§ 268", "text": "§ 268. […] 2) zamocowania przewodów do elementów budowlanych powinny być wykonane z materiałów niepalnych, zapewniających przejęcie siły powstającej w przypadku pożaru w czasie nie krótszym niż wymagany dla klasy odporności ogniowej przewodu lub klapy odcinającej; 3) w przewodach wentylacyjnych nie należy prowadzić innych instalacji; 4) filtry i tłumiki powinny być zabezpieczone przed przeniesieniem się do ich wnętrza palących się cząstek; 5) maszynownie wentylacyjne i klimatyzacyjne w budynkach mieszkalnych średniowysokich (SW) i wyższych oraz w innych budynkach o wysokości powyżej dwóch kondygnacji nadziemnych powinny być wydzielone ścianami o klasie odporności ogniowej co najmniej E I 60 i zamykane drzwiami o klasie odporności ogniowej co najmniej E I 30; nie dotyczy to obudowy urządzeń instalowanych ponad dachem budynku. 2. […]"}], "552": [{"ref": "§ 12 WT – usytuowanie budynku względem granicy działki", "kind": "akt", "act": "wt", "label": "§ 12", "text": "§ 12. 1. Jeżeli z przepisów § 13, 19, 23, 36, 40, 60 i 271–273 lub przepisów odrębnych określających dopuszczalne odległości niektórych budowli od budynków nie wynikają inne wymagania, budynek na działce budowlanej należy sytuować w odległości od granicy tej działki w odległości nie mniejszej niż: 1) 4 m – w przypadku budynku zwróconego ścianą z oknami lub drzwiami w stronę tej granicy; 2) 3 m – w przypadku budynku zwróconego ścianą bez okien i drzwi w stronę tej granicy. 2. Sytuowanie budynku w przypadku, o którym mowa w ust. 1 pkt 2, dopuszcza się w odległości 1,5 m od granicy lub bezpośrednio przy tej granicy, jeżeli plan miejscowy przewiduje taką możliwość. 3. […]"}], "553": [{"ref": "PN-EN 12845+A1:2020 – dobór temperatury tryskaczy", "kind": "norma"}], "555": [{"ref": "§ 216, § 232 WT – ściany oddzielające mieszkania", "kind": "akt", "act": "wt", "label": "§ 216", "text": "§ 216. 1. Elementy budynku, odpowiednio do jego klasy odporności pożarowej, powinny spełniać, z zastrzeżeniem § 213 oraz § 237 ust. 9, co najmniej wymagania określone w poniższej tabeli: Klasa odporności pożarowej budynku Klasa odporności ogniowej elementów budynku5) *) główna konstrukcja nośna konstrukcja dachu strop1) ściana zewnętrzna1), 2) ściana wewnętrzna1) przekrycie dachu3) 1 2 3 4 5 6 7 „A” R 240 R 30 R E I 120 E I 120 (o↔i) E I 60 R E 30 „B” R 120 R 30 R E I 60 E I 60 (o↔i) E I 304) R E 30 „C” R 60 R 15 R E I 60 E I 30 (o↔i) E I 154) R E 15 „D” R 30 (–) R E I 30 E I 30 (o↔i) (–) (–) „E” (–) (–) (–) (–) (–) (–) *) Z zastrzeżeniem § 219 ust. 1. […]"}], "556": [{"ref": "PKN-CEN/TS 54-14:2020 – promienie działania czujek na dachach spadzistych", "kind": "norma"}], "559": [{"ref": "PN-EN 81-72:2020 – dźwigi dla straży pożarnej", "kind": "norma"}], "560": [{"ref": "§ 5–6 RW – wymagana ilość wody do zewnętrznego gaszenia", "kind": "akt", "act": "rw", "label": "§ 5", "text": "§ 5. 1. Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla budynków użyteczności publicznej i zamieszkania zbiorowego oraz innych obiektów budowlanych o takim przeznaczeniu, służąca do zewnętrznego gaszenia pożaru, wynosi: 1) dla budynku o kubaturze brutto do 5 000 m3 i o powierzchni wewnętrznej do 1 000 m2 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 2) dla budynków niewymienionych w pkt 1 — 20 dm3/s łącznie z co najmniej dwóch hydrantów o średnicy 80 mm lub 200 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym; 3) dla obiektów wymienionych w § 3 ust. 1 pkt 3 — 10 dm3/s z co najmniej jednego hydrantu o średnicy 80 mm lub 100 m3 zapasu wody w przeciwpożarowym zbiorniku wodnym. 2. […]"}], "1001": [{"ref": "§ 306 pkt 2 projektu WT (projekt z 9.06.2025 r.) – instalowanie urządzeń fotowoltaicznych na dachu", "kind": "akt", "act": "wt-projekt", "label": "§ 306", "text": "§ 306. Urządzenie fotowoltaiczne na dachu budynku instaluje się w sposób ograniczający możliwość rozprzestrzeniania się pożaru pomiędzy strefami pożarowymi, przy spełnieniu łącznie następujących warunków: 1) dach, na którym instaluje się urządzenie fotowoltaiczne, jest NRO, a izolacja cieplna przekrycia dachu ma klasę reakcji na ogień inną niż F; 2) urządzenie fotowoltaiczne na dachu budynku instaluje się w sektorze o powierzchni nieprzekraczającej 1600 m2 i o rozpiętości nie większej niż 40 m; 3) między sektorami, o których mowa w pkt 2, jest zachowana odległość co najmniej 5 m; 4) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2,5 m od ściany oddzielenia przeciwpożarowego; warunku nie stosuje się, jeżeli ściana oddzielenia przeciwpożarowego jest wyprowadzona ponad górną krawędź urządzenia fotowoltaicznego, na wysokość co najmniej 0,3 m; […]"}], "1002": [{"ref": "§ 306 pkt 3 projektu WT (projekt z 9.06.2025 r.)", "kind": "akt", "act": "wt-projekt", "label": "§ 306", "text": "§ 306. Urządzenie fotowoltaiczne na dachu budynku instaluje się w sposób ograniczający możliwość rozprzestrzeniania się pożaru pomiędzy strefami pożarowymi, przy spełnieniu łącznie następujących warunków: 1) dach, na którym instaluje się urządzenie fotowoltaiczne, jest NRO, a izolacja cieplna przekrycia dachu ma klasę reakcji na ogień inną niż F; 2) urządzenie fotowoltaiczne na dachu budynku instaluje się w sektorze o powierzchni nieprzekraczającej 1600 m2 i o rozpiętości nie większej niż 40 m; 3) między sektorami, o których mowa w pkt 2, jest zachowana odległość co najmniej 5 m; 4) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2,5 m od ściany oddzielenia przeciwpożarowego; warunku nie stosuje się, jeżeli ściana oddzielenia przeciwpożarowego jest wyprowadzona ponad górną krawędź urządzenia fotowoltaicznego, na wysokość co najmniej 0,3 m; […]"}], "1003": [{"ref": "§ 306 pkt 4 projektu WT (projekt z 9.06.2025 r.)", "kind": "akt", "act": "wt-projekt", "label": "§ 306", "text": "§ 306. […] 2) urządzenie fotowoltaiczne na dachu budynku instaluje się w sektorze o powierzchni nieprzekraczającej 1600 m2 i o rozpiętości nie większej niż 40 m; 3) między sektorami, o których mowa w pkt 2, jest zachowana odległość co najmniej 5 m; 4) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2,5 m od ściany oddzielenia przeciwpożarowego; warunku nie stosuje się, jeżeli ściana oddzielenia przeciwpożarowego jest wyprowadzona ponad górną krawędź urządzenia fotowoltaicznego, na wysokość co najmniej 0,3 m; 5) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2 m od urządzenia służących do usuwania dymu."}], "1004": [{"ref": "§ 306 pkt 5 projektu WT (projekt z 9.06.2025 r.)", "kind": "akt", "act": "wt-projekt", "label": "§ 306", "text": "§ 306. […] 2) urządzenie fotowoltaiczne na dachu budynku instaluje się w sektorze o powierzchni nieprzekraczającej 1600 m2 i o rozpiętości nie większej niż 40 m; 3) między sektorami, o których mowa w pkt 2, jest zachowana odległość co najmniej 5 m; 4) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2,5 m od ściany oddzielenia przeciwpożarowego; warunku nie stosuje się, jeżeli ściana oddzielenia przeciwpożarowego jest wyprowadzona ponad górną krawędź urządzenia fotowoltaicznego, na wysokość co najmniej 0,3 m; 5) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2 m od urządzenia służących do usuwania dymu."}], "1005": [{"ref": "§ 307 pkt 2 projektu WT (projekt z 9.06.2025 r.)", "kind": "akt", "act": "wt-projekt", "label": "§ 307", "text": "§ 307. Urządzenie fotowoltaiczne na ścianie zewnętrznej budynku instaluje się w sposób ograniczający możliwość rozprzestrzeniania się pożaru pomiędzy kondygnacjami, przy spełnieniu łącznie następujących warunków: 1) ściana zewnętrzna, na której instaluje się urządzenie fotowoltaiczne ma klasę odporności ogniowej co najmniej EI 30 oraz jest NRO, a izolacja cieplna tej ściany ma klasę reakcji na ogień inną niż F; 2) urządzenie fotowoltaiczne instaluje się na wysokości nie większej niż 25 m od poziomu terenu; 3) urządzenie fotowoltaiczne instaluje się w odległości co najmniej 2 m od otworów okiennych, drzwiowych lub innych, umożliwiających rozprzestrzenianie się ognia, niezamkniętych zamknięciami przeciwpożarowymi, o klasie odporności ogniowej EI ściany zewnętrznej, na której są zainstalowane te urządzenia; […]"}], "1006": [{"ref": "§ 308 projektu WT (projekt z 9.06.2025 r.) – urządzenia fotowoltaiczne zintegrowane z budynkiem", "kind": "akt", "act": "wt-projekt", "label": "§ 308", "text": "§ 308. 1. Urządzenia fotowoltaiczne mogą być zintegrowane z budynkiem i stanowić jego ścianę zewnętrzną lub dach, jeżeli znajdują się na wysokości nie większej niż 25 m od poziomu terenu. 2. Dopuszcza się wykonanie urządzenia fotowoltaicznego, o których mowa w ust. 1, na wysokości powyżej 25 m, jeżeli budynek jest wyposażony w stałe samoczynne urządzenia gaśnicze wodne."}], "1007": [{"ref": "§ 305 ust. 1 i 2 projektu WT (projekt z 9.06.2025 r.) – usytuowanie falownika", "kind": "akt", "act": "wt-projekt", "label": "§ 305", "text": "§ 305. 1. Falownik umieszcza się na zewnątrz budynku lub w pomieszczeniu nieprzeznaczonym na pobyt ludzi, w odległości co najmniej 2 m od elementu budynku wykonanego z materiałów o klasie reakcji na ogień innej niż A1 lub A2, d0, w miejscu zapewniającym odpowiednią wentylację."}], "1008": [{"ref": "§ 303 ust. 1 i 2 projektu WT (projekt z 9.06.2025 r.) – prowadzenie przewodów DC", "kind": "akt", "act": "wt-projekt", "label": "§ 303", "text": "§ 303. 1. Przewód instalacji elektrycznej z urządzeniami fotowoltaicznymi, zwanej dalej „instalacją fotowoltaiczną”, po stronie prądu stałego prowadzi się na zewnątrz budynku."}], "1009": [{"ref": "§ 305 ust. 3 projektu WT (projekt z 9.06.2025 r.)", "kind": "akt", "act": "wt-projekt", "label": "§ 305", "text": "3. Instalację fotowoltaiczną wyposaża się w co najmniej następujące środki ochrony: 1) urządzenie do monitorowania stanu izolacji po stronie prądu stałego; 2) urządzenie do wykrywania zwarć łukowych."}], "1010": [{"ref": "§ 311 ust. 2 projektu WT (projekt z 9.06.2025 r.) – magazyny energii, progi detekcji", "kind": "akt", "act": "wt-projekt", "label": "§ 311", "text": "2. Urządzenia detekcyjne po przekroczeniu stężenia progowego: 1) 10 % dolnej granicy wybuchowości – mają uruchamiać sygnalizację alarmową i wentylację zapewniającą dwukrotne zwiększenie liczby wymian powietrza, w stosunku do liczby wymian powietrza w warunkach normalnej pracy; 2) 30 % dolnej granicy wybuchowości – mają odłączać akumulatory od źródeł zasilania do czasu rozcieńczenia atmosfery poniżej dopuszczalnego stężenia gazu."}], "1011": [{"ref": "§ 311 ust. 2 pkt 2 projektu WT (projekt z 9.06.2025 r.)", "kind": "akt", "act": "wt-projekt", "label": "§ 311", "text": "2. Urządzenia detekcyjne po przekroczeniu stężenia progowego: 1) 10 % dolnej granicy wybuchowości – mają uruchamiać sygnalizację alarmową i wentylację zapewniającą dwukrotne zwiększenie liczby wymian powietrza, w stosunku do liczby wymian powietrza w warunkach normalnej pracy; 2) 30 % dolnej granicy wybuchowości – mają odłączać akumulatory od źródeł zasilania do czasu rozcieńczenia atmosfery poniżej dopuszczalnego stężenia gazu."}], "1012": [{"ref": "§ 310 ust. 1–3 projektu WT (projekt z 9.06.2025 r.) – wyłącznik awaryjny magazynu energii", "kind": "akt", "act": "wt-projekt", "label": "§ 310", "text": "§ 310. 1. Budynek, w którym jednym ze źródeł energii elektrycznej jest akumulatorowy system magazynowania energii elektrycznej, wyposaża się w przeznaczony do użycia przez ekipy ratownicze wyłącznik awaryjny, odłączający ten system od wszystkich obwodów wejściowych i wyjściowych."}], "1013": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego i dopuszczalne powiększenia", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. 1. W pomieszczeniach, od najdalszego miejsca, w którym może przebywać człowiek, do wyjścia ewakuacyjnego na drogę ewakuacyjną lub do innej strefy pożarowej albo na zewnątrz budynku, powinno być zapewnione przejście, zwane dalej „przejściem ewakuacyjnym”, o długości nieprzekraczającej: 1) w strefach pożarowych ZL – 40 m; 2) w strefach pożarowych PM o gęstości obciążenia ogniowego przekraczającej 500 MJ/m2 w budynku o więcej niż jednej kondygnacji nadziemnej – 75 m; 3) w strefach pożarowych PM, o obciążeniu ogniowym nieprzekraczającym 500 MJ/m2, w budynku o więcej niż jednej kondygnacji nadziemnej oraz w strefach pożarowych PM w budynku o jednej kondygnacji nadziemnej bez względu na wielkość obciążenia ogniowego – 100 m. 2. W pomieszczeniu zagrożonym wybuchem długość przejścia ewakuacyjnego, o którym mowa w ust. 1 pkt 2 i 3, nie powinna przekraczać 40 m. 3. […]"}], "1014": [{"ref": "§ 237 WT – długość przejścia ewakuacyjnego", "kind": "akt", "act": "wt", "label": "§ 237", "text": "§ 237. […] 3. Dopuszcza się prowadzenie przez pomieszczenie zagrożone wybuchem przejścia ewakuacyjnego z innego pomieszczenia, jeżeli pomieszczenia te są powiązane funkcjonalnie. 4. Jeżeli z przewidywanego przeznaczenia pomieszczenia nie wynika jednoznacznie sposób jego zagospodarowania, projektowa długość przejścia ewakuacyjnego nie może być większa niż 80% długości określonej w ust. 1 i 2. 5. W pomieszczeniach o wysokości przekraczającej 5 m długość przejść, o których mowa w ust. 1 i 2, może być powiększona o 25%. 6. Długości przejść, o których mowa w ust. 1 i 2, mogą być powiększone pod warunkiem zastosowania: 1) stałych samoczynnych urządzeń gaśniczych wodnych – o 50%; 2) samoczynnych urządzeń oddymiających uruchamianych za pomocą systemu wykrywania dymu – o 50%. 7. Powiększenia, o których mowa w ust. 5 i 6 pkt 1 i 2, podlegają sumowaniu. 8. […]"}], "1015": [{"ref": "§ 239 WT – szerokość drzwi stanowiących wyjścia ewakuacyjne", "kind": "akt", "act": "wt", "label": "§ 239", "text": "§ 239. 1. Łączną szerokość drzwi w świetle, stanowiących wyjścia ewakuacyjne z pomieszczenia, należy obliczać proporcjonalnie do liczby osób mogących przebywać w nim równocześnie, przyjmując co najmniej 0,6 m szerokości na 100 osób, przy czym najmniejsza szerokość drzwi w świetle ościeżnicy powinna wynosić 0,9 m, a w przypadku drzwi służących do ewakuacji do 3 osób – 0,8 m. 2. Drzwi stanowiące wyjście ewakuacyjne powinny otwierać się na zewnątrz pomieszczeń: 1) zagrożonych wybuchem; 2) do których jest możliwe niespodziewane przedostanie się mieszanin wybuchowych lub substancji trujących, duszących bądź innych, mogących utrudnić ewakuację; 3) przeznaczonych do jednoczesnego przebywania ponad 50 osób; 4) przeznaczonych dla ponad 6 osób o ograniczonej zdolności poruszania się. 3. […]"}], "1016": [{"ref": "§ 12 RW – parametry drogi pożarowej (promień zewnętrznej krawędzi łuku)", "kind": "akt", "act": "rw", "label": "§ 12", "text": "§ 12. […] 9. Droga pożarowa powinna zapewniać przejazd bez cofania lub powinna być zakończona placem manewrowym o wymiarach 20 m x 20 m, względnie można przewidzieć inne rozwiązania umożliwiające zawrócenie pojazdu, z zastrzeżeniem ust. 10. 10. Dopuszcza się wykonanie odcinka drogi pożarowej o długości nie większej niż 15 m, z którego wyjazd jest możliwy jedynie przez cofanie pojazdu. 11. Najmniejszy promień zewnętrznego łuku drogi pożarowej nie może wynosić mniej niż 11 m. 12. Drogi pożarowe oraz place manewrowe w miejscach innych niż wymienione w ust. 2 i 3 mogą być usytuowane w odległości mniejszej niż 5 m od chronionego budynku, pod warunkiem że ściana zewnętrzna budynku na tym odcinku oraz w odległości do 5 m od niego posiada klasę odporności ogniowej wymaganą dla ściany oddzielenia pożarowego tego budynku."}], "1017": [{"ref": "PN-EN 1838 – oświetlenie awaryjne, czasy osiągania natężenia", "kind": "norma"}], "1018": [{"ref": "§ 2 RPB – definicja materiałów niebezpiecznych pożarowo", "kind": "akt", "act": "rpb", "label": "§ 2", "text": "§ 2. 1. Ilekroć w rozporządzeniu jest mowa o: 1) materiałach niebezpiecznych pożarowo ‒ należy przez to rozumieć: a) gazy palne, b) ciecze palne o temperaturze zapłonu poniżej 328,15 K (55ºC), c) materiały wytwarzające w zetknięciu z wodą gazy palne, d) materiały zapalające się samorzutnie na powietrzu, e) materiały wybuchowe i wyroby pirotechniczne, f) materiały ulegające samorzutnemu rozkładowi lub polimeryzacji, g) materiały mające skłonności do samozapalenia, h) materiały inne niż wymienione w lit. a‒g, jeśli sposób ich składowania, przetwarzania lub innego wykorzystania może spowodować powstanie pożaru; 2) pasie przeciwpożarowym ‒ należy przez to rozumieć system drzewostanów różnej szerokości poddanych specjalnym zabiegom gospodarczym i porządkowym lub powierzchni wylesionych i oczyszczonych do warstwy mineralnej; […]"}], "1019": [{"ref": "§ 37 RPB – ocena zagrożenia wybuchem i wyznaczanie stref", "kind": "norma"}], "1020": [{"ref": "dyrektywa ATEX 2014/34/UE – kategorie urządzeń a strefy zagrożenia wybuchem", "kind": "ue"}], "1021": [{"ref": "PN-EN 12845 – wydatek tryskacza (współczynnik wypływu K)", "kind": "norma"}], "1022": [{"ref": "§ 256 WT – podział korytarzy stanowiących drogi ewakuacyjne", "kind": "akt", "act": "wt", "label": "§ 256", "text": "§ 256. 1. Długość drogi ewakuacyjnej od wyjścia z pomieszczenia na tę drogę do wyjścia do innej strefy pożarowej lub na zewnątrz budynku, zwanej dalej „dojściem ewakuacyjnym”, mierzy się wzdłuż osi drogi ewakuacyjnej. W przypadku zakończenia dojścia ewakuacyjnego przedsionkiem przeciwpożarowym, długość tę mierzy się do pierwszych drzwi tego przedsionka. 2. Za równorzędne wyjściu do innej strefy pożarowej, o którym mowa w ust. 1, uważa się wyjście do obudowanej klatki schodowej, zamykanej drzwiami o klasie odporności ogniowej co najmniej E I 30, wyposażonej w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, a w przypadku, o którym mowa w § 246 ust. 5 – zamykanej drzwiami dymoszczelnymi. 3. […]"}], "1023": [{"ref": "§ 6–9 RW / PN-B-02857 – zapas wody (wzór obliczeniowy nie jest podany wprost w rozporządzeniu)", "kind": "norma"}], "1024": [{"ref": "§ 236 WT – kierunek otwierania drzwi ewakuacyjnych", "kind": "akt", "act": "wt", "label": "§ 236", "text": "§ 236. 1. Z pomieszczeń przeznaczonych na pobyt ludzi powinna być zapewniona możliwość ewakuacji w bezpieczne miejsce na zewnątrz budynku lub do sąsiedniej strefy pożarowej, bezpośrednio albo drogami komunikacji ogólnej, zwanymi dalej „drogami ewakuacyjnymi”. 2. Ze strefy pożarowej, o której mowa w ust. 1, powinno być wyjście bezpośrednio na zewnątrz budynku lub przez inną strefę pożarową, z zastrzeżeniem § 227 ust. 5. 3. Wyjścia z pomieszczeń na drogi ewakuacyjne powinny być zamykane drzwiami. 4. Drzwi stanowiące wyjście ewakuacyjne z budynku przeznaczonego dla więcej niż 50 osób powinny otwierać się na zewnątrz. Wymaganie to nie dotyczy budynku wpisanego do rejestru zabytków. 5. W wyjściu ewakuacyjnym z budynku dopuszcza się stosowanie drzwi rozsuwanych spełniających wymagania określone w § 240 ust. 4. 6. […]"}]};
